/* AudioWorklet: batches microphone audio into ~100 ms Float32 blocks and posts them to the main thread.
 * Plain JS on purpose (loaded by URL with audioWorklet.addModule). */
class TalkKwsCapture extends AudioWorkletProcessor {
  constructor() {
    super();
    // Fixed once: after a block is TRANSFERRED its array is detached and reports length 0, so the size of the
    // next block must never be read from the old one (that made a zero-length block and an endless post loop).
    this.size = Math.round(sampleRate / 10);
    this.block = new Float32Array(this.size);
    this.filled = 0;
  }

  process(inputs) {
    const channel = inputs[0] && inputs[0][0];
    if (!channel) return true;
    let offset = 0;
    while (offset < channel.length) {
      const n = Math.min(channel.length - offset, this.block.length - this.filled);
      this.block.set(channel.subarray(offset, offset + n), this.filled);
      this.filled += n;
      offset += n;
      if (this.filled === this.block.length) {
        const full = this.block;
        this.port.postMessage({ sampleRate, samples: full }, [full.buffer]);
        this.block = new Float32Array(this.size);
        this.filled = 0;
      }
    }
    return true;
  }
}

registerProcessor('talk-kws-capture', TalkKwsCapture);

/* Classic Web Worker hosting the sherpa-onnx keyword spotter.
 * Plain JS on purpose: the host page loads it by URL next to the wasm, so it must not go through a bundler.
 * Protocol — in:  {type:'init', keywords, threshold, score} | {type:'audio', sampleRate, samples} | {type:'reset'}
 *            out: {type:'ready'} | {type:'inited'} | {type:'keyword', keyword} | {type:'fatal', message}
 * unhandledrejection/error listeners: the glue preloads sherpa-onnx-wasm-kws-main.data through an async
 * function invoked fire-and-forget (no .then/.catch attached), so a failed fetch (404, network error) rejects
 * with nothing to catch it — onAbort alone only covers the wasm-binary path, not this one — and without these
 * listeners the worker would emit neither 'ready' nor 'fatal' and just go silent. */
'use strict';

var spotter = null;
var stream = null;

function fatal(e) {
  self.postMessage({ type: 'fatal', message: String(e && e.message ? e.message : e) });
}

self.addEventListener('unhandledrejection', function (ev) { fatal(ev.reason); });
self.addEventListener('error', function (ev) { fatal(ev.message || ev.error || 'worker error'); });

// The emscripten glue is a plain script that reads a global Module.
self.Module = {
  onRuntimeInitialized: function () { self.postMessage({ type: 'ready' }); },
  onAbort: fatal,
};

try {
  importScripts('sherpa-onnx-kws.js', 'sherpa-onnx-wasm-kws-main.js');
} catch (e) {
  fatal(e);
}

// createKws REPLACES its defaults when given a config, so every field must be present.
function spotterConfig(m) {
  var stem = '-epoch-12-avg-2-chunk-16-left-64.onnx';
  return {
    featConfig: { samplingRate: 16000, featureDim: 80 },
    modelConfig: {
      transducer: { encoder: './encoder' + stem, decoder: './decoder' + stem, joiner: './joiner' + stem },
      tokens: './tokens.txt', provider: 'cpu', modelType: '', numThreads: 1, debug: 0,
      modelingUnit: 'cjkchar', bpeVocab: '',
    },
    maxActivePaths: 4, numTrailingBlanks: 1,
    keywordsScore: m.score, keywordsThreshold: m.threshold, keywords: m.keywords,
  };
}

self.onmessage = function (ev) {
  var m = ev.data;
  try {
    if (m.type === 'init') {
      if (stream) { stream.free(); stream = null; }
      if (spotter) { spotter.free(); spotter = null; }
      spotter = createKws(self.Module, spotterConfig(m));
      stream = spotter.createStream();
      self.postMessage({ type: 'inited' });
    } else if (m.type === 'audio') {
      if (!stream) return;
      stream.acceptWaveform(m.sampleRate, m.samples);
      while (spotter.isReady(stream)) {
        spotter.decode(stream);
        var r = spotter.getResult(stream);
        if (r.keyword) {
          self.postMessage({ type: 'keyword', keyword: r.keyword });
          // A hit only has to clear the decoder's matched path so the same wake word can be spotted
          // again; spotter.reset() does exactly that and keeps the stream's feature history, which
          // is what lets detection continue mid-audio. The 'reset' message below is a different
          // job — see there.
          spotter.reset(stream);
        }
      }
    } else if (m.type === 'reset') {
      // drop whatever was half-heard before a pause, so it cannot complete a match after resume.
      // That needs the feature history GONE, not just the decoder's path cleared, so this frees the
      // stream and makes a new one instead of using the light spotter.reset() above.
      if (spotter && stream) { stream.free(); stream = spotter.createStream(); }
    }
  } catch (e) {
    fatal(e);
  }
};

function freeConfig(config, Module) {
  if ('buffer' in config) {
    Module._free(config.buffer);
  }

  if ('transducer' in config) {
    freeConfig(config.transducer, Module);
  }

  if ('featConfig' in config) {
    freeConfig(config.featConfig, Module);
  }

  if ('modelConfig' in config) {
    freeConfig(config.modelConfig, Module);
  }

  if ('keywordsBuffer' in config) {
    Module._free(config.keywordsBuffer);
  }

  Module._free(config.ptr);
}


function initSherpaOnnxOnlineTransducerModelConfig(config, Module) {
  const encoderLen = Module.lengthBytesUTF8(config.encoder) + 1;
  const decoderLen = Module.lengthBytesUTF8(config.decoder) + 1;
  const joinerLen = Module.lengthBytesUTF8(config.joiner) + 1;

  const n = encoderLen + decoderLen + joinerLen;

  const buffer = Module._malloc(n);

  const len = 3 * 4;  // 3 pointers
  const ptr = Module._malloc(len);

  let offset = 0;
  Module.stringToUTF8(config.encoder, buffer + offset, encoderLen);
  offset += encoderLen;

  Module.stringToUTF8(config.decoder, buffer + offset, decoderLen);
  offset += decoderLen;

  Module.stringToUTF8(config.joiner, buffer + offset, joinerLen);

  offset = 0;
  Module.setValue(ptr, buffer + offset, 'i8*');
  offset += encoderLen;

  Module.setValue(ptr + 4, buffer + offset, 'i8*');
  offset += decoderLen;

  Module.setValue(ptr + 8, buffer + offset, 'i8*');

  return {
    buffer: buffer,
    ptr: ptr,
    len: len,
  };
}

// The user should free the returned pointers
function initModelConfig(config, Module) {
  if (!('tokensBuf' in config)) {
    config.tokensBuf = '';
  }

  if (!('tokensBufSize' in config)) {
    config.tokensBufSize = 0;
  }

  const transducer =
      initSherpaOnnxOnlineTransducerModelConfig(config.transducer, Module);
  const paraformer_len = 2 * 4
  const zipfomer2_ctc_len = 1 * 4
  const nemo_ctc_len = 1 * 4
  const t_one_ctc_len = 1 * 4

  const len = transducer.len + paraformer_len + zipfomer2_ctc_len + 9 * 4 +
      nemo_ctc_len + t_one_ctc_len;

  const ptr = Module._malloc(len);
  Module.HEAPU8.fill(0, ptr, ptr + len);

  let offset = 0;
  Module._CopyHeap(transducer.ptr, transducer.len, ptr + offset);

  const tokensLen = Module.lengthBytesUTF8(config.tokens) + 1;
  const providerLen = Module.lengthBytesUTF8(config.provider || 'cpu') + 1;
  const modelTypeLen = Module.lengthBytesUTF8(config.modelType || '') + 1;
  const modelingUnitLen = Module.lengthBytesUTF8(config.modelingUnit || '') + 1;
  const bpeVocabLen = Module.lengthBytesUTF8(config.bpeVocab || '') + 1;
  const tokensBufLen = Module.lengthBytesUTF8(config.tokensBuf || '') + 1;
  const bufferLen = tokensLen + providerLen + modelTypeLen + modelingUnitLen +
      bpeVocabLen + tokensBufLen;
  const buffer = Module._malloc(bufferLen);

  offset = 0;
  Module.stringToUTF8(config.tokens, buffer, tokensLen);
  offset += tokensLen;

  Module.stringToUTF8(config.provider || 'cpu', buffer + offset, providerLen);
  offset += providerLen;

  Module.stringToUTF8(config.modelType || '', buffer + offset, modelTypeLen);
  offset += modelTypeLen;

  Module.stringToUTF8(
      config.modelingUnit || '', buffer + offset, modelingUnitLen);
  offset += modelingUnitLen;

  Module.stringToUTF8(config.bpeVocab || '', buffer + offset, bpeVocabLen);
  offset += bpeVocabLen;

  Module.stringToUTF8(config.tokensBuf || '', buffer + offset, tokensBufLen);
  offset += tokensBufLen;

  offset = transducer.len + paraformer_len + zipfomer2_ctc_len;
  Module.setValue(ptr + offset, buffer, 'i8*');  // tokens
  offset += 4;

  Module.setValue(ptr + offset, config.numThreads || 1, 'i32');
  offset += 4;

  Module.setValue(ptr + offset, buffer + tokensLen, 'i8*');  // provider
  offset += 4;

  Module.setValue(ptr + offset, config.debug, 'i32');
  offset += 4;

  Module.setValue(
      ptr + offset, buffer + tokensLen + providerLen, 'i8*');  // modelType
  offset += 4;

  Module.setValue(
      ptr + offset, buffer + tokensLen + providerLen + modelTypeLen,
      'i8*');  // modelingUnit
  offset += 4;

  Module.setValue(
      ptr + offset,
      buffer + tokensLen + providerLen + modelTypeLen + modelingUnitLen,
      'i8*');  // bpeVocab
  offset += 4;

  Module.setValue(
      ptr + offset,
      buffer + tokensLen + providerLen + modelTypeLen + modelingUnitLen +
          bpeVocabLen,
      'i8*');  // tokens_buf
  offset += 4;

  Module.setValue(ptr + offset, config.tokensBufSize || 0, 'i32');
  offset += 4;
  // skip nemo_ctc and t_one_ctc

  return {buffer: buffer, ptr: ptr, len: len, transducer: transducer};
}

function initFeatureExtractorConfig(config, Module) {
  let ptr = Module._malloc(4 * 2);
  Module.setValue(ptr, config.samplingRate || 16000, 'i32');
  Module.setValue(ptr + 4, config.featureDim || 80, 'i32');
  return {
    ptr: ptr,
    len: 8,
  };
}

function initKwsConfig(config, Module) {
  if (!('featConfig' in config)) {
    config.featConfig = {
      sampleRate: 16000,
      featureDim: 80,
    };
  }

  if (!('keywordsBuf' in config)) {
    config.keywordsBuf = '';
  }

  if (!('keywordsBufSize' in config)) {
    config.keywordsBufSize = 0;
  }

  let featConfig = initFeatureExtractorConfig(config.featConfig, Module);

  let modelConfig = initModelConfig(config.modelConfig, Module);
  let numBytes = featConfig.len + modelConfig.len + 4 * 7;

  let ptr = Module._malloc(numBytes);
  let offset = 0;
  Module._CopyHeap(featConfig.ptr, featConfig.len, ptr + offset);
  offset += featConfig.len;

  Module._CopyHeap(modelConfig.ptr, modelConfig.len, ptr + offset)
  offset += modelConfig.len;

  Module.setValue(ptr + offset, config.maxActivePaths || 4, 'i32');
  offset += 4;

  Module.setValue(ptr + offset, config.numTrailingBlanks || 1, 'i32');
  offset += 4;

  Module.setValue(ptr + offset, config.keywordsScore || 1.0, 'float');
  offset += 4;

  Module.setValue(ptr + offset, config.keywordsThreshold || 0.25, 'float');
  offset += 4;

  let keywordsLen = Module.lengthBytesUTF8(config.keywords) + 1;
  let keywordsBufLen = Module.lengthBytesUTF8(config.keywordsBuf) + 1;

  let keywordsBuffer = Module._malloc(keywordsLen + keywordsBufLen);
  Module.stringToUTF8(config.keywords, keywordsBuffer, keywordsLen);
  Module.stringToUTF8(
      config.keywordsBuf, keywordsBuffer + keywordsLen, keywordsBufLen);

  Module.setValue(ptr + offset, keywordsBuffer, 'i8*');
  offset += 4;

  Module.setValue(ptr + offset, keywordsBuffer + keywordsLen, 'i8*');
  offset += 4;

  Module.setValue(ptr + offset, config.keywordsBufSize, 'i32');
  offset += 4;

  return {
    ptr: ptr,
    len: numBytes,
    featConfig: featConfig,
    modelConfig: modelConfig,
    keywordsBuffer: keywordsBuffer
  };
}

class Stream {
  constructor(handle, Module) {
    this.handle = handle;
    this.pointer = null;
    this.n = 0;
    this.Module = Module;
  }

  free() {
    if (this.handle) {
      this.Module._SherpaOnnxDestroyOnlineStream(this.handle);
      this.handle = null;
      this.Module._free(this.pointer);
      this.pointer = null;
      this.n = 0;
    }
  }

  /**
   * @param sampleRate {Number}
   * @param samples {Float32Array} Containing samples in the range [-1, 1]
   */
  acceptWaveform(sampleRate, samples) {
    if (this.n < samples.length) {
      this.Module._free(this.pointer);
      this.pointer =
          this.Module._malloc(samples.length * samples.BYTES_PER_ELEMENT);
      this.n = samples.length
    }

    this.Module.HEAPF32.set(samples, this.pointer / samples.BYTES_PER_ELEMENT);
    this.Module._SherpaOnnxOnlineStreamAcceptWaveform(
        this.handle, sampleRate, this.pointer, samples.length);
  }

  inputFinished() {
    this.Module._SherpaOnnxOnlineStreamInputFinished(this.handle);
  }
};

class Kws {
  constructor(configObj, Module) {
    this.config = configObj;
    let config = initKwsConfig(configObj, Module)
    let handle = Module._SherpaOnnxCreateKeywordSpotter(config.ptr);

    freeConfig(config, Module);

    this.handle = handle;
    this.Module = Module;
  }

  free() {
    this.Module._SherpaOnnxDestroyKeywordSpotter(this.handle);
    this.handle = 0
  }

  createStream() {
    let handle = this.Module._SherpaOnnxCreateKeywordStream(this.handle);
    return new Stream(handle, this.Module);
  }

  isReady(stream) {
    return this.Module._SherpaOnnxIsKeywordStreamReady(
               this.handle, stream.handle) == 1;
  }

  decode(stream) {
    this.Module._SherpaOnnxDecodeKeywordStream(this.handle, stream.handle);
  }

  reset(stream) {
    this.Module._SherpaOnnxResetKeywordStream(this.handle, stream.handle);
  }

  getResult(stream) {
    let r = this.Module._SherpaOnnxGetKeywordResult(this.handle, stream.handle);
    let jsonPtr = this.Module.getValue(r + 24, 'i8*');
    let json = this.Module.UTF8ToString(jsonPtr);
    this.Module._SherpaOnnxDestroyKeywordResult(r);
    return JSON.parse(json);
  }
}

function createKws(Module, myConfig) {
  let transducerConfig = {
    encoder: './encoder-epoch-12-avg-2-chunk-16-left-64.onnx',
    decoder: './decoder-epoch-12-avg-2-chunk-16-left-64.onnx',
    joiner: './joiner-epoch-12-avg-2-chunk-16-left-64.onnx',
  };
  let modelConfig = {
    transducer: transducerConfig,
    tokens: './tokens.txt',
    provider: 'cpu',
    modelType: '',
    numThreads: 1,
    debug: 1,
    modelingUnit: 'cjkchar',
    bpeVocab: '',
  };

  let featConfig = {
    samplingRate: 16000,
    featureDim: 80,
  };

  let configObj = {
    featConfig: featConfig,
    modelConfig: modelConfig,
    maxActivePaths: 4,
    numTrailingBlanks: 1,
    keywordsScore: 1.0,
    keywordsThreshold: 0.25,
    keywords: 'x iǎo ài t óng x ué @小爱同学\n' +
        'j ūn g ē n iú b ī @军哥牛逼'
  };

  if (myConfig) {
    configObj = myConfig;
  }
  return new Kws(configObj, Module);
}

if (typeof process == 'object' && typeof process.versions == 'object' &&
    typeof process.versions.node == 'string') {
  module.exports = {
    createKws,
  };
}

// dsh-voice-hub build: esbuild-based, replicating the official tsdown.client.ts
// artifact shape for the client half; the host half is a plain ESM bundle
// with native runtime deps (sherpa-onnx) external.

import { build } from 'esbuild'
import { mkdirSync, readFileSync, renameSync, writeFileSync, mkdtempSync, copyFileSync, cpSync, symlinkSync, rmSync } from 'node:fs'
import { execSync } from 'node:child_process'
import { tmpdir } from 'node:os'
import { join } from 'node:path'

import { WorkspaceAnalyzer, FaceModelEmitter } from '@deepseek-ai/dsh-typert-generator'

const PKG_ID = '@aisoc/dsh-voice-hub'

// 构建版本号：git 短哈希（进入语音模式时打到控制台，供确认运行版本）。
const pluginVersion = JSON.parse(readFileSync('package.json', 'utf8')).version
let BUILD_TAG = `${pluginVersion}+unknown`
try {
  const hash = execSync('git rev-parse --short HEAD', { encoding: 'utf8' }).trim()
  const dirty = execSync('git status --porcelain -- .', { encoding: 'utf8' }).trim() !== ''
  BUILD_TAG = `${pluginVersion}+${hash}${dirty ? '-dirty' : ''}`
} catch {
  // 非 git 环境：保持 unknown
}

/**
 * 原子构建：先写 `lib/.tmp-*` 再 rename 覆盖成品。
 * 直接覆盖成品文件存在窗口：运行中的 dsh 若恰在此时重建合成子进程（崩溃重试/
 * 引擎切换）会 fork 到写了一半的脚本；用户刷新网页也可能拿到半成品 client.js。
 */
async function buildAtomically(opts) {
  const tmp = join('lib', `.tmp-${opts.outfile.split('/').pop()}-${process.pid}`)
  await build({ ...opts, outfile: tmp })
  renameSync(tmp, opts.outfile)
}

const PLATFORM_EXTERNALS = [
  'react',
  'react/jsx-runtime',
  'react-dom',
  'react-dom/client',
  '@deepseek-ai/cordis',
  '@deepseek-ai/dsh-client-ui-slots',
  '@deepseek-ai/dsh-client-web-react',
  '@deepseek-ai/dsh-client-ui-primitives',
  '@deepseek-ai/dsh-client-ui-attachment',
  '@deepseek-ai/dsh-client-schema-form',
]

mkdirSync('lib', { recursive: true })
// 从唯一的 TypeScript Remote 声明生成契约；typecheck 随后检查两端。
// 官方生成器只识别 packages/ 项目，临时工作区仅用于读取当前 Remote 声明。
const workspace = mkdtempSync(join(tmpdir(), 'voice-typert-'))
try {
  const project = join(workspace, 'packages/voice')
  const protocol = join(workspace, 'packages/protocol')
  mkdirSync(protocol, { recursive: true })
  cpSync('node_modules/@deepseek-ai/dsh-typert-protocol/lib/types', join(protocol, 'types'), { recursive: true })
  writeFileSync(join(protocol, 'package.json'), JSON.stringify({ name: '@deepseek-ai/dsh-typert-protocol', exports: {} }))
  writeFileSync(join(protocol, 'tsconfig.json'), JSON.stringify({ include: ['types/**/*.d.ts'] }))
  symlinkSync(join(process.cwd(), 'node_modules'), join(workspace, 'node_modules'), 'dir')
  mkdirSync(join(project, 'src'), { recursive: true })
  copyFileSync('src/voice-remote.ts', join(project, 'src/voice-remote.ts'))
  const manifest = JSON.parse(readFileSync('package.json', 'utf8'))
  manifest.exports = { './voice-remote': manifest.exports['./voice-remote'] }
  writeFileSync(join(project, 'package.json'), JSON.stringify(manifest))
  symlinkSync(join(process.cwd(), 'node_modules'), join(project, 'node_modules'), 'dir')
  const config = JSON.parse(readFileSync('tsconfig.json', 'utf8'))
  config.include = ['src/voice-remote.ts']
  config.compilerOptions.paths = { '@deepseek-ai/dsh-typert-protocol': [join(protocol, 'types/index.d.ts')] }
  writeFileSync(join(project, 'tsconfig.json'), JSON.stringify(config))
  writeFileSync(join(workspace, 'tsconfig.host.json'), JSON.stringify({ compilerOptions: config.compilerOptions, references: [{ path: './packages/voice' }, { path: './packages/protocol' }] }))
  const model = new WorkspaceAnalyzer({ root: workspace, packages: [PKG_ID], faces: ['host'], checkDiagnostics: false }).analyze()
  const artifact = new FaceModelEmitter(model.faces[0]).emit(PKG_ID)
  if (!artifact.remote) throw new Error('未生成语音 Remote 契约')
  writeFileSync('lib/typert.host.js', artifact.js)
  writeFileSync('lib/typert.host.d.ts', artifact.dts)
  writeFileSync('lib/typert.remote-client.js', artifact.remote.js)
  writeFileSync('lib/typert.remote-client.d.ts', artifact.remote.dts)
} finally {
  rmSync(workspace, { recursive: true, force: true })
}


// Edge TTS 作为 CJS 单独打包：DSH profile 对依赖的 buffer/index 子路径解析有缺陷。
await buildAtomically({
  entryPoints: ['msedge-tts'],
  outfile: 'lib/msedge-tts.cjs',
  bundle: true,
  format: 'cjs',
  platform: 'node',
  external: ['node:*'],
  logLevel: 'info',
})

// --- host half: plain ESM cordis plugin; runtime deps stay external ---
await buildAtomically({
  entryPoints: ['src/index.ts'],
  outfile: 'lib/index.js',
  bundle: true,
  format: 'esm',
  platform: 'node',
  target: 'node22',
  external: [
    '@deepseek-ai/cordis',
    '@deepseek-ai/schemastery',
    '@deepseek-ai/dsh-host-webserver',
    '@deepseek-ai/dsh-llm',
    '@deepseek-ai/dsh-settings',
    '@deepseek-ai/dsh-typert-protocol',
    'ws',
    'sherpa-onnx',
    'sherpa-onnx-node',
    'node:*',
  ],
  logLevel: 'info',
})

// --- SenseVoice 定稿解码 worker（P4-1 离主线程）：独立 ESM，主线程 new Worker 加载 ---
await build({
  entryPoints: ['src/sense-worker.ts'],
  outfile: 'lib/sense-worker.mjs',
  bundle: true,
  format: 'esm',
  platform: 'node',
  external: [
    'sherpa-onnx',
    'node:*',
  ],
  logLevel: 'info',
})

// --- AudioWorklet（客户端采集）：独立 IIFE 字符串，经 define 注入 client bundle，
//     运行时用 Blob URL 交给 audioCtx.audioWorklet.addModule 加载（浏览器仅服务 client.js）。 ---
const workletBuild = await build({
  entryPoints: ['src/audio-worklet.ts'],
  bundle: true,
  write: false,
  format: 'iife',
  platform: 'browser',
  logLevel: 'info',
})
const AUDIO_WORKLET_SOURCE = workletBuild.outputFiles[0].text

// --- 本地 TTS 合成子进程（child_process.fork，CJS 以获得 IPC 通道）---
await buildAtomically({
  entryPoints: ['src/tts-vits-worker.ts'],
  outfile: 'lib/tts-vits-worker.cjs',
  bundle: true,
  format: 'cjs',
  platform: 'node',
  external: ['sherpa-onnx', 'sherpa-onnx-node', 'node:*'],
  logLevel: 'info',
})

// --- client half: module-loader closure artifact ---
await buildAtomically({
  entryPoints: ['src/client.tsx'],
  outfile: 'lib/client.js',
  bundle: true,
  format: 'cjs',
  platform: 'browser',
  jsx: 'automatic',
  // Keep the native import() for the transformers.js CDN ESM bundle.
  supported: { 'dynamic-import': true },
  external: PLATFORM_EXTERNALS,
  define: {
    __BUILD_TAG__: JSON.stringify(BUILD_TAG),
    __AUDIO_WORKLET__: JSON.stringify(AUDIO_WORKLET_SOURCE),
  },
  banner: {
    js:
      `window.__ModuleLoader__.load({ id: ${JSON.stringify(PKG_ID)}, factory: (require) => {\n` +
      'var module = { exports: {} }; var exports = module.exports;',
  },
  footer: {
    js: 'return module.exports; } });',
  },
  logLevel: 'info',
})

console.log('[dsh-voice-hub] 构建完成：宿主端 lib/index.js、浏览器端 lib/client.js 和语音工作线程')

window.__ModuleLoader__.load({ id: "@aisoc/dsh-voice-hub", factory: (require) => {
var module = { exports: {} }; var exports = module.exports;
"use strict";
var __create = Object.create;
var __defProp = Object.defineProperty;
var __getOwnPropDesc = Object.getOwnPropertyDescriptor;
var __getOwnPropNames = Object.getOwnPropertyNames;
var __getProtoOf = Object.getPrototypeOf;
var __hasOwnProp = Object.prototype.hasOwnProperty;
var __export = (target, all) => {
  for (var name in all)
    __defProp(target, name, { get: all[name], enumerable: true });
};
var __copyProps = (to, from, except, desc) => {
  if (from && typeof from === "object" || typeof from === "function") {
