#!/usr/bin/env node
/**
 * 真机 fixture 分析（ADR-0005 第二批）——把一次录制变成结论。
 *
 * 用法：
 *   node scripts/analyze-fixture.mjs <fixture.json> [--json]
 *
 * ── 判据的由来（2026-09-02 修正） ──
 * 初版用 crest factor（max/mean）判断「残差是否保留语音包络」。**这个判据是错的**：
 * crest 被单个离群帧主导，真机上量到 8.6dB / 12.4dB（看着"像语音"），而实际的
 * 回声地板棘轮效应几乎没发生（doubleTalk 触发率 0.3% / 16.4%，远低于合成信号的 85~97%）。
 *
 * 进一步试过 中位/均值、p90/中位、调制周期 等多个边缘统计量，**没有一个能预测棘轮强度**
 * （合成 p90/中位=1.92 冻结 85%，真机=2.62 只冻结 16%，不单调）。原因是棘轮是**双稳态动态**：
 * 地板一旦开始塌就正反馈继续塌，是否启动取决于初期越过 floor×2 的帧够不够多，不是分布形状的函数。
 *
 * 所以本脚本**不再给基于分布的判据**，直接报引擎每帧记下的真值：
 *   - doubleTalk 触发率（f.dt）→ 棘轮驱动力本身
 *   - 门开率（f.fl / f.pk）→ 门控当时的真实状态
 *   - 地板对残差均值的误差 → 地板还能不能当电平估计用
 * 分布统计量保留为描述性信息，不参与判定。
 *
 * 而「回声门控有没有在保护你」的答案，其实由更前面的一环决定：
 *   - 朗读期 Silero isSpeech 真值率 → 若为 0，门控根本不会被查询到（打断需要先连续判真）
 */
import { readFileSync } from 'node:fs'

const path = process.argv[2]
const wantJson = process.argv.includes('--json')
if (!path) {
  console.error('用法：node scripts/analyze-fixture.mjs <fixture.json> [--json]')
  process.exit(1)
}

const fx = JSON.parse(readFileSync(path, 'utf8'))
if (fx.schema !== 'dsh-voice-mode/fixture@1') {
  console.error(`未知 schema：${fx.schema}`)
  process.exit(1)
}

const frames = fx.frames ?? []
const marks = fx.marks ?? []
if (frames.length === 0) {
  console.error('录制里没有帧——是不是没进语音模式，或开关没设成 meta/full？')
  process.exit(1)
}

const GATE_DB = fx.env?.echoGateDb ?? 6
const GATE_RATIO = Math.pow(10, GATE_DB / 20)

// ── 圈定窗口：TTS 在播 且 用户没在说话 = 纯回声 ──
const speechSpans = []
let openSpan = null
for (const m of marks) {
  if (m.kind === 'user-speech-start') openSpan = m.t
  else if (m.kind === 'user-speech-end' && openSpan !== null) {
    speechSpans.push([openSpan, m.t])
    openSpan = null
  }
}
if (openSpan !== null) speechSpans.push([openSpan, Infinity])
const inUserSpeech = (t) => speechSpans.some(([a, b]) => t >= a && t <= b)

const pureEcho = frames.filter((f) => f.pt === 1 && !inUserSpeech(f.t))
const userWhilePlaying = frames.filter((f) => f.pt === 1 && inUserSpeech(f.t))
const idleFrames = frames.filter((f) => f.pt === 0 && !inUserSpeech(f.t))

const qtl = (a, p) => {
  const s = [...a].sort((x, y) => x - y)
  return s.length ? s[Math.min(s.length - 1, Math.floor(s.length * p))] : 0
}
const avg = (a) => (a.length ? a.reduce((s, x) => s + x, 0) / a.length : 0)

function shape(fr) {
  if (fr.length === 0) return null
  const r = fr.map((f) => f.rms)
  const mean = avg(r)
  const median = qtl(r, 0.5)
  return {
    n: fr.length,
    mean,
    median,
    p90: qtl(r, 0.9),
    p99: qtl(r, 0.99),
    max: Math.max(...r),
    /** 描述性：分布偏度代理。**不预测棘轮**（见文件头），仅供人看。 */
    medianOverMean: mean > 0 ? median / mean : 0,
    /** 描述性：旧判据，已废弃。 */
    crestDb: mean > 0 ? 20 * Math.log10(Math.max(...r) / mean) : 0,
    /** 引擎内真值：本窗口 doubleTalk 触发率（= 地板棘轮的驱动力）。 */
    doubleTalkPct: (100 * fr.filter((f) => f.dt === 1).length) / fr.length,
    /** 引擎内真值：门开率（用录制时的 fl/pk，不是重放）。 */
    gateOpenPct: (100 * fr.filter((f) => f.fl > 0 && f.pk > f.fl * GATE_RATIO).length) / fr.length,
    /** 地板对本窗口残差均值的估计误差（正 = 低估）。 */
    floorErrorDb: (() => {
      const fl = qtl(fr.map((f) => f.fl), 0.5)
      return fl > 0 && mean > 0 ? 20 * Math.log10(mean / fl) : null
    })(),
  }
}

const echo = shape(pureEcho)
const userPlay = shape(userWhilePlaying)
const idle = shape(idleFrames)

// ── 决定性一环：朗读期 Silero 有没有把回声判成语音 ──
const echoVad = pureEcho.filter((f) => f.spk !== undefined)
const echoVadTrue = echoVad.filter((f) => f.spk === 1).length
const userVad = userWhilePlaying.filter((f) => f.spk !== undefined)
const userVadTrue = userVad.filter((f) => f.spk === 1).length

// ── 检测通道往返耗时（A 档埋点；旧 fixture 无此字段） ──
const detects = (fx.detects ?? []).filter((d) => d.ok === 1)

// ── 检测通道观测栅格：回报间隔分布（打断延迟的真实约束） ──
// 只在**连续播放段内部**统计：跨越非播放期的"间隔"是两轮对话之间的静默，不是停顿。
// （初版没分段，把 9.5s 的回合间静默算成了停顿。）
const playRuns = []
{
  let cur = null
  for (const f of frames) {
    if (f.pt === 1) {
      if (!cur) { cur = []; playRuns.push(cur) }
      cur.push(f)
    } else cur = null
  }
}
const gaps = []
for (const run of playRuns) {
  const ts = run.filter((f) => f.spk !== undefined).map((f) => f.t)
  for (let i = 1; i < ts.length; i++) gaps.push(ts[i] - ts[i - 1])
}
const confirmWindow = (cf) => {
  const w = []
  for (let i = 0; i + cf - 1 < gaps.length; i++) w.push(gaps.slice(i, i + cf).reduce((a, b) => a + b, 0))
  return w
}

const fmt = (v, d = 4) => (v === null || v === undefined ? '—' : v.toFixed(d))
const pct = (v) => (v === null || v === undefined ? '—' : v.toFixed(1) + '%')

const L = []
L.push('# 真机 fixture 分析')
L.push('')
L.push(`文件：\`${path}\``)
L.push(`录于 ${fx.recordedAt} · 时长 ${(fx.durationMs / 1000).toFixed(1)}s · ${frames.length} 帧 · 档位 ${fx.mode} · 结束原因 ${fx.reason}`)
const env = fx.env ?? {}
L.push(
  `环境：build=${env.build ?? '?'} · mode=${env.mode ?? '?'} · bargeInMode=${env.bargeInMode ?? '?'} · echoGateDb=${GATE_DB} · interruptLevel=${env.interruptLevel ?? '?'}`,
)
const aecMark = marks.find((m) => m.kind === 'native-aec')
L.push(`原生 AEC：${aecMark ? aecMark.note : '（未记录）'}`)
L.push('')
L.push(`窗口：纯回声 ${pureEcho.length} 帧 · 播放期用户说话 ${userWhilePlaying.length} 帧 · 非播放 ${idleFrames.length} 帧`)
if (speechSpans.length === 0) L.push('> 无 F8 标注 → 按「全程未说话」处理。非播放窗口里会混入你提问时的语音，属正常。')
L.push('')

// ── 1. 门控是否在保护你 ──
L.push('## 1. 回声门控实际起没起作用')
L.push('')
if (!echo) {
  L.push('**没有纯回声帧**——本次 TTS 没播过，或全程都在说话。')
} else {
  L.push('| 指标 | 纯回声 | 播放期用户说话 | 判读 |')
  L.push('|---|---|---|---|')
  L.push(
    `| 朗读期 Silero 判语音率 | **${echoVad.length ? pct((100 * echoVadTrue) / echoVad.length) : '无回报'}**（${echoVadTrue}/${echoVad.length}） | ${userVad.length ? pct((100 * userVadTrue) / userVad.length) : '—'}（${userVadTrue}/${userVad.length}） | 为 0 ⇒ 门控**根本没被查询到** |`,
  )
  L.push(`| 引擎内门开率 | ${pct(echo.gateOpenPct)} | ${userPlay ? pct(userPlay.gateOpenPct) : '—'} | 纯回声段理想 0% |`)
  L.push(`| doubleTalk 触发率 | ${pct(echo.doubleTalkPct)} | ${userPlay ? pct(userPlay.doubleTalkPct) : '—'} | 高 ⇒ 地板棘轮 |`)
  L.push(`| 地板低估残差均值 | ${echo.floorErrorDb === null ? '—' : echo.floorErrorDb.toFixed(1) + ' dB'} | — | 大 ⇒ 地板不可作电平估计 |`)
  L.push('')
  if (echoVad.length > 0 && echoVadTrue === 0) {
    L.push('**判定：Silero 在整个朗读期从未把回声判成语音（0 帧）。**')
    L.push('⇒ 打断的必要条件（连续 confirmFrames 次判真）从未成立 ⇒ **回声门控这一道从未被查询到**。')
    L.push('真正在拦自打断的是 VAD，不是门控。`echoGateDb` 在此配置下是空操作——但原因是"没走到"，')
    L.push('不是"走到了但判错"。')
  } else if (echoVad.length > 0) {
    L.push(`**判定：Silero 在纯回声期有 ${echoVadTrue} 帧判真** ⇒ 门控是最后一道防线，它的判别力此时才重要。`)
  }
}
L.push('')

// ── 2. 分布形状（描述性；没有边缘统计量能预测棘轮，见文件头）──
L.push('## 2. 残差分布形状（描述性，不作判据）')
L.push('')
L.push('| 窗口 | 帧 | 均值 | 中位 | p90 | p99 | max | **中位/均值** | crest(dB) |')
L.push('|---|---|---|---|---|---|---|---|---|')
for (const [nm, s] of [['纯回声', echo], ['播放期用户说话', userPlay], ['非播放', idle]]) {
  if (!s) continue
  L.push(
    `| ${nm} | ${s.n} | ${fmt(s.mean)} | ${fmt(s.median)} | ${fmt(s.p90)} | ${fmt(s.p99)} | ${fmt(s.max)} | **${s.medianOverMean.toFixed(2)}** | ${s.crestDb.toFixed(1)} |`,
  )
}
L.push('')
L.push('> 以上均为**描述性统计**。中位/均值、p90/中位、调制周期都试过，没有一个能预测棘轮强度——')
L.push('> 棘轮是双稳态动态（地板一塌就正反馈继续塌），不是分布形状的函数。**判定看 §1 的引擎真值，不看这里。**')
L.push('> 参照：`bench-echo-gate.mjs` 的尖锐档中位/均值 ≈0.49~1.07，冻结率却一律 85%+；真机 0.80 只冻结 16.4%。')
L.push('')

// ── 3. 打断观测栅格（延迟的真实约束）──
if (gaps.length > 4) {
  L.push('## 3. 打断检测的观测栅格')
  L.push('')
  L.push(`播放期共 ${gaps.length} 次 VAD 回报。名义节拍 128ms（64ms 帧 + \`>=100ms\` 阈值需攒两帧）。`)
  L.push('')
  L.push('| 分位 | p50 | p90 | p95 | p99 | max |')
  L.push('|---|---|---|---|---|---|')
  L.push(`| 回报间隔 | ${qtl(gaps, 0.5)}ms | ${qtl(gaps, 0.9)}ms | ${qtl(gaps, 0.95)}ms | ${qtl(gaps, 0.99)}ms | ${Math.max(...gaps)}ms |`)
  L.push('')
  L.push('| confirmFrames | 理论确认窗 | 实测 p50 | 实测 p90 | 实测 p99 |')
  L.push('|---|---|---|---|---|')
  for (const cf of [3, 2, 1]) {
    const w = confirmWindow(cf)
    L.push(`| ${cf}${cf === 3 ? '（默认）' : ''} | ${cf * 128}ms | ${qtl(w, 0.5)}ms | ${qtl(w, 0.9)}ms | ${qtl(w, 0.99)}ms |`)
  }
  L.push('')
  // 检测通道覆盖率：播放期本应每 128ms 发一次，实际发了多少。
  // 这一项能直接抓出「某些帧跳过了轮询」这类 bug——2026-09-02 的 return-跳过轮询
  // 就是靠它暴露的（打断窗口覆盖率仅 21%）。
  const playMs = frames.filter((f) => f.pt === 1).length * 64
  const expectedPolls = Math.round(playMs / 128)
  if (expectedPolls > 10 && detects.length > 0) {
    const coverage = (100 * detects.length) / expectedPolls
    L.push(`**检测通道覆盖率**：播放期 ${(playMs / 1000).toFixed(1)}s，应发约 ${expectedPolls} 次，实发 ${detects.length} 次 → **${coverage.toFixed(0)}%**`)
    // 用户说话期间单独算——这是最该覆盖、也最容易被漏掉的窗口。
    // 按**每段说话区间**分别算：初版取首末帧做窗口，把区间之间的空隙也算进了分母（虚低）。
    let expUser = 0
    let gotUser = 0
    for (const [a, b] of speechSpans) {
      const fr = frames.filter((f) => f.pt === 1 && f.t >= a && f.t <= b)
      if (fr.length === 0) continue
      expUser += Math.round((fr.length * 64) / 128)
      gotUser += detects.filter((d) => d.t >= a && d.t <= b).length
    }
    if (expUser > 3) {
      const cu = (100 * gotUser) / expUser
      L.push(`**打断窗口覆盖率**：${speechSpans.length} 段说话，应发约 ${expUser} 次，实发 ${gotUser} 次 → **${cu.toFixed(0)}%**`)
      if (cu < 80) L.push('> ⚠️ 打断窗口覆盖率偏低——正是最需要检测的时候反而少发。检查 handleAudio 是否有分支跳过了轮询块。')
    }
    L.push('')
  }

  // A 档埋点：把「回报间隔」拆成「往返耗时」与「客户端等待」，定位瓶颈在哪一侧。
  if (detects.length > 4) {
    const rtts = detects.map((d) => d.rtt)
    L.push('**停顿归因**（A 档埋点，`detects` 字段）：')
    L.push('')
    L.push('| | p50 | p90 | p99 | max |')
    L.push('|---|---|---|---|---|')
    L.push(`| 请求往返耗时 | ${qtl(rtts, 0.5)}ms | ${qtl(rtts, 0.9)}ms | ${qtl(rtts, 0.99)}ms | ${Math.max(...rtts)}ms |`)
    L.push(`| 回报间隔（含等待） | ${qtl(gaps, 0.5)}ms | ${qtl(gaps, 0.9)}ms | ${qtl(gaps, 0.99)}ms | ${Math.max(...gaps)}ms |`)
    L.push('')
    const rttP99 = qtl(rtts, 0.99)
    const gapP99 = qtl(gaps, 0.99)
    if (rttP99 > gapP99 * 0.6) {
      L.push(`> 尾部由**往返耗时**主导（p99 往返 ${rttP99}ms vs 间隔 ${gapP99}ms）⇒ 瓶颈在宿主/网络侧。`)
      L.push('> 客户端侧的节拍修复帮不上，需要 ADR-0003（VAD 下沉）或减小上行体积。')
    } else {
      L.push(`> 尾部**不由往返耗时解释**（p99 往返仅 ${rttP99}ms，间隔却 ${gapP99}ms）⇒ 时间花在客户端等待上。`)
      L.push('> 这正是 A 档节拍修复针对的情形——请求回来后应当立即补发，而不是等下一个 128ms 边界。')
    }
    L.push('')
  } else if ((fx.detects ?? []).length === 0) {
    L.push('> （本次录制没有 `detects` 字段——是 A 档埋点之前的版本。重录可拿到停顿归因。）')
    L.push('')
  }
  const stalls = gaps.filter((g) => g > 200).length
  if (stalls > 0) {
    L.push(
      `> **${stalls} 次回报间隔 > 200ms**（占 ${((100 * stalls) / gaps.length).toFixed(1)}%，最长 ${Math.max(...gaps)}ms）。`,
    )
    L.push('> 检测通道被 `detectInFlight` 串行化——下一拍必须等上一次 HTTP 往返回来。宿主忙时（TTS 合成 / LLM 流 / ASR 解码')
    L.push('> 共用一条 Node 事件循环）这一拍就被拖长，而**这恰好发生在打断时刻**。')
  } else {
    L.push('> 本次录制没有出现回报停顿（全程 ≤200ms）。')
  }
  L.push('')
}

// ── 4. 打断事件 ──
const interrupts = marks.filter((m) => m.kind === 'interrupt')
if (interrupts.length > 0) {
  L.push('## 4. 打断事件')
  L.push('')
  for (const m of interrupts) {
    const ok = inUserSpeech(m.t)
    L.push(`- t=${(m.t / 1000).toFixed(2)}s · ${m.note ?? ''} · ${ok ? '用户确实在说话 ✅' : '**用户未标注说话 → 疑似误打断** ⚠️'}`)
  }
  const cm = interrupts.map((m) => Number(String(m.note ?? '').replace(/\D/g, ''))).filter(Number.isFinite)
  if (cm.length) {
    L.push('')
    // confirmMs = 首次判真 → 第三次判真 = **2 个**回报间隔（不是 3 个）。
    const floorMs = 2 * 128
    L.push(`确认耗时：${cm.join(' / ')}ms（理论下限 ${floorMs}ms = 2 × 128ms 栅格 @ interruptLevel=0）`)
    if (Math.max(...cm) > floorMs * 1.5) L.push('> 明显超出理论下限 → 对照上面的覆盖率与停顿归因。')
    else L.push('> 贴着理论下限 —— 检测通道没有被跳过或拖延。')
  }
  L.push('')
}

const sentences = marks.filter((m) => m.kind === 'tts-sentence')
L.push('## 5. 朗读句（供定位）')
L.push('')
if (sentences.length === 0) {
  L.push('（无 `tts-sentence` 标注。若本次确实朗读过，说明埋点漏在了 Web Audio 主路径——')
  L.push('已于 2026-09-02 修复，重建后重录即可拿到句边界。）')
} else {
  for (const m of sentences.slice(0, 12)) L.push(`- t=${(m.t / 1000).toFixed(2)}s · ${String(m.note ?? '').slice(0, 60)}`)
  if (sentences.length > 12) L.push(`- …共 ${sentences.length} 句`)
}

console.log(L.join('\n'))

if (wantJson) {
  console.log('\n---\n')
  console.log(
    JSON.stringify(
      {
        schema: 'dsh-voice-mode/fixture-analysis@2',
        source: path,
        env,
        windows: { pureEcho: pureEcho.length, userWhilePlaying: userWhilePlaying.length, idle: idleFrames.length },
        shape: { pureEcho: echo, userWhilePlaying: userPlay, idle },
        vadOnEcho: { reported: echoVad.length, trueCount: echoVadTrue },
        pollGrid: {
          n: gaps.length,
          p50: qtl(gaps, 0.5),
          p90: qtl(gaps, 0.9),
          p99: qtl(gaps, 0.99),
          max: gaps.length ? Math.max(...gaps) : null,
          confirm3: { p50: qtl(confirmWindow(3), 0.5), p99: qtl(confirmWindow(3), 0.99) },
        },
        interrupts: interrupts.map((m) => ({ t: m.t, note: m.note })),
      },
      null,
      2,
    ),
  )
}

#!/usr/bin/env node
/**
 * P4-2 在线 ASR 换型离线对照评测（CER/段延迟/体积）。
 *
 * 用法：
 *   node scripts/bench-asr.mjs --dir <测试集目录>
 *
 * 测试集目录约定：*.wav（16k 单声道 16bit PCM）+ 同名 *.txt（参考文本，UTF-8）。
 * 模型自动懒下载至平台缓存目录（与插件同一约定：Linux/macOS
 * ~/.cache/dsh-voice-mode/models/，Windows %LOCALAPPDATA%\dsh-voice-mode\models），
 * .part 断点续传，huggingface.co ↗ hf-mirror.com 回退（--host 可指定镜像）。
 *
 * 输出：Markdown 表格（model | CER% | 平均段延迟 ms | 模型体积 MB），
 * 「数据说话」支撑 P4 换型决策（plan.md §3-P4）。
 */
import { createWriteStream, readdirSync, readFileSync, statSync, mkdirSync, renameSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { homedir } from 'node:os'
import sherpa_onnx from 'sherpa-onnx'

const here = dirname(fileURLToPath(import.meta.url))
const root = join(here, '..')

// ---------- 模型清单（repo/文件清单/设备配置） ----------
const MODELS = [
  {
    id: 'zipformer-zh-int8',
    repo: 'csukuangfj/sherpa-onnx-streaming-zipformer-zh-int8-2025-06-30',
    files: ['encoder.int8.onnx', 'decoder.onnx', 'joiner.int8.onnx', 'tokens.txt'],
    make: (t) => ({
      modelConfig: {
        transducer: { encoder: t('encoder.int8.onnx'), decoder: t('decoder.onnx'), joiner: t('joiner.int8.onnx') },
        tokens: t('tokens.txt'), numThreads: 4, provider: 'cpu', debug: 0,
      },
      decodingMethod: 'greedy_search',
    }),
  },
  {
    id: 'zipformer-zh-xlarge-int8',
    repo: 'csukuangfj/sherpa-onnx-streaming-zipformer-zh-xlarge-int8-2025-06-30',
    files: ['encoder.int8.onnx', 'decoder.onnx', 'joiner.int8.onnx', 'tokens.txt'],
    make: (t) => ({
      modelConfig: {
        transducer: { encoder: t('encoder.int8.onnx'), decoder: t('decoder.onnx'), joiner: t('joiner.int8.onnx') },
        tokens: t('tokens.txt'), numThreads: 4, provider: 'cpu', debug: 0,
      },
      decodingMethod: 'greedy_search',
    }),
  },
  {
    id: 'zipformer-small-ctc-zh-int8',
    repo: 'csukuangfj/sherpa-onnx-streaming-zipformer-small-ctc-zh-int8-2025-04-01',
    files: ['model.int8.onnx', 'tokens.txt'],
    make: (t) => ({
      modelConfig: {
        zipformer2Ctc: { model: t('model.int8.onnx') },
        tokens: t('tokens.txt'), numThreads: 4, provider: 'cpu', debug: 0,
      },
    }),
  },
  {
    id: 'paraformer-bilingual-zh-en',
    repo: 'csukuangfj/sherpa-onnx-streaming-paraformer-bilingual-zh-en',
    files: ['encoder.int8.onnx', 'decoder.int8.onnx', 'tokens.txt'],
    make: (t) => ({
      modelConfig: {
        paraformer: { encoder: t('encoder.int8.onnx'), decoder: t('decoder.int8.onnx') },
        tokens: t('tokens.txt'), numThreads: 4, provider: 'cpu', debug: 0,
      },
    }),
  },
]

// ---------- 参数 ----------
function parseArgs(argv) {
  const args = { dir: null, host: 'https://huggingface.co' }
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--dir') args.dir = argv[i + 1]
    else if (argv[i] === '--host') args.host = argv[i + 1]
  }
  return args
}

// ---------- 平台缓存目录 ----------
function cacheDir() {
  return process.platform === 'win32'
    ? join(process.env.LOCALAPPDATA ?? join(homedir(), 'AppData', 'Local'), 'dsh-voice-mode', 'models')
    : join(homedir(), '.cache', 'dsh-voice-mode', 'models')
}

// ---------- 懒下载（.part 续传 + host 回退，与插件 ensureFile 同构） ----------
async function ensureFile(repoDir, file, hosts) {
  const localPath = join(repoDir, file)
  try {
    if (statSync(localPath).isFile()) return true
  } catch {
    // 缺失
  }
  if (file === 'tokens.txt') console.log(`  下载 ${file}…`)
  else console.log(`  下载 ${file}（可能较大）…`)
  mkdirSync(repoDir, { recursive: true })
  const partPath = localPath + '.part'
  let partSize = 0
  try {
    partSize = statSync(partPath).size
  } catch {
    // 无 .part
  }
  for (const host of hosts) {
    try {
      const url = `${host}/${repoDir.split(/[\\/]/).pop()}/resolve/main/${file}`
      const headers = { 'user-agent': 'dsh-voice-hub-bench' }
      if (partSize > 0) headers.range = `bytes=${partSize}-`
      const res = await fetch(url, { headers })
      if (res.status === 416) {
        renameSync(partPath, localPath)
        return true
      }
      if (res.status !== 200 && res.status !== 206) continue
      const sink = createWriteStream(partPath, partSize > 0 ? { flags: 'a' } : {})
      const reader = res.body.getReader()
      for (;;) {
        const { done, value } = await reader.read()
        if (done) break
        if (!sink.write(value)) await new Promise((r) => sink.once('drain', r))
      }
      await new Promise((resolve, reject) => {
        sink.end(() => resolve())
        sink.on('error', reject)
      })
      renameSync(partPath, localPath)
      return true
    } catch {
      partSize = 0 // 换 host 重来
    }
  }
  return false
}


async function ensureModels(cache, repo, files, hosts) {
  const repoDir = join(cache, repo)
  for (const f of files) {
    if (!(await ensureFile(repoDir, f, hosts))) {
      console.error(`  模型下载失败: ${repo}/${f}`)
      return false
    }
  }
  return true
}

// ---------- WAV 读取（readWaveFromBinaryData → {samples, sampleRate}） ----------
async function loadTestSet(dir) {
  const entries = readdirSync(dir)
  const wavs = entries.filter((n) => n.endsWith('.wav')).sort()
  const cases = []
  for (const w of wavs) {
    const txt = w.replace(/\.wav$/, '.txt')
    if (!entries.includes(txt)) {
      console.warn(`跳过 ${w}：无同名 ${txt} 参考文本`)
      continue
    }
    const buf = readFileSync(join(dir, w))
    let wav
    try {
      wav = sherpa_onnx.readWaveFromBinaryData(new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength))
    } catch (e) {
      console.warn(`跳过 ${w}：无法解析 WAV（${String(e).slice(0, 80)}）`)
      continue
    }
    if (wav.sampleRate !== 16000) {
      console.warn(`跳过 ${w}：采样率 ${wav.sampleRate}Hz ≠ 16k（请先重采样）`)
      continue
    }
    const ref = readFileSync(join(dir, txt), 'utf8').trim()
    cases.push({ name: w, samples: wav.samples, ref })
  }
  return cases
}

// ---------- 编辑距离（字符级，中文按字） ----------
function cer(hyp, ref) {
  const a = [...hyp]
  const b = [...ref]
  const m = a.length
  const n = b.length
  const dp = new Uint32Array((m + 1) * (n + 1))
  for (let i = 0; i <= m; i++) dp[i * (n + 1)] = i
  for (let j = 0; j <= n; j++) dp[j] = j
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1
      dp[i * (n + 1) + j] = Math.min(
        dp[(i - 1) * (n + 1) + j] + 1,
        dp[i * (n + 1) + j - 1] + 1,
        dp[(i - 1) * (n + 1) + j - 1] + cost,
      )
    }
  }
  const dist = dp[m * (n + 1) + n]
  const denom = Math.max(n, 1)
  return (dist / denom) * 100
}



// ---------- 单模型评测 ----------
async function evalModel(model, cases, hosts, cache) {
  const repoDir = join(cache, model.repo)
  if (!(await ensureModels(cache, model.repo, model.files, hosts))) {
    return { id: model.id, cer: null, ms: null, mb: null, error: '模型下载失败' }
  }
  const t = (f) => join(repoDir, f)
  const rec = sherpa_onnx.createOnlineRecognizer(model.make(t))
  let distSum = 0
  let lenSum = 0
  const timings = []
  for (const c of cases) {
    const stream = rec.createStream()
    const t0 = performance.now()
    stream.acceptWaveform(16000, c.samples)
    while (rec.isReady(stream)) rec.decode(stream)
    const text = rec.getResult(stream).text
    timings.push(performance.now() - t0)
    distSum += cer(text, c.ref) * Math.max(c.ref.length, 1)
    lenSum += Math.max(c.ref.length, 1)
    stream.free?.()
  }
  rec.free?.()
  let bytes = 0
  for (const f of model.files) {
    try {
      bytes += statSync(join(repoDir, f)).size
    } catch {
      // ignore
    }
  }
  return {
    id: model.id,
    cer: lenSum > 0 ? distSum / lenSum : null,
    ms: timings.length > 0 ? timings.reduce((a, b) => a + b, 0) / timings.length : null,
    mb: bytes / (1024 * 1024),
  }
}

async function main() {
  const args = parseArgs(process.argv.slice(2))
  if (!args.dir) {
    console.error('用法: node scripts/bench-asr.mjs --dir <测试集目录> [--host 镜像]')
    process.exit(1)
  }
  const cache = cacheDir()
  const hosts = [...new Set([args.host, 'https://huggingface.co', 'https://hf-mirror.com'].filter(Boolean))]
  const cases = await loadTestSet(args.dir)
  if (cases.length === 0) {
    console.error(`测试集为空：${args.dir}（需 16k 单声道 16bit PCM .wav + 同名 .txt）`)
    process.exit(1)
  }
  console.log(`测试集 ${args.dir}：${cases.length} 段（合计约 ${Math.round(cases.reduce((a, c) => a + c.samples.length, 0) / 16000)}s 音频）`)
  console.log('')
  const rows = []
  for (const m of MODELS) {
    const r = await evalModel(m, cases, hosts, cache)
    rows.push(r)
    console.log(
      r.error
        ? `- ${m.id}: ${r.error}`
        : `- ${m.id}: CER ${r.cer.toFixed(2)}% · 平均段延迟 ${r.ms.toFixed(0)}ms · 体积 ${r.mb.toFixed(0)}MB`,
    )
  }
  console.log('')
  console.log('| 模型 | CER% | 平均段延迟 ms | 体积 MB |')
  console.log('| --- | --- | --- | --- |')
  for (const r of rows) {
    console.log(
      r.error || r.cer === null
        ? `| ${r.id} | — | — | — (${r.error ?? '无数据'}) |`
        : `| ${r.id} | ${r.cer.toFixed(2)} | ${r.ms.toFixed(0)} | ${r.mb.toFixed(0)} |`,
    )
  }
  console.log('')
  console.log('说明：CER = 字符编辑距离/参考长度；段延迟 = 整段喂入到 getResult 的墙钟；体积 = 模型文件磁盘占用。')
}

main().catch((e) => {
  console.error('bench failed:', e)
  process.exit(1)
})

#!/usr/bin/env node
/**
 * 回声门控离线基准（ADR-0005 第一批：零依赖、零录音、可进 CI）。
 *
 * 用法：
 *   node scripts/bench-echo-gate.mjs            # 打印 Markdown 报告
 *   node scripts/bench-echo-gate.mjs --json     # 追加机器可读 JSON（基线对比用）
 *
 * 为什么是「bench」而不是「test」：ADR-0005 的第一阶段是「先报告不拦截」。
 * 本脚本当前报告的是**现状**，而现状里有一个已确认的缺陷（见下），所以它
 * 不能当断言门用——先把数字晒出来，等修法确定后再转成 test。
 *
 * ── 它测什么 ──
 * 回声门控（asr.ts:575-593 + aboveEchoFloor）在「纯 TTS 回声期」应当保持关闭
 * （不把回声判成用户人声），在「用户开口」时应当打开。本脚本用确定性合成残差
 * 扫描 crest factor（峰值/均值，dB），量出两件事：
 *   1) 纯回声期的门开率（理想 0%）
 *   2) 回声地板对真实回声电平的估计误差（理想 0dB）
 *
 * ── 重要：这是压力测试，不是真机预测器（2026-09-02 真机修订） ──
 * 本脚本的合成残差比真机残差"尖"得多，下表的 99.8% 门开率是**机制的上界**，不是现状。
 * 真机实测：门开率 0.3%（纯听）/ 27.1%（打断场景）。见
 * docs/findings/2026-09-02-echo-gate-ratchet.md。
 *
 * **不要把本脚本的数字当真机预测。** 试过用中位/均值、p90/中位、调制周期等统计量把合成档
 * 映射到真机，都不成立（合成中位/均值 1.07 冻结 85%，真机 1.00 只冻结 0.3%）——棘轮是双稳态
 * 动态，不是分布形状的函数。要知道真机什么样，只能录一条跑 analyze-fixture.mjs。
 *
 * 保留尖锐档的意义：它守的是「原生 AEC 失效、走自研 NLMS」那条尚无真机数据的路径。
 *
 * ── 机制（真实存在，强度随残差尖锐度单调上升） ──
 * `doubleTalk` 冻结让回声地板变成**单向棘轮**：
 *   doubleTalk = playing && floor > 0 && rms > floor * gateRatio   (asr.ts:588)
 *   地板仅在 !doubleTalk 时更新                                     (asr.ts:591)
 * ⇒ 凡是「响于 floor×gateRatio」的帧一律不参与地板更新，只有安静帧能更新地板，
 *   而安静帧只会把地板往下拉。地板因此收敛到**音节间隙的电平**而非回声均值。
 *   同时 echoPeak 是峰值保持（asr.ts:583），停在响的一端。
 * ⇒ peak/floor 比值被系统性放大，门几乎恒开。
 *
 * TTS 回声本身就是语音，crest 天然在 7dB 以上，所以这条路径在**它被设计来防的
 * 那个场景里**失效。详见 docs/findings/2026-09-02-echo-gate-ratchet.md。
 *
 * 本脚本无外部依赖（不需要 npm install、不需要模型、不联网）。
 */

const FRAME_MS = 64 // AudioWorklet 每 1024 样本 @16k 投一帧（audio-worklet.ts CHUNK/TARGET_RATE）
const DEFAULT_GATE_DB = 6

/** 确定性伪随机（mulberry32），与 test/aec.test.mjs 同款，保证跨机可复现。 */
function mulberry32(a) {
  return () => {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/**
 * 参考实现：逐行转写 src/asr.ts:575-593 与 aboveEchoFloor(:849-852)。
 *
 * **不要改这里的算式** —— 它的唯一职责是与生产代码对拍。生产代码改了，
 * 这里跟着改，并且改动必须体现在报告数字上（这就是回归保护的机制）。
 */
function refEchoGate(gateDb = DEFAULT_GATE_DB) {
  let floorRms = 0
  let peakRms = 0
  let residualRms = 0
  return {
    /** 送入一帧 AEC 后残差 RMS；返回本帧 { doubleTalk, gateOpen }。 */
    step(rms, durationMs, playing) {
      const gateRatio = Math.pow(10, gateDb / 20) //                        asr.ts:575
      const peakDecay = Math.pow(0.9, durationMs / 64) //                   asr.ts:578
      const floorAlpha = 1 - Math.pow(0.98, durationMs / 64) //             asr.ts:579
      if (playing) {
        residualRms = rms //                                               asr.ts:581
        peakRms = Math.max(peakRms * peakDecay, rms) //                     asr.ts:583
      }
      // 关键：doubleTalk 用**更新前**的 floor（asr.ts:588）
      const doubleTalk = playing && floorRms > 0 && rms > floorRms * gateRatio
      if (playing) {
        if (floorRms === 0) floorRms = rms //                              asr.ts:590
        else if (!doubleTalk) floorRms = floorRms * (1 - floorAlpha) + rms * floorAlpha // asr.ts:591
      } else {
        peakRms = 0 //                                                     asr.ts:593
      }
      // aboveEchoFloor：floor===0 保守拒绝；否则比较**峰值**（asr.ts:849-852）
      const gateOpen = floorRms !== 0 && peakRms > floorRms * Math.pow(10, gateDb / 20)
      return { doubleTalk, gateOpen }
    },
    levels: () => ({ floorRms, residualRms, peakRms }),
  }
}

/**
 * 分布偏度代理：中位/均值。越接近 1 越准平稳，越接近 0 越「深谷+高峰」。
 * **这是棘轮强度的正确预测量**——crest（下面那个）不是，它被单个离群帧主导。
 * 真机参照：纯听 1.00、打断场景 0.80；本脚本的尖锐档 ~0.49。
 */
function medianOverMean(a) {
  const sorted = [...a].sort((x, y) => x - y)
  const mean = sorted.reduce((s, x) => s + x, 0) / sorted.length
  return mean > 0 ? sorted[Math.floor(sorted.length / 2)] / mean : 0
}

/** crest factor（峰值/均值，dB）——**保留仅作对照，它不预测棘轮**。 */
function crestDb(a) {
  const mean = a.reduce((s, x) => s + x, 0) / a.length
  return 20 * Math.log10(Math.max(...a) / mean)
}

const meanOf = (a) => a.reduce((s, x) => s + x, 0) / a.length

/**
 * 合成一段「AEC 后残差」的逐帧 RMS 序列。
 *
 * gapDepth 控制词间/句间静音有多深：1 = 完全没有停顿（准平稳噪声，
 * 接近原生 AEC + RES 之后的残留），0.03 = 真实语音的停顿深度。
 * 这个参数就是 crest factor 的旋钮。
 */
function synthResidual({ frames = 470, level = 0.01, gapDepth = 0.03, seed = 11 } = {}) {
  const rng = mulberry32(seed)
  return Array.from({ length: frames }, (_, i) => {
    const syllable = Math.pow(Math.abs(Math.sin((i * Math.PI) / 3.5)), 2.2) // 音节起伏 ~0.45s
    const gap = i % 47 < 8 ? gapDepth : 1 // 词间/句间静音
    return level * (0.05 + 2.6 * syllable) * gap * (0.8 + 0.4 * rng())
  })
}

/** 跑一条序列，返回门开率 / 冻结率 / 地板估计误差。 */
function evaluate(signal, { gateDb = DEFAULT_GATE_DB, playing = true } = {}) {
  const gate = refEchoGate(gateDb)
  let open = 0
  let frozen = 0
  const openFlags = []
  for (const rms of signal) {
    const d = gate.step(rms, FRAME_MS, playing)
    if (d.gateOpen) open++
    if (d.doubleTalk) frozen++
    openFlags.push(d.gateOpen)
  }
  const lv = gate.levels()
  const trueLevel = meanOf(signal)
  return {
    openPct: (100 * open) / signal.length,
    frozenPct: (100 * frozen) / signal.length,
    floorRms: lv.floorRms,
    trueLevel,
    // 地板低估真实回声电平多少 dB（正数 = 低估）
    floorErrorDb: 20 * Math.log10(trueLevel / Math.max(lv.floorRms, 1e-12)),
    openFlags,
  }
}

/** 判别力：纯回声段应关、用户开口段应开，两者门开率之差才是这道门的价值。 */
function discrimination({ gateDb = DEFAULT_GATE_DB, seed = 11 } = {}) {
  const echo = synthResidual({ seed })
  const split = Math.floor(echo.length / 2)
  const rng = mulberry32(3)
  // 后半段叠加用户人声（幅度约为回声的 3 倍）
  const mixed = echo.map((v, i) =>
    i < split ? v : v + 0.03 * Math.pow(Math.abs(Math.sin((i * Math.PI) / 4)), 1.5) * (0.8 + 0.4 * rng()),
  )
  const r = evaluate(mixed, { gateDb })
  const echoPart = r.openFlags.slice(0, split)
  const userPart = r.openFlags.slice(split)
  const echoOpen = (100 * echoPart.filter(Boolean).length) / echoPart.length
  const userOpen = (100 * userPart.filter(Boolean).length) / userPart.length
  return { echoOpen, userOpen, marginPct: userOpen - echoOpen }
}

/** 轮询观测栅格：worklet 64ms/帧 + asr.ts:700 的 100ms 阈值 ⇒ 稳态 128ms。 */
function pollGrid() {
  let last = 0
  const at = []
  for (let i = 0; i < 40; i++) {
    const t = Math.round(((i + 1) * 1024) / 16000 * 1000)
    if (t - last >= 100) {
      at.push(t)
      last = t
    }
  }
  const gaps = at.slice(1).map((v, i) => v - at[i])
  return { intervalMs: [...new Set(gaps)], confirmMs: { 0: 3, 1: 2, 2: 1 } }
}

// ─────────────────────────── 报告 ───────────────────────────

const wantJson = process.argv.includes('--json')
const out = []
const p = (s) => out.push(s)

p('# 回声门控离线基准（ADR-0005 · 报告模式）')
p('')
p(`帧长 ${FRAME_MS}ms · 门限 ${DEFAULT_GATE_DB}dB · 确定性合成 · 无外部依赖`)
p('')

p('## 1. 纯回声期门开率 vs 信号 crest（理想：全 0%）')
p('')
p('| 词间静音深度 | **中位/均值** | 门开率 | 地板冻结率 | 地板低估真实回声 | crest (dB) |')
p('|---|---|---|---|---|---|')
const sweep = []
for (const gapDepth of [1, 0.6, 0.3, 0.15, 0.08, 0.03]) {
  const sig = synthResidual({ gapDepth })
  const r = evaluate(sig)
  const mom = medianOverMean(sig)
  sweep.push({ gapDepth, medianOverMean: +mom.toFixed(2), crestDb: +crestDb(sig).toFixed(2), openPct: +r.openPct.toFixed(1), frozenPct: +r.frozenPct.toFixed(1), floorErrorDb: +r.floorErrorDb.toFixed(1) })
  p(`| ${gapDepth} | **${mom.toFixed(2)}** | ${r.openPct.toFixed(1)}% | ${r.frozenPct.toFixed(1)}% | ${r.floorErrorDb.toFixed(1)} dB | ${crestDb(sig).toFixed(1)} |`)
}
p('')
p('')
p('**真机实测对照**（`analyze-fixture.mjs`，原生 AEC 生效，外放）：')
p('')
p('| 录制 | 中位/均值 | 门开率 | doubleTalk 触发率 | 地板低估 |')
p('|---|---|---|---|---|')
p('| ① 纯听 124.6s | 1.00 | 0.3% | 0.3% | 0.1 dB |')
p('| ② 打断 61.8s | 0.80 | 27.1% | 16.4% | 2.8 dB |')
p('')
p('> 真机上棘轮几乎不发作（原生 AEC 生效时）。合成档是**机制上界**，两者之间没有可用的映射关系——')
p('> 试过中位/均值、p90/中位、调制周期，都不单调。棘轮是双稳态动态，只能实测。')
p('> 机制本身是真的：真机②相对①更"尖"一点，冻结率就从 0.3% 跳到 16.4%。')
p('')

p('## 2. 调大 echoGateDb 能否补救（README 目前教用户这么做）')
p('')
p('| echoGateDb | 门开率 | 地板低估 |')
p('|---|---|---|')
const gateSweep = []
for (const gateDb of [6, 8, 10, 12, 15, 20, 30]) {
  const r = evaluate(synthResidual({ gapDepth: 0.03 }), { gateDb })
  gateSweep.push({ gateDb, openPct: +r.openPct.toFixed(1), floorErrorDb: +r.floorErrorDb.toFixed(1) })
  p(`| ${gateDb} | ${r.openPct.toFixed(1)}% | ${r.floorErrorDb.toFixed(1)} dB |`)
}
p('')
