p('|---|---|---|---|')
const disc = []
for (const gateDb of [6, 10, 20]) {
  const d = discrimination({ gateDb })
  disc.push({ gateDb, echoOpen: +d.echoOpen.toFixed(1), userOpen: +d.userOpen.toFixed(1), marginPct: +d.marginPct.toFixed(1) })
