function sha256OfFile(path) {
  return new Promise((resolve, reject) => {
    const hash = createHash('sha256')
    const stream = createReadStream(path)
    stream.on('data', (c) => hash.update(c))
    stream.on('error', reject)
    stream.on('end', () => resolve(hash.digest('hex')))
  })
}

async function downloadFile(repo, repoDir, file, expectedSha) {
  const localPath = join(repoDir, file)
  const st = await stat(localPath).catch(() => null)
  if (st?.isFile()) {
    if ((await sha256OfFile(localPath)) === expectedSha) {
      console.log(`  ✓ ${file} 已存在（校验通过）`)
      return true
    }
    console.log(`  ! ${file} 校验失败，重新下载`)
    await unlink(localPath).catch(() => undefined)
  }
  const partPath = `${localPath}.part`
  // 子目录文件（如 espeak-ng-data/phontab）：确保父目录存在再写流。
  await mkdir(join(repoDir, file.includes('/') ? file.slice(0, file.lastIndexOf('/')) : ''), { recursive: true }).catch(() => undefined)
  const partSt = await stat(partPath).catch(() => null)
  for (const host of [HOST_PRIMARY, HOST_FALLBACK]) {
    const url = `${host}/${repo}/resolve/main/${file}`
    const headers = { 'user-agent': 'dsh-voice-hub/prefetch' }
    const resumeFrom = partSt?.size ?? 0
    if (resumeFrom > 0) headers.range = `bytes=${resumeFrom}-`
    try {
      const res = await fetch(url, { headers })
      if (res.status === 416) {
        if ((await sha256OfFile(partPath)) === expectedSha) {
          await rename(partPath, localPath)
          console.log(`  ✓ ${file}（续传完成）`)
          return true
        }
      }
      if (res.status !== 200 && res.status !== 206) continue
      // 续传只在 206 成立；镜像/CDN 忽略 Range 返回 200 全量时必须从头重写。
      const resume = res.status === 206 ? resumeFrom : 0
      const total = Number(res.headers.get('content-length') ?? 0) + resume
      const statusMax = file.length + 18
      const sink = createWriteStream(partPath, resume > 0 ? { flags: 'a' } : {})
      const reader = res.body?.getReader()
      if (!reader) continue
      let received = resume
      for (;;) {
        const { done, value } = await reader.read()
        if (done) break
        received += value.byteLength
        if (!sink.write(value)) await new Promise((r) => sink.once('drain', r))
        const pct = total > 0 ? Math.min(100, Math.round((received / total) * 100)) : -1
        if (pct >= 0 && pct % 10 === 0) process.stdout.write(`\r  ${file.padEnd(statusMax)} ${pct}%`)
      }
      await new Promise((resolve, reject) => {
        sink.end(resolve)
        sink.on('error', reject)
      })
      if ((await sha256OfFile(partPath)) !== expectedSha) {
        await unlink(partPath).catch(() => undefined)
        continue // 校验失败换镜像
      }
      await rename(partPath, localPath)
      process.stdout.write(`\r  ${file.padEnd(statusMax)} 100%\n`)
      console.log(`  ✓ ${file} 完成（${(received / 1048576).toFixed(1)} MB）`)
      return true
    } catch {
      // 换下一个 host
    }
  }
  await unlink(partPath).catch(() => undefined)
  console.error(`  ✗ ${file} 下载失败（两个镜像均不可达或校验不过）`)
  return false
}

let ok = true
for (const [repo, files] of Object.entries(MODELS)) {
  const repoDir = join(cacheDir, repo)
  console.log(`模型仓库：${repo}（缓存 ${repoDir}）`)
  await mkdir(repoDir, { recursive: true })
  for (const [file, sha] of Object.entries(files)) {
    if (!(await downloadFile(repo, repoDir, file, sha))) ok = false
  }
}

// --- Kokoro 中英朗读模型：文件多（含 espeak-ng-data 全目录），走 HF 树枚举批量下载。
//     int8（默认，CPU 友好）与 fp32（音质更好）两档，主模型文件不同、支持文件同源。 ---
for (const kokoro of [
  { repo: 'csukuangfj/kokoro-int8-multi-lang-v1_1', main: 'model.int8.onnx', sha: 'bda15858163726a492d02a9a727bc263551b86ac77f90812c4b30ff41d380e26' },
  { repo: 'csukuangfj/kokoro-multi-lang-v1_1', main: 'model.onnx', sha: 'acc4adc175b9d9986106cd20060329673ad5a2e12ef3c557d2d3745b694f8b38' },
]) {
  const { repo, main, sha } = kokoro
  const repoDir = join(cacheDir, repo)
  const SENTINELS = {
    [main]: sha,
    'voices.bin': 'e64a5a581d8c2a350d848f51c3121657cd83aa07ed6109172177345874a7244c',
    'tokens.txt': '931ab2df2400cd65d580a22402024c2347ced8ae9ea300e545144b1aacc48e14',
    'lexicon-us-en.txt': '7daaab53a181be9885b853a8582bf1838186317e5dadacbcef9c426d6fa0da14',
    'lexicon-zh.txt': '11111d8cd695fba2ace1367a1d0a708b586e6ef5c1f9be91da5d7eef129b651c',
    'espeak-ng-data/phontab': '886f3fa402cb0ba73d483aa8ad000af47a6b7cc06293c75a97913fba68a530f6',
  }
  const sentinelOk = await Promise.all(Object.entries(SENTINELS).map(async ([f, sha2]) => (await sha256OfFile(join(repoDir, f)).catch(() => '')) === sha2))
  if (!sentinelOk.every(Boolean)) {
    console.log(`Kokoro 模型（${repo}）：文件不全，走 HF 树枚举下载`)
    const treeRes = await fetch(`${HOST_FALLBACK}/api/models/${repo}/tree/main?recursive=true`, { headers: { 'user-agent': 'dsh-voice-hub/prefetch' } })
    if (treeRes.ok) {
      const tree = await treeRes.json()
      const files = (tree ?? []).map((x) => x.path).filter((p) => !p.endsWith('/') && !['.gitattributes', 'README.md', 'LICENSE'].includes(p))
      await mkdir(repoDir, { recursive: true })
      let doneCount = 0
      const queue = [...files]
      async function worker() {
        for (;;) {
          const rel = queue.shift()
          if (rel === undefined) return
          const want = SENTINELS[rel]
          const localPath = join(repoDir, rel)
          const partPath = `${localPath}.part`
          if (want && (await sha256OfFile(localPath).catch(() => '')) === want) { doneCount++; continue }
          try {
            await mkdir(localPath.replace(/[\\/][^\\/]*$/, ''), { recursive: true })
            const res = await fetch(`${HOST_FALLBACK}/${repo}/resolve/main/${encodeURIComponent(rel)}`, { headers: { 'user-agent': 'dsh-voice-hub/prefetch' } })
            if (res.status !== 200) { console.error(`  ✗ ${rel} (status ${res.status})`); ok = false; continue }
            const sink = createWriteStream(partPath)
            const reader = res.body?.getReader()
            if (!reader) continue
            for (;;) {
              const { done, value } = await reader.read()
              if (done) break
              if (!sink.write(value)) await new Promise((r) => sink.once('drain', r))
            }
            await new Promise((resolve, reject) => { sink.end(resolve); sink.on('error', reject) })
            const got = await sha256OfFile(partPath)
            if (want && got !== want) { console.error(`  ✗ ${rel} 校验失败`); ok = false; await unlink(partPath).catch(() => undefined); continue }
            await rename(partPath, localPath)
            doneCount++
          } catch {
            console.error(`  ✗ ${rel} 下载失败`)
            ok = false
          }
        }
      }
      await Promise.all(Array.from({ length: 6 }, () => worker()))
      console.log(`Kokoro 下载完成 ${doneCount}/${files.length}`)
    } else {
      console.error('Kokoro 树枚举失败，请稍后重试')
      ok = false
    }
  } else {
    console.log(`Kokoro 模型（${repo}）：已齐备（校验通过）`)
  }
}

console.log(ok ? '\n预下载完成，可直接进入语音模式（本地朗读亦可用）。' : '\n预下载未完成，可稍后重试（断点续传）。')
process.exitCode = ok ? 0 : 1

#!/usr/bin/env node
/**
 * client 冒烟（防回归 I-3 的客户端部分）：用 headless chromium 打开 dsh web，
 * 走完首次引导流程（关 Internal Testing Notice / workspace 配置 / 选 workspace），
 * 等待 voice-mode 麦克风按钮 [data-dshvm="mic"] 渲染，并断言 console 无 error。
 *
 * 用法：node scripts/smoke-client.mjs <dsh-url> [--allow-console-error=regex,...]
 *   dsh-url：boot 后含 token 的完整 URL（如 http://127.0.0.1:3120/?token=xxx）。
 *
 * 依赖：playwright-core（devDependency）+ 已装的 chromium。
 *   浏览器发现：优先用 PLAYWRIGHT_CHROMIUM（executablePath），否则用 playwright 默认
 *   （~/.cache/ms-playwright 下匹配 rev 的 chromium）。
 */
import { chromium } from 'playwright-core'
import { existsSync } from 'node:fs'

const url = process.argv[2]
if (!url) {
  console.error('用法: node scripts/smoke-client.mjs <dsh-url> [--allow-console-error=regex,...]')
  process.exit(2)
}

const allowRe = [/favicon/i]
for (const a of process.argv.slice(3)) {
  const m = a.match(/^--allow-console-error=(.+)$/)
  if (m) for (const r of m[1].split(',')) if (r) allowRe.push(new RegExp(r))
}

const executablePath = process.env.PLAYWRIGHT_CHROMIUM
  || [
      '/root/.cache/ms-playwright/chromium-1237/chrome-linux64/chrome',
      '/root/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome',
    ].find((p) => existsSync(p))

const browser = await chromium.launch({ headless: true, ...(executablePath ? { executablePath } : {}) })
const page = await browser.newPage()

const consoleErrors = []
page.on('console', (msg) => { if (msg.type() === 'error') consoleErrors.push(msg.text()) })
page.on('pageerror', (err) => consoleErrors.push(`pageerror: ${err.message}`))

let failed = false

// 点第一个匹配文本正则的按钮（DOM click，绕过 locator 遮罩拦截问题）。返回按钮文本或 null。
async function clickButton(re) {
  return page.evaluate((src) => {
    const btn = Array.from(document.querySelectorAll('button')).find((b) =>
      new RegExp(src, 'i').test((b.textContent || '').trim()))
    if (btn) { btn.click(); return btn.textContent.trim() }
    return null
  }, re.source)
}

// 同上，但也搜菜单/列表项——工作区下拉里的条目不是 <button>。
async function clickAny(re) {
  return page.evaluate((src) => {
    const rx = new RegExp(src, 'i')
    const sel = 'button,[role="option"],[role="menuitem"],[role="menuitemradio"],[role="listitem"],li,[data-value]'
    const el = Array.from(document.querySelectorAll(sel)).find((e) => {
      const t = (e.textContent || '').trim()
      return t && t.length < 80 && rx.test(t)
    })
    if (el) { el.click(); return (el.textContent || '').trim() }
    return null
  }, re.source)
}

try {
  await page.goto(url, { waitUntil: 'load', timeout: 30000 })
  // 等 React 首屏 + 引导弹窗渲染
  await page.waitForTimeout(2000)

  // 诊断：把首屏对话框里的按钮文本记下来（引导关不掉时能直接看出正则该补什么）
  const dialogButtons = await page.evaluate(() =>
    Array.from(document.querySelectorAll('[role="dialog"] button')).map((b) => (b.textContent || '').trim()).filter(Boolean))
  if (dialogButtons.length) console.log('  引导弹窗按钮:', dialogButtons.join(' | '))

  // 1) 关掉引导弹窗（Internal Testing Notice → Continue；API/workspace 配置 → Configure later）
  //    按「有 dialog 才点」循环，最多 8 轮
  for (let i = 0; i < 8; i++) {
    const hasDialog = await page.evaluate(() => !!document.querySelector('[role="dialog"]'))
    if (!hasDialog) break
    // 中英双语：dsh 界面语言跟随浏览器，纯英文正则在中文环境下匹配不到任何按钮，
    // 引导弹窗关不掉，最终表现为「30s 内等不到 mic 按钮」（实测 win32 中文环境）。
    const clicked = await clickButton(/continue|later|skip|got it|ok|继续|稍后|跳过|知道了|我知道|好的|确定|了解|同意|开始/)
    if (!clicked) break
    await page.waitForTimeout(1000)
  }

  // 2) 选定工作区。两条路径：
  //    a) 已有工作区（smoke-runtime 会预置一个）→ 下拉里点该条目；条目不是 <button>，用 clickAny
  //    b) 无工作区 → 走系统目录选择器（Choose workspace → Open），headless 下基本走不通，仅保留
  const WS_TITLE = process.env.SMOKE_WORKSPACE || 'smoke'
  const opened = await clickButton(/choose workspace|选择工作区/)
  if (opened) {
    await page.waitForTimeout(1200)
    const picked = await clickAny(new RegExp(`^${WS_TITLE}$`))
    if (picked) {
      console.log(`  已选定工作区: ${picked}`)
      await page.waitForTimeout(1500)
    } else {
      await clickButton(/^open$/)
      await page.waitForTimeout(1200)
    }
  }

  // 2.5) 新建会话。mic 按钮在输入区里，而输入区要有「当前会话」才渲染；当前会话存在浏览器
  //      localStorage 的 dsh.sessions.current，headless 全新启动没有，页面停在
  //      「选择一个工作区开始」。点「新会话」按正常用户路径建一个即可。
  if (!(await page.$('[data-dshvm="mic"]'))) {
    const started = await clickAny(/^新会话$|^new session$|新建会话/)
    if (started) {
      console.log(`  已新建会话: ${started}`)
      await page.waitForTimeout(2000)
    }
  }

  // 3) 等 mic 按钮渲染。
  //
  //    口径说明（2026-09-03 实测校正）：mic 按钮挂在「活跃会话」的输入区上，而活跃会话
  //    要发出第一条消息才真正创建（需要模型凭据）。隔离冒烟 home 故意不配凭据（走
  //    「稍后配置」），因此**拿不到会话是环境使然，不是插件回归**。
  //    初版不加区分一律报 FAIL，会把环境限制误报成产品问题。
  //    现在分三种结局：
  //      - 有 mic          → PASS
  //      - 无会话且无 mic  → SKIP（打印原因，不判失败）
  //      - 有会话却无 mic  → FAIL（这才是真回归）
  let micOk = false
  try {
    await page.waitForSelector('[data-dshvm="mic"]', { timeout: 30000 })
    console.log('  ✓ mic 按钮 [data-dshvm="mic"] 渲染')
    micOk = true
  } catch {
    micOk = false
  }

  if (!micOk) {
    const state = await page.evaluate(() => ({
      session: localStorage.getItem('dsh.sessions.current'),
      composer: document.querySelectorAll('textarea,[contenteditable="true"]').length > 0,
      body: (document.body.innerText || '').slice(0, 200),
    }))
    if (!state.session) {
      console.log('  ⚠ 跳过 mic 断言：隔离环境未配置模型凭据 → 无法创建活跃会话 → 输入区不挂 mic 槽位')
      console.log(`    （输入区已渲染: ${state.composer ? '是' : '否'}；这是冒烟环境限制，非插件问题）`)
    } else {
      console.error('  ✗ 已有活跃会话但 mic 按钮未渲染——这是真回归')
      console.error('    页面文本: ' + state.body)
      failed = true
    }
  }
  await page.waitForTimeout(1200)
} catch (e) {
  console.error(`  ✗ 页面加载失败: ${e.message}`)
  failed = true
}

const realErrors = consoleErrors.filter((t) => !allowRe.some((r) => r.test(t)))
if (realErrors.length > 0) {
  console.error(`  ✗ console/pageerror 有 ${realErrors.length} 条：`)
  for (const t of realErrors.slice(0, 10)) console.error(`    - ${t.slice(0, 200)}`)
  failed = true
} else {
  console.log('  ✓ console 0 error')
}

await browser.close()
process.exit(failed ? 1 : 0)

#!/usr/bin/env node
/**
 * 离线纯逻辑验证聚合（官方验证金字塔第 3 层）。
 * 逐个执行无网络单测与清单自检；任一失败即非零退出。
 * 用法：node scripts/verify.mjs（或 npm run verify）
 */
import { spawnSync } from 'node:child_process'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const root = join(here, '..')
const tests = [
  ['segmenter 单测', ['node', 'test/segmenter.test.mjs']],
  ['aec 单测', ['node', 'test/aec.test.mjs']],
  ['下载完整性 单测', ['node', 'test/download.test.mjs']],
  ['语义端点 单测', ['node', 'test/endpoint.test.mjs']],
  ['重采样 单测', ['node', 'test/resample.test.mjs']],
  ['SenseVoice worker 协议 单测', ['node', 'test/sense-worker.test.mjs']],
  ['打断检测路由 单测', ['node', 'test/detect-route.test.mjs']],
  ['清单/产物自检', ['node', 'test/verify-client.mjs']],
]
let failed = 0
for (const [name, cmd] of tests) {
  const r = spawnSync(cmd[0], cmd.slice(1), { cwd: root, encoding: 'utf8' })
  const tail = r.stdout.trim().split('\n').slice(-2).join(' | ')
  console.log(`— ${name}: ${r.status === 0 ? 'PASS' : 'FAIL'}${tail ? `（${tail}）` : ''}`)
  if (r.status !== 0) {
    console.error(r.stderr || r.stdout)
    failed++
  }
}
console.log(failed === 0 ? '\nverify: 全部通过' : `\nverify: ${failed} 项失败`)
process.exitCode = failed === 0 ? 0 : 1

/**
 * NLMS（normalized least-mean-squares）声学回声消除（P3-1）。
 *
 * 移植自上游 haoku123/dsh-voice v0.7.0 的 src/aec.ts（生产已验证）：
 * 浏览器 echoCancellation 是黑盒（OS/浏览器差异大，且看不到本页在播什么）；
 * 当 TTS 音量较大时播放会漏进麦克风、误触发 barge-in。此模块以「页面自产
 * TTS 播放」为参考信号做第二道显式回声消除——参考零歧义，是打断可靠性的
 * 上限来源（回声在识别/打断判定前被减去）。
 *
 * 算法：标准 NLMS + 固定 tap 延迟 + 自适应 FIR：
 *   y[n] = w · x[n - D .. n - D - L]（估计回声）
 *   e[n] = d[n] - y[n]（干净信号）
 *   w += μ · e[n] · x / (‖x‖² + ε)
 * d = 麦克风（期望）信号，x = TTS 参考。滤波器学习扬声器→麦克风声学路径
 * （延迟 + 房间冲激响应）并从麦克风中减去。纯模块（无 Web Audio 类型），可单测。
 */
export interface AecOptions {
  /** FIR 滤波器长度（taps）：覆盖扬声器→麦克风延迟 + 早期反射。 */
  filterLength?: number
  /** 参考信号固定前导延迟（样本）：声学路径的短 OS/缓冲延迟。 */
  delay?: number
  /** 归一化步长（0 < μ < 2；~0.1 为安全默认）。 */
  step?: number
  /** 分母正则化（防静音除零）。 */
  epsilon?: number
}

const DEFAULT_FILTER_LENGTH = 256
const DEFAULT_DELAY = 64
const DEFAULT_STEP = 0.1
const DEFAULT_EPSILON = 1e-6
/** 参考窗均方能量低于此值不更新权重（防近零参考发散，对抗性审查修复）。 */
const MIN_REF_NORM = 1e-6

export class NlmsAec {
  private readonly w: Float32Array
  private readonly xBuf: Float32Array
  private readonly filterLength: number
  private readonly delay: number
  private readonly mu: number
  private readonly eps: number
  /** 参考历史环形游标。 */
  private cursor = 0
  /** 已缓冲参考样本数（预热期）。 */
  private filled = 0
  /** A2.5 双讲冻结：用户说话时暂停权重更新，防滤波器被用户语音带偏。 */
  private frozen = false

  constructor(options: AecOptions = {}) {
    this.filterLength = options.filterLength ?? DEFAULT_FILTER_LENGTH
    this.delay = options.delay ?? DEFAULT_DELAY
    this.mu = options.step ?? DEFAULT_STEP
    this.eps = options.epsilon ?? DEFAULT_EPSILON
    this.w = new Float32Array(this.filterLength)
    this.xBuf = new Float32Array(this.delay + this.filterLength)
  }

  /** A2.5 双讲冻结：true 时暂停权重更新（回声相减照常，仅停止自适应）。 */
  setFrozen(frozen: boolean): void {
    this.frozen = frozen
  }

  /**
   * 送入下一块麦克风/参考；返回去回声后的麦克风样本（与输入等长）。
   * 参考可比麦克风块短（如静音填充）——不足部分补零。
   */
  process(mic: Float32Array, ref: Float32Array): Float32Array {
    const n = mic.length
    const out = new Float32Array(n)
    if (n === 0) return out
    const xBuf = this.xBuf
    const bufLen = xBuf.length
    let cursor = this.cursor
    for (let i = 0; i < n; i++) {
      // 参考样本写入历史环。
      xBuf[cursor] = i < ref.length ? ref[i] : 0
      cursor = (cursor + 1) % bufLen
      this.filled = Math.min(this.filled + 1, bufLen)
      const d = mic[i]
      if (this.filled >= this.delay + this.filterLength) {
        let y = 0
        let norm = 0
        let idx = (cursor - this.delay + bufLen) % bufLen
        for (let t = 0; t < this.filterLength; t++) {
          const x = xBuf[idx]
          y += this.w[t] * x
          norm += x * x
          idx = (idx - 1 + bufLen) % bufLen
        }
        const e = d - y
        // 发散防护：非有限误差收敛为 0（防 NaN/Inf 传染 RMS/打断/VAD 判定链）。
        out[i] = Number.isFinite(e) ? e : 0
        // NLMS 权重更新：仅在参考能量足够时训练（近零参考/未播时不放大权重，
        // 防「麦大声 + 参考窗近零」导致 gain 爆炸 → 权重失稳发散）。
        // A2.5 双讲冻结：用户说话时暂停更新，防滤波器被带偏。
        if (norm > MIN_REF_NORM && !this.frozen) {
          const denom = norm + this.eps
          const gain = (this.mu * e) / denom
          idx = (cursor - this.delay + bufLen) % bufLen
          for (let t = 0; t < this.filterLength; t++) {
            this.w[t] += gain * xBuf[idx]
            idx = (idx - 1 + bufLen) % bufLen
          }
        }
      } else {
        // 预热：参考历史不足，透传麦克风。
        out[i] = d
      }
    }
    this.cursor = cursor
    return out
  }
}

export interface DelayEstimateOptions {
  /** 采样率（默认 16000）。 */
  sampleRate?: number
  /** 最小滞后（样本，默认 0）。 */
  minLag?: number
  /** 最大滞后（样本，默认 300ms @ sampleRate）。 */
  maxLag?: number
  /** 相关窗下采样因子（默认 4；降计算量，16k 下分辨率 0.25ms）。 */
  downsample?: number
}

/**
 * 估计 mic 相对 ref 的 bulk delay（样本数，未下采样口径）。
 *
 * 用互相关在 [minLag, maxLag] 内找峰值（A2-1）：外放回声路径含 AudioContext 输出延迟 +
 * 系统混音 + 采集延迟（数十 ms 量级），NLMS 若 delay=0 靠长滤波器自行建模 bulk delay，
 * 收敛极慢、稳态失调大。此函数先量出 bulk delay，调用方据此平移参考、把滤波器缩短到
 * 只建模残余房间冲激响应，收敛速度与 ERLE 大幅提升。
 *
 * 返回 { lag, peak }：lag = 最佳滞后样本；peak = 归一化互相关峰值（0..1，接近 0 表示
 * 无清晰回声/无参考，调用方应据此拒绝应用）。
 */
export function estimateBulkDelay(
  mic: Float32Array,
  ref: Float32Array,
  opts: DelayEstimateOptions = {},
): { lag: number; peak: number } {
  const sr = opts.sampleRate ?? 16000
  const ds = Math.max(1, Math.floor(opts.downsample ?? 4))
  const minLag = Math.max(0, opts.minLag ?? 0)
  const maxLag = opts.maxLag ?? Math.floor((300 * sr) / 1000)
  const n = Math.min(mic.length, ref.length)
  if (n < ds * 64) return { lag: 0, peak: 0 } // 数据太短，不可靠
  const N = Math.floor(n / ds)
  const maxLagD = Math.floor(maxLag / ds)
  const minLagD = Math.floor(minLag / ds)
  if (maxLagD >= N) return { lag: 0, peak: 0 }

  // 下采样（ds 点盒式平均 = 简易抗混叠）+ 去均值（去除 DC 对相关的偏置）。
  const m = new Float32Array(N)
  const r = new Float32Array(N)
  let mSum = 0
  let rSum = 0
  for (let i = 0; i < N; i++) {
    let mv = 0
    let rv = 0
    for (let k = 0; k < ds; k++) {
      mv += mic[i * ds + k]
      rv += ref[i * ds + k]
    }
    mv /= ds
    rv /= ds
    m[i] = mv
    r[i] = rv
    mSum += mv
    rSum += rv
  }
  const mMu = mSum / N
  const rMu = rSum / N
  let mE = 0
  let rE = 0
  for (let i = 0; i < N; i++) {
    m[i] -= mMu
    r[i] -= rMu
    mE += m[i] * m[i]
    rE += r[i] * r[i]
  }
  if (mE < 1e-9 || rE < 1e-9) return { lag: 0, peak: 0 }

  // 前缀平方和：逐滞后用「重叠窗」能量归一化，消除全窗能量的 (N-d)/N 偏置
  // （对抗审查 Minor#2：大滞后峰值被系统性低估，250ms 从 0.95 降到 0.71）。
  const prefM = new Float32Array(N + 1)
  const prefR = new Float32Array(N + 1)
  for (let i = 0; i < N; i++) {
    prefM[i + 1] = prefM[i] + m[i] * m[i]
    prefR[i + 1] = prefR[i] + r[i] * r[i]
  }
  let bestLag = 0
  let bestPeak = -Infinity
  for (let d = minLagD; d <= maxLagD; d++) {
    let corr = 0
    for (let i = d; i < N; i++) corr += m[i] * r[i - d]
    const em = prefM[N] - prefM[d]
    const er = prefR[N - d]
    const peak = em > 1e-12 && er > 1e-12 ? corr / Math.sqrt(em * er) : 0
    if (peak > bestPeak) {
      bestPeak = peak
      bestLag = d
    }
  }
  return { lag: bestLag * ds, peak: bestPeak }
}

