/** 每条已完成回复的单次朗读按钮，放在复制按钮旁边。 */
export function ReplySpeakerButton({ bus, sessionId, messageId }: StatusBarProps & { messageId?: string }): React.ReactElement {
  const [reading, setReading] = useState(() => ({ sessionId: bus.ui.manualReadSessionId, messageId: bus.ui.manualReadMessageId }))
  const [pending, setPending] = useState(false)
  useEffect(() => bus.subscribe(({ ui }) => {
    setReading((prev) => prev.sessionId === ui.manualReadSessionId && prev.messageId === ui.manualReadMessageId
      ? prev : { sessionId: ui.manualReadSessionId, messageId: ui.manualReadMessageId })
  }), [bus])
  if (!sessionId || !messageId) return <></>
  const active = reading.sessionId === sessionId && reading.messageId === messageId
  return (
    <button type="button" data-dshvm="reply-speaker" data-dshvm-message-id={messageId}
      aria-label={active ? '停止朗读这条回复' : '朗读这条回复'} aria-pressed={active}
      title={active ? '停止朗读这条回复' : '朗读这条回复'} disabled={pending}
      onClick={() => {
        bus.warmAudio()
        setPending(true)
        void bus.readOnce(sessionId, messageId, !active).finally(() => setPending(false))
      }}
      style={{ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: 28, height: 28,
        padding: 0, border: 0, borderRadius: 6, background: 'transparent', cursor: 'pointer',
        color: active ? 'var(--dsw-alias-brand-primary)' : 'var(--dsw-alias-label-secondary)' }}>
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
        {active
          ? <rect x="7" y="7" width="10" height="10" rx="1.5" />
          : <><path d="M11.5 5.5 7 9H4.5a1 1 0 0 0-1 1v4a1 1 0 0 0 1 1H7l4.5 3.5v-13Z" /><path d="M15.5 9a4.5 4.5 0 0 1 0 6" /><path d="M18 6.5a8 8 0 0 1 0 11" /></>}
      </svg>
    </button>
  )
}

/** 使用 DSH 自身待交互事件，重复 key 由 Host 去重。 */
export function ApprovalWatcher({ bus, sessionId, useSessionStatus }: StatusBarProps & {
  useSessionStatus: <T>(selector: (snapshot: ReadonlyMap<string, { pendingInteraction?: { key: string; kind: string; toolName?: string } }>) => T) => T
}): React.ReactElement {
  const item = useSessionStatus(snapshot => sessionId ? snapshot.get(sessionId)?.pendingInteraction : undefined)
  useEffect(() => {
    if (!sessionId) return
    bus.setVisibleSession(sessionId)
    return () => { if (bus.ui.visibleSessionId === sessionId) bus.setVisibleSession(null) }
  }, [bus, sessionId])
  useEffect(() => {
    if (!sessionId || !item) return
      void fetch(`${location.origin}${BASE_PATH}/announce`, {
        method: 'POST', headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ sessionId, tabId: TAB_ID, key: item.key, kind: item.kind, toolName: item.toolName }),
      }).then((res) => {
        if (!res.ok && res.status !== 400) bus.setUi({ error: `审批语音提示失败：HTTP（请求状态）${res.status}，请检查插件服务。` })
      }).catch((error) => { debugLog('approval-announce-error', { detail: String(error) }); bus.setUi({ error: '审批语音提示失败，请检查插件服务。' }) })
  }, [bus, sessionId, item?.key, item?.kind, item?.toolName])
  return <></>
}

export function VoiceStatusBar({ bus, sessionId }: StatusBarProps): React.ReactElement {
  const [b, setB] = useState(() => ({ active: bus.activeSessionId, ui: bus.ui }))
  // P1-UX 状态条计时器：会话活跃期间按秒递增；会话切走 / 卸载时清零
  const [elapsedSec, setElapsedSec] = useState(0)

  useEffect(() => {
    return bus.subscribe(setB)
  }, [bus])

  useEffect(() => {
    if (b.active !== sessionId) {
      setElapsedSec(0)
      return
    }
    const id = setInterval(() => setElapsedSec((s) => s + 1), 1000)
    return () => clearInterval(id)
  }, [b.active, sessionId])

  const isActive = b.active === sessionId
  if (!isActive) {
    if (sessionId !== b.ui.visibleSessionId || (b.ui.readSessionId !== sessionId && !b.ui.error && !b.ui.ttsNotice && !b.ui.playing && b.ui.wakeStatus === 'off')) return <></>
    return <div role="status" aria-live="polite" style={{ boxSizing: 'border-box', width: '100%', maxWidth: 'var(--dsh-composer-card-max-width)', marginInline: 'auto', padding: '6px 10px', fontSize: 12, color: b.ui.error ? 'var(--dsw-alias-state-error-primary)' : 'var(--dsw-alias-label-secondary)' }}>
      {b.ui.error ?? b.ui.ttsNotice ?? (b.ui.playing ? '正在播报…' : b.ui.wakeStatus === 'loading' ? '正在加载本地唤醒模型…' : b.ui.wakeStatus === 'on' ? `常开唤醒中 · 说「${splitWakeWords(b.ui.wakeWord).join('」或「')}」开始；点击麦克风可直接输入` : '后续回复自动播报已开启')}
    </div>
  }

  const stateText =
    b.ui.state === 'loading-model'
      ? t('loadingModel')
      : b.ui.state === 'transcribing'
        ? t('recognizing')
        : b.ui.state === 'wake'
          ? t('sayWake').replace('{wake}', b.ui.wakeWord || t('wakeWord'))
          : b.ui.state === 'speech'
            ? b.ui.mode === 'hold'
              ? t('holdDots')
              : t('listening')
            : b.ui.playing // Fix：TTS 播放時顯示「朗讀中…」，防用戶誤以為系統無響應
              ? t('reading')
              : b.ui.turn === 'agent-speaking'
                ? t('thinking')
                : b.ui.mode === 'hold'
                  ? t('barHold')
                  : t('barListening')

  const bars = Array.from({ length: WAVE_BARS }, (_, i) => b.ui.levels[i] ?? 0)
  // P0-UX 双条 SVG 波形：第二组柱形表示 AI 朗读端电平
  const botBars = Array.from({ length: WAVE_BARS }, (_, i) => b.ui.botLevels[i] ?? 0)

  // P1-5 延迟埋点链展示（开发模式）：各相邻阶段耗时 + 说完→首音合计。
  const telParts: string[] = []
  const fmt = (ms: number): string => (ms >= 1000 ? `${(ms / 1000).toFixed(2)}s` : `${Math.round(ms)}ms`)
  const tel = b.ui.telemetry
  if (tel) {
    for (let i = 1; i < TELEMETRY_VIEW.length; i++) {
      const cur = tel[TELEMETRY_VIEW[i].stage]
      const prev = tel[TELEMETRY_VIEW[i - 1].stage]
      if (cur === undefined || prev === undefined) continue
      telParts.push(`${t(TELEMETRY_VIEW[i].key)} ${fmt(cur - prev)}`)
    }
    const begin = tel['utterance-end']
    const end = tel['first-audio-played']
    if (begin !== undefined && end !== undefined) telParts.push(`${t('telTotal')} ${fmt(end - begin)}`)
  }
  // 打断确认耗时（打断后独立展示；埋点链已被打断清空，此处单列）。
  if (b.ui.interruptConfirmMs !== undefined) {
    telParts.push(`${t('interruptConfirm')} ${fmt(b.ui.interruptConfirmMs)}`)
  }
  // 回声诊断（开发模式标定数据）：bulk delay / 回声地板 RMS / 当前残差 RMS。
  // 仅 telemetry 开启时显示——默认关，避免把 AEC 标定数据暴露给普通用户。
  if (telemetryEnabled && b.ui.echoLevels) {
    const el = b.ui.echoLevels
    telParts.push(
      `AEC delay=${Math.round(b.ui.echoDelayMs ?? 0)}ms floor=${el.floorRms.toFixed(4)} resid=${el.residualRms.toFixed(4)}`,
    )
  }

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        boxSizing: 'border-box',
        width: '100%',
        maxWidth: 'var(--dsh-composer-card-max-width)',
        marginInline: 'auto',
        gap: 2,
        padding: '6px 12px',
        borderRadius: 10,
        fontSize: 12,
        fontFamily: 'system-ui, sans-serif',
        color: '#3fb950',
        background: 'rgba(63, 185, 80, 0.08)',
        border: '1px solid rgba(63, 185, 80, 0.25)',
        animation: 'dshvm-fadein 0.2s ease',
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        {/* P0-UX 双条 SVG 波形：先 AI 朗读端(蓝)，后麦克风采集端(绿)；视觉左→右读"AI→我" */}
        {botBars.some((v) => v > 0) && (
          <span
            title={t('botLevelsHint')}
            style={{
              display: 'inline-flex',
              alignItems: 'flex-end',
              gap: 2,
              height: 14,
              flexShrink: 0,
            }}
          >
            {botBars.map((v, i) => (
              <span
                key={i}
                className="dshvm-bar-bot"
                style={{
                  height: `${3 + v * 12}px`,
                  background: '#58a6ff',
                  opacity: 0.4 + v * 0.6,
                }}
              />
            ))}
          </span>
        )}
        <span style={{ display: 'inline-flex', alignItems: 'flex-end', gap: 2, height: 14, flexShrink: 0 }}>
          {bars.map((v, i) => (
            <span
              key={i}
              className="dshvm-bar"
              style={{
                height: `${3 + v * 12}px`,
                background: '#3fb950',
                opacity: 0.4 + v * 0.6,
              }}
            />
          ))}
        </span>
        <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', flexGrow: 1 }}>
          {b.ui.error
            ? b.ui.error
            : b.ui.notice
              ? b.ui.notice
              : b.ui.idleWarn
                ? t('idleWarn30s')
                : b.ui.state === 'loading-model' || b.ui.model
                ? b.ui.model
                  ? `${t('loadingModel')} ${b.ui.model.file} ${b.ui.model.percent}%`
                  : stateText
                : b.ui.playing || b.ui.turn === 'agent-speaking'
                  ? stateText // 朗读/思考中优先显示状态，不显示用户旧的 partial（防遮蔽 thinking/reading）
                  : b.ui.state === 'wake' && b.ui.partial
                  ? `${stateText} · ${b.ui.partial}` // wake 待机：提示 + 实时转写并存（issue #10 问题 2，唤醒成败可自查）
                  : b.ui.partial
                    ? b.ui.partial
                    : b.ui.ttsNotice
                      ? b.ui.ttsNotice
                      : stateText}
        </span>
        {b.ui.isSpeech === true && (
          <span
            title={t('vadDetected')}
            style={{
              flexShrink: 0,
              padding: '0 6px',
              borderRadius: 8,
              fontSize: 10,
              lineHeight: '16px',
              color: '#ffa657',
              background: 'rgba(255, 166, 87, 0.15)',
              border: '1px solid rgba(255, 166, 87, 0.35)',
            }}
          >
            {t('vadDetected')}
          </span>
        )}
        {/* P1-UX 状态条计时器：会话时长（mm:ss），活跃期间按秒递增 */}
        {elapsedSec > 0 && (
          <span
            title={t('elapsedHint')}
            style={{
              flexShrink: 0,
              padding: '0 6px',
              borderRadius: 8,
              fontSize: 10,
              lineHeight: '16px',
              color: '#8b949e',
              fontVariantNumeric: 'tabular-nums',
              fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace',
            }}
          >
            {String(Math.floor(elapsedSec / 60)).padStart(2, '0')}:{String(elapsedSec % 60).padStart(2, '0')}
          </span>
        )}
        {b.ui.aecOff === true && (
          <span
            title={b.ui.bargeInDetectFallback ? t('bargeInDetectFallback') : t('aecOffHint')}
            style={{
              flexShrink: 0,
              padding: '0 6px',
              borderRadius: 8,
              fontSize: 10,
              lineHeight: '16px',
              color: '#ffa657',
              background: 'rgba(255, 166, 87, 0.15)',
              border: '1px solid rgba(255, 166, 87, 0.35)',
            }}
          >
            {b.ui.bargeInDetectFallback ? t('bargeInDetectFallback') : t('aecOff')}
          </span>
        )}
        <button
          onClick={() => {
            void bus.exit(sessionId!)
          }}
          style={{
            border: 'none',
            background: 'transparent',
            color: '#8b949e',
            cursor: 'pointer',
            fontSize: 12,
            flexShrink: 0,
          }}
        >
          {t('exit')}
        </button>
      </div>
      {telParts.length > 0 && (
        <div
          style={{
            fontSize: 11,
            color: '#8b949e',
            fontVariantNumeric: 'tabular-nums',
            fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace',
            whiteSpace: 'nowrap',
            overflowX: 'auto',
          }}
        >
          {telParts.join(' · ')}
        </div>
      )}
    </div>
  )
}

/** 右下角朗读浮层（Q6 朗读字幕 + playing 状态 + 跳过）。 */
interface OverlayProps extends VoiceSlotActions {
  sessionId?: string
}

export function VoiceOverlay({ bus }: OverlayProps): React.ReactElement {
  const [b, setB] = useState(() => ({ active: bus.activeSessionId, ui: bus.ui }))

  useEffect(() => {
    return bus.subscribe(setB)
  }, [bus])

  // 播放引擎只推当前语音会话的帧（模式隔离）；有朗读才显示浮层。
  if (!b.ui.playing) return <></>

  return (
    <div
      role="status"
      aria-live="polite"
      style={{
        position: 'fixed',
        right: 16,
        bottom: 96, // 上移，避免盖住底部输入框/麦克风按钮
        zIndex: 9999,
        display: 'flex',
        alignItems: 'center',
        gap: 10,
        padding: '8px 14px',
        borderRadius: 999,
        // 批 3：4 档字号（0/1/2/3 → 12/14/18/24 px）。默认 0=12px 与现状字节等价。
        fontSize: [12, 14, 18, 24][b.ui.boot?.captionFontSize ?? 0],
        fontFamily: 'system-ui, sans-serif',
        // 批 G 任务 5：浮层默认 'auto'——触屏需要命中内部「跳过」按钮；外层无 cursor:
        // default 由按钮自身 cursor:pointer 表达，文本区不显 pointer。
        // touchAction: 'manipulation' 阻止双击放大与连续点击 300ms 延迟（保留手势语义）。
        pointerEvents: 'auto',
        touchAction: 'manipulation',
        cursor: 'default',
        // 批 H 任务 2：背景与文字走 dsw-alias 主题变量（与 settings-form.tsx:32 / :35 一致），
        // 浅色主题下不再硬编码深色，a11y 与可读性同步提升。
        background: 'var(--dsw-alias-bg-layer-3)',
        backdropFilter: 'blur(14px)',
        WebkitBackdropFilter: 'blur(14px)',
        border: '1px solid rgba(255, 255, 255, 0.08)',
        boxShadow: '0 8px 28px rgba(0, 0, 0, 0.4)',
        color: 'var(--dsw-alias-label-primary)',
        // 批 3：3 档宽度（0/1/2 → 50vw/70vw/90vw）。默认 1=70vw。
        maxWidth: ['50vw', '70vw', '90vw'][b.ui.boot?.captionMaxWidth ?? 1],
        // 批 3：浮层最大高度（24px 多行时不盖输入框）。maxHeight 30vh + overflow hidden。
        maxHeight: '30vh',
        overflow: 'hidden',
        animation: 'dshvm-fadein 0.25s ease',
      }}
    >
      <span style={{ display: 'inline-flex', alignItems: 'flex-end', gap: 2, height: 12, flexShrink: 0 }}>
        {[0, 1, 2].map((i) => (
          <span
            key={i}
            style={{
              width: 3,
              height: '100%',
              borderRadius: 99,
              background: '#2ea043',
              transformOrigin: 'bottom',
              animation: `dshvm-eq 0.85s ease-in-out ${i * 0.18}s infinite`,
            }}
          />
        ))}
      </span>
      <span
        key={b.ui.playingCaption ?? 'idle'}
        className="dshvm-caption"
        style={{
          // 批 3：换行（中文长 URL 等场景）。注：whiteSpace:normal + overflowWrap:anywhere 与 ellipsis 互斥（nowrap 才需要 ellipsis），
          //   接受换行后 ellipsis 失效——计划 §5.2 已显式声明。
          whiteSpace: 'normal',
          overflowWrap: 'anywhere',
          wordBreak: 'break-word',
          flex: 1,
          minWidth: 0,
        }}
      >
        {b.ui.playingCaption ?? t('reading')}
      </span>
      <button
        onClick={() => bus.skipAudio()}
        aria-label={t('skipReading')}
        style={{
          border: 'none',
          background: 'rgba(255, 255, 255, 0.14)',
          color: '#fff',
          borderRadius: 999,
          padding: '3px 12px',
          fontSize: 11,
          cursor: 'pointer',
          flexShrink: 0,
          pointerEvents: 'auto', // 仅此按钮可点
        }}
      >
        {t('skip')}
      </button>
    </div>
  )
}

/**
 * 情感标签解析与剥离（批 4 / ADR-0007 步 1，纯函数模块）。
 *
 * 计划依据：docs/plan/implementation-plan-2026-09-14.md §6。
 * 能力边界（§6.0）：Kokoro/VITS 不支持 SSML；本批只做 PCM 后处理可实现的：
 *   - `<break N ms>` → 段间插入 N 毫秒静音 PCM（落地由 tts-local.synthesize 内部多段合成实现）
 *   - `<whisper>...</whisper>` → 作用域内段落 PCM 增益 ×0.5（成对标签；ADR-0007 原文是单标签，本偏差已在 §6 落地注记）
 *   - `<laugh>` / `<sigh>` / `<emphasis>` → 剥离不读出（防逐字朗读；真声音留给第二步 Edge）
 *
 * 不持有任何状态、不调用任何 IO、不依赖 cordis/dsh/sherpa——所有依赖均由调用方注入。
 */

/** 单标签（剥离不读出 / 段间插静音）。 */
export type EmotionTag = 'laugh' | 'sigh' | 'emphasis'

/** 段落描述：纯文本 + 可选增益（whisper 作用域内段落 gain=0.5）+ 可选前置静音（紧跟在它之前的 break 标签的 ms 数，落到段序列里的「段」即插在该段前）。 */
export interface EmotionSegment {
  /** 段落纯文本（不含任何 emotion 标签；标签已被消费）。 */
  text: string
  /** 该段是否在 <whisper> 作用域内（true → 合成后 PCM 乘 0.5）。 */
  whisper: boolean
}

/** 标签正则：<break N ms> / <whisper> / </whisper> / <laugh> / <sigh> / <emphasis>。大小写不敏感（gi 标志）。 */
const TAG_RE = /<\s*(break\s+(?<ms>\d+)\s*ms|whisper|\/whisper|laugh|sigh|emphasis)\s*>/gi

/**
 * 将含标签文本解析为段序列（每段带 whisper 状态）。
 * 单标签（laugh/sigh/emphasis/break）：消费但不产生段落，break 的毫秒数作为前一段的 preBreakMs。
 * 成对 <whisper>...</whisper>：消费，作用域内的段落 whisper=true；嵌套/不平衡时降级为「全段退回非 whisper」（保守语义：避免误降音量）。
 * 空段文本会被丢弃（不输出空段）；连续 break 累加到最后一个非空段之前的 preBreakMs。
 */
export function parseEmotionTags(raw: string): EmotionSegment[] {
  const out: EmotionSegment[] = []
  let buf = ''
  let whisper = false
  let pendingBreakMs = 0

  const flush = (): void => {
    const t = buf.trim()
    buf = ''
    if (t.length === 0) return
    const seg: EmotionSegment = { text: t, whisper }
    // preBreakMs 由调用方在 flush 之后、push 之前注入（保留到「下一段」语义）。
    // 这里不读 pendingBreakMs——break 分支已 flush 后再注入到 seg。
    out.push(seg)
  }

  // 用 matchAll 顺序扫描；每个 match 替换为「flush 之前累积的 buf + 标签处理」
  let lastEnd = 0
  for (const m of raw.matchAll(TAG_RE)) {
    const idx = m.index ?? 0
    buf += raw.slice(lastEnd, idx)
    lastEnd = idx + m[0].length
    const tag = (m[1] ?? '').toLowerCase().trim()
    if (tag.startsWith('break')) {
      const ms = Number(m.groups?.ms ?? 0)
      if (!Number.isFinite(ms) || ms <= 0) continue
      // break 是结构分隔符：先 flush 已累积文本（≥1 个非空字符）。
      // 语义：break ms 累加到「它之前的最后一段」的 preBreakMs（不论 buf 是否空）。
      if (buf.trim().length > 0) {
        flush()
      }
      const last = out[out.length - 1]
      if (last) {
        ;(last as EmotionSegment & { preBreakMs?: number }).preBreakMs =
          ((last as { preBreakMs?: number }).preBreakMs ?? 0) + ms
      } else {
        // break 在最前面（无任何已 flush 段）→ 累加到 pendingBreakMs，等下一段文本到来时再挂
        pendingBreakMs += ms
      }
    } else if (tag === 'whisper') {
      // 进入 whisper 作用域：先 flush 已累积文本（那段不是 whisper）
      flush()
      whisper = true
    } else if (tag === '/whisper') {
      flush()
      whisper = false
    } else {
      // laugh / sigh / emphasis：单标签，剥离不读出；不产生段
      // —— 但若之前累积了文本，应 flush 成段（标签相当于"段尾标点"前的边界）
      // 这里选择不在标签处强行切段，因为它们语义上不是分隔；flush 留给后续真实文本到达时
      // 但若标签出现在文本末尾，需要把累积的文本刷出
      // ——我们不在这里 flush，留给文本继续累积时由下一次 flush 触发；末尾累积在循环结束后统一 flush
    }
  }
  buf += raw.slice(lastEnd)
  flush()
  // 收尾：若仍有 pendingBreakMs（break 在最末无后续段文本），累加到「最后一段」
  if (pendingBreakMs > 0) {
    const last = out[out.length - 1]
    if (last) {
      ;(last as EmotionSegment & { preBreakMs?: number }).preBreakMs =
        ((last as { preBreakMs?: number }).preBreakMs ?? 0) + pendingBreakMs
    }
    pendingBreakMs = 0
  }

  // 不平衡处理：「有打开无关闭」时把 out 中所有 whisper=true 段降级为 false
  // ——保守语义：开启而无关闭 → 视作未开启（不误降音量）。
  if (whisper) {
    for (const s of out) s.whisper = false
  }
  return out
}

/**
 * 声学 fixture 录制器（ADR-0005 第二批：真机录音）——**调试工具，默认完全关闭**。
 *
 * 目的：把真机上的 mic / TTS 参考 / AEC 残差三条时间线录下来，供离线重放与标定。
 * 首要待测量的问题：**AEC 后残差是否保留语音包络（crest factor）**——它决定
 * docs/findings/2026-09-02-echo-gate-ratchet.md 里哪个分支成立。
 *
 * ── 开关（localStorage，改完刷新页面）──
 *   localStorage.setItem('dsh-voice-mode.record', 'meta')  // 只录逐帧统计（几十 KB）
 *   localStorage.setItem('dsh-voice-mode.record', 'full')  // 统计 + 音轨（可离线重放全链路）
 *   localStorage.removeItem('dsh-voice-mode.record')       // 关闭
 *
 * ── 用法 ──
 *   进入语音模式即自动开录，右上角出现红色 REC 徽标。
 *   F8  = 标注「我开始说话 / 我说完了」（打断类场景需要；纯听不需要）
 *   F9  = 立即保存并下载
 *   退出语音模式 = 自动保存并下载
 *
 * ── 设计约束 ──
 * 自包含：不接入 React 状态、不改状态条组件。徽标是自己 append 的 DOM，
 * 删掉本文件 + 两处调用点即可完全移除。
 *
 * 产物：单个 .json（schema dsh-voice-mode/fixture@1），音轨为 base64 Int16。
 */

/** 录制档位。 */
export type RecordMode = 'off' | 'meta' | 'full'

const FLAG = 'dsh-voice-mode.record'
/** 上限：防长时间录制吃爆内存（到点自动停并落盘）。 */
const MAX_SECONDS = 180
const SAMPLE_RATE = 16000

/** 逐帧统计（64ms 一条，180s ≈ 2800 条）。 */
interface FrameMeta {
  /** 相对录制起点的毫秒。 */
  t: number
  /** 判定链实际使用的残差 RMS（AEC 之后）。 */
  rms: number
  /** AEC 之前的 mic RMS（原生 AEC 已生效过）。 */
  mic: number
  /** 参考信号 RMS（0 = 无参考/未播放）。 */
  ref: number
  /** 回声地板。 */
  fl: number
  /** 残差峰值。 */
  pk: number
  /** doubleTalk。 */
  dt: 0 | 1
  /** 播放中（含尾音宽限，asr.ts 口径）。 */
  pt: 0 | 1
  /** host 下行 isSpeech（异步到达，盖在最近一帧上；缺省表示本帧无 VAD 信息）。 */
  spk?: 0 | 1
}

interface Mark {
  t: number
  kind: string
  note?: string
}

/** 检测通道一次往返（A 档：停顿归因）。 */
interface DetectRtt {
  /** 发起时刻（相对录制起点，ms）。 */
  t: number
  /** 往返耗时 ms。 */
  rtt: number
  /** 1 = 拿到响应，0 = 超时/网络失败。 */
  ok: 0 | 1
  /** 本次上行样本数。 */
  n: number
}

/** 读取当前档位（每次读，改完刷新即可生效）。 */
export function recordMode(): RecordMode {
  try {
    const v = localStorage.getItem(FLAG)
    if (v === 'full') return 'full'
    if (v === 'meta' || v === '1') return 'meta'
  } catch {
    // localStorage 不可用（隐私模式）：视为关闭
  }
  return 'off'
}

/** Int16 累积缓冲（分块存，落盘时一次性拼接）。 */
class Track {
  private chunks: Int16Array[] = []
  private total = 0
  push(f: Float32Array): void {
    const out = new Int16Array(f.length)
    for (let i = 0; i < f.length; i++) {
      const v = Math.max(-1, Math.min(1, f[i]))
      out[i] = v < 0 ? v * 0x8000 : v * 0x7fff
    }
    this.chunks.push(out)
    this.total += out.length
  }
  get length(): number {
    return this.total
  }
  toBase64(): string {
    const all = new Int16Array(this.total)
    let off = 0
    for (const c of this.chunks) {
      all.set(c, off)
      off += c.length
    }
    const bytes = new Uint8Array(all.buffer)
    // 分块转 base64（一次性 apply 会在大数组上爆栈）
    let bin = ''
    const STEP = 0x8000
    for (let i = 0; i < bytes.length; i += STEP) {
      bin += String.fromCharCode(...bytes.subarray(i, i + STEP))
    }
    return btoa(bin)
  }
  clear(): void {
    this.chunks = []
    this.total = 0
  }
}

export interface RecorderEnv {
  build?: string
  /** track.getSettings().echoCancellation */
  nativeAec?: boolean
  /** 自研 NLMS 是否被旁路（原生 AEC 生效时为 true） */
  echoBypass?: boolean
  ctxRate?: number
  mode?: string
  bargeInMode?: string
  echoGateDb?: number
  interruptLevel?: number
  ttsEngine?: string
  voice?: string
}

class FixtureRecorder {
  private mode: RecordMode = 'off'
  private active = false
  private startedAt = 0
  private frames: FrameMeta[] = []
  private marks: Mark[] = []
  private detects: DetectRtt[] = []
  private micTrack = new Track()
  private refTrack = new Track()
  private resTrack = new Track()
  /** 残差与 mic 是否出现过差异（原生 AEC 失效时自研 NLMS 生效）——决定是否落残差轨。 */
  private resDiffers = false
  private env: RecorderEnv = {}
  private badge: HTMLElement | null = null
  private userSpeaking = false
  private keyHandler: ((e: KeyboardEvent) => void) | null = null

  get isActive(): boolean {
    return this.active
  }

  /** 进入语音模式时调用。档位为 off 时什么都不做。 */
  begin(env: RecorderEnv): void {
    const mode = recordMode()
    if (mode === 'off') {
      this.mode = 'off'
      return
    }
    if (this.active) this.save('restart')
    this.mode = mode
    this.active = true
    this.startedAt = Date.now()
    this.frames = []
    this.marks = []
    this.detects = []
    this.micTrack.clear()
    this.refTrack.clear()
    this.resTrack.clear()
    this.resDiffers = false
    this.userSpeaking = false
    this.env = env
    this.mark('begin', mode)
    this.mountBadge()
    this.bindKeys()
    // 控制台兜底入口：部分笔记本 F8/F9 被 Fn 功能键占用，键盘标注可能触发不了。
    try {
      ;(window as unknown as Record<string, unknown>).__dshvmRec = {
        说话开始: () => this.setUserSpeaking(true),
        说话结束: () => this.setUserSpeaking(false),
        保存: () => this.save('console'),
        标注: (kind: string, note?: string) => this.mark(kind, note),
        状态: () => ({ mode: this.mode, 帧数: this.frames.length, 标注数: this.marks.length, 说话中: this.userSpeaking }),
      }
    } catch {
      // ignore
    }
    console.log(
      `[dsh-voice][rec] 开始录制（${mode}）· F8=标注说话 · F9=保存下载\n` +
        `[dsh-voice][rec] 键盘不灵时用控制台：__dshvmRec.说话开始() / .说话结束() / .保存() / .状态()`,
    )
  }

  /**
   * 逐帧写入。在 asr.ts handleAudio 里 AEC 与门控统计算完之后调用。
   * micPre = AEC 前（重采样后）；ref = 参考窗；res = AEC 后残差（判定链实际输入）。
   */
  frame(
    micPre: Float32Array,
    ref: Float32Array | null,
    res: Float32Array,
    stats: { rms: number; floorRms: number; peakRms: number; doubleTalk: boolean; playingTail: boolean },
  ): void {
    if (!this.active) return
    const t = Date.now() - this.startedAt
    if (t > MAX_SECONDS * 1000) {
      this.mark('auto-stop', `到达 ${MAX_SECONDS}s 上限`)
      this.save('maxlen')
      return
    }
    this.frames.push({
      t,
      rms: round6(stats.rms),
      mic: round6(rmsOf(micPre)),
      ref: round6(ref ? rmsOf(ref) : 0),
      fl: round6(stats.floorRms),
      pk: round6(stats.peakRms),
      dt: stats.doubleTalk ? 1 : 0,
      pt: stats.playingTail ? 1 : 0,
    })
    if (this.mode === 'full') {
      this.micTrack.push(micPre)
      this.refTrack.push(ref ?? new Float32Array(micPre.length))
      if (res !== micPre) {
        // 自研 AEC 实际生效过：残差与 mic 不是同一块，单独落轨
        if (!this.resDiffers) this.resDiffers = true
        this.resTrack.push(res)
      } else if (this.resDiffers) {
        this.resTrack.push(res)
      }
    }
    this.refreshBadge()
  }

  /**
   * 检测通道一次往返（A 档埋点）：分离「请求在途慢」与「客户端没排上」。
   * 停顿归因的唯一依据——回报间隔 = 往返耗时 + 客户端等待，此处记的是前者。
   */
  noteDetect(sentAt: number, rttMs: number, ok: boolean, samples: number): void {
    if (!this.active) return
    this.detects.push({ t: sentAt - this.startedAt, rtt: rttMs, ok: ok ? 1 : 0, n: samples })
  }

  /** host 下行 isSpeech：盖在最近一帧上。 */
  noteIsSpeech(speech: boolean | undefined): void {
    if (!this.active || speech === undefined) return
    const last = this.frames[this.frames.length - 1]
    if (last) last.spk = speech ? 1 : 0
  }

  /** 播放态（裸口径）变化 / 打断触发 / 句子边界等事件。 */
  mark(kind: string, note?: string): void {
    if (!this.active && kind !== 'begin') return
    this.marks.push({ t: Date.now() - this.startedAt, kind, note })
  }

  /** 保存并触发下载。reason 只用于文件名与日志。 */
  save(reason = 'manual'): void {
    if (!this.active) return
    this.active = false
    this.unbindKeys()
    this.unmountBadge()
    const durationMs = Date.now() - this.startedAt
    const payload: Record<string, unknown> = {
      schema: 'dsh-voice-mode/fixture@1',
      recordedAt: new Date(this.startedAt).toISOString(),
      reason,
      mode: this.mode,
      sampleRate: SAMPLE_RATE,
      durationMs,
      env: this.env,
      frames: this.frames,
      marks: this.marks,
      detects: this.detects,
    }
    if (this.mode === 'full' && this.micTrack.length > 0) {
      payload.audio = {
        encoding: 'int16le-base64',
        mic: this.micTrack.toBase64(),
        ref: this.refTrack.toBase64(),
        ...(this.resDiffers ? { res: this.resTrack.toBase64() } : {}),
      }
      // res 缺省 = 与 mic 逐样本相同（原生 AEC 生效时自研 NLMS 被旁路）
    }
    const name = `dshvm-fixture-${new Date(this.startedAt).toISOString().replace(/[:.]/g, '-')}-${reason}.json`
    try {
      const blob = new Blob([JSON.stringify(payload)], { type: 'application/json' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = name
      document.body.appendChild(a)
      a.click()
      a.remove()
      setTimeout(() => URL.revokeObjectURL(url), 10000)
      console.log(
        `[dsh-voice][rec] 已保存 ${name}：${this.frames.length} 帧 / ${(durationMs / 1000).toFixed(1)}s / 标注 ${this.marks.length} 条 / 检测往返 ${this.detects.length} 次`,
      )
    } catch (e) {
      console.warn('[dsh-voice][rec] 保存失败：' + String(e))
    }
    this.micTrack.clear()
    this.refTrack.clear()
    this.resTrack.clear()
  }

  /** 说话区间标注（键盘与控制台入口共用；重复置同一状态不产生重复标注）。 */
  setUserSpeaking(on: boolean): void {
    if (!this.active || this.userSpeaking === on) return
    this.userSpeaking = on
    this.mark(on ? 'user-speech-start' : 'user-speech-end')
    console.log(`[dsh-voice][rec] 标注：${on ? '开始说话' : '说完了'}`)
    this.refreshBadge()
  }

  // ── 键盘标注 ──
  private bindKeys(): void {
    this.keyHandler = (e: KeyboardEvent) => {
      if (e.key === 'F8') {
        e.preventDefault()
        this.setUserSpeaking(!this.userSpeaking)
      } else if (e.key === 'F9') {
        e.preventDefault()
        this.save('hotkey')
      }
    }
    window.addEventListener('keydown', this.keyHandler, true)
  }

  private unbindKeys(): void {
    if (this.keyHandler) window.removeEventListener('keydown', this.keyHandler, true)
    this.keyHandler = null
  }

  // ── 徽标（自包含 DOM，不接 React）──
  private mountBadge(): void {
    try {
      const el = document.createElement('div')
      el.style.cssText = [
        'position:fixed',
        'top:8px',
        'right:8px',
        'z-index:2147483647',
        'padding:6px 10px',
        'border-radius:6px',
        'background:rgba(180,20,20,.92)',
        'color:#fff',
        'font:12px/1.4 ui-monospace,SFMono-Regular,Consolas,monospace',
        'pointer-events:none',
        'white-space:pre',
      ].join(';')
      document.body.appendChild(el)
      this.badge = el
      this.refreshBadge()
    } catch {
      // DOM 不可用：静默（录制本身不受影响）
    }
  }

  private refreshBadge(): void {
    if (!this.badge) return
    const s = ((Date.now() - this.startedAt) / 1000).toFixed(1)
    const last = this.frames[this.frames.length - 1]
    this.badge.textContent =
      `● REC ${this.mode}  ${s}s  ${this.frames.length}帧` +
      (this.userSpeaking ? '  [说话中]' : '') +
      (last ? `\nresid ${last.rms.toFixed(4)}  floor ${last.fl.toFixed(4)}  peak ${last.pk.toFixed(4)}` : '') +
      '\nF8 标注说话 · F9 保存'
  }

  private unmountBadge(): void {
    try {
      this.badge?.remove()
    } catch {
      // ignore
    }
    this.badge = null
  }
}

function rmsOf(x: Float32Array): number {
  if (x.length === 0) return 0
  let s = 0
  for (let i = 0; i < x.length; i++) s += x[i] * x[i]
  return Math.sqrt(s / x.length)
}

const round6 = (v: number): number => Math.round(v * 1e6) / 1e6

/** 全局单例（与 client.tsx 的全局单活架构一致）。 */
export const fixtureRecorder = new FixtureRecorder()

export interface AudioCapture {
  start(mic: MediaStream, onChunk: (sampleRate: number, samples: Float32Array) => void): Promise<void>;
  suspend(): Promise<void>;
  resume(): Promise<void>;
  close(): Promise<void>;
}

const PROCESSOR = 'talk-kws-capture';

/** Microphone -> ~100 ms Float32 blocks, via the kws-capture-worklet.js asset. Browser only. */
export class WorkletAudioCapture implements AudioCapture {
  private context: AudioContext | null = null;
  // The graph MUST be referenced from JS: Chrome garbage-collects a MediaStreamAudioSourceNode (and the worklet
  // node behind it) that nothing points to, and capture then goes silent after the first GC — found by the
  // end-to-end test, where wake-word detection died after one 60 s conversation.
  private graph: { source: MediaStreamAudioSourceNode; node: AudioWorkletNode; mute: GainNode } | null = null;

  constructor(private readonly workletUrl: string) {}

  async start(mic: MediaStream, onChunk: (sampleRate: number, samples: Float32Array) => void): Promise<void> {
    const context = new AudioContext();
    this.context = context;
    await context.audioWorklet.addModule(this.workletUrl);
    const node = new AudioWorkletNode(context, PROCESSOR, { numberOfInputs: 1, numberOfOutputs: 1, channelCount: 1, channelCountMode: 'explicit' });
    node.port.onmessage = (ev: MessageEvent<{ sampleRate: number; samples: Float32Array }>) => onChunk(ev.data.sampleRate, ev.data.samples);
    const source = context.createMediaStreamSource(mic);
    // A node nobody pulls from may never be processed; route it to the output through a muted gain.
    const mute = context.createGain();
    mute.gain.value = 0;
    source.connect(node);
    node.connect(mute);
    mute.connect(context.destination);
    this.graph = { source, node, mute };
  }

  // Both call through unconditionally. `state` lags: it stays 'running' until a pending suspend()
  // settles, so gating on it made a resume() issued right after a suspend() do nothing at all and
  // leave the capture stopped. Browsers make both idempotent, so the redundant calls cost nothing.
  async suspend(): Promise<void> {
    if (this.context) await this.context.suspend();
  }

  async resume(): Promise<void> {
    if (this.context) await this.context.resume();
  }

  async close(): Promise<void> {
    const { context, graph } = this;
    this.context = null;
    this.graph = null;
    if (graph) {
      graph.node.port.onmessage = null;
      graph.source.disconnect();
      graph.node.disconnect();
      graph.mute.disconnect();
    }
    if (context && context.state !== 'closed') await context.close();
  }
}

import { pinyin } from 'pinyin-pro';
import type { KeywordSpec } from './types.ts';
import { MODEL_TOKENS } from './model-tokens.ts';

// The model writes ü as u after j/q/x/y (pypinyin's non-strict finals); pinyin-pro keeps the umlaut.
const PLAIN_U: Readonly<Record<string, string>> = { ü: 'u', ǖ: 'ū', ǘ: 'ú', ǚ: 'ǔ', ǜ: 'ù' };
const UMLAUT_DROPPING_INITIALS: ReadonlySet<string> = new Set(['j', 'q', 'x', 'y']);
const HINT = 'pass { text, tokens } with explicit tokens if the automatic pinyin is wrong (polyphones)';
/**
 * 一 and 不 change tone depending on what follows (一起 yì, 一定 yí, 第一 yì, 不对 bú, 不客气 bú…), and
 * the rules the official sherpa-onnx text2token tool applies are not the ones pinyin-pro applies:
 * they disagree on 4 of the 10 phrases in golden-tokens-sandhi.json. Both spellings are valid model
 * units, so a wrong guess passes validation and then silently never fires. Refuse to guess instead.
 */
const TONE_SANDHI_CHARACTERS = /[一不]/;

function compact(text: string): string {
  return text.replace(/\s+/g, '');
}

function assertKnown(phrase: string, tokens: readonly string[]): void {
  const unknown = tokens.find((t) => !MODEL_TOKENS.has(t));
  if (unknown !== undefined) {
    throw new Error(`wake keyword "${phrase}" needs the unit "${unknown}", which the KWS model does not know; ${HINT}`);
  }
}

/** Chinese text -> the model's units: per syllable, initial then tone-marked final (e.g. 小云 -> x iǎo y ún). */
export function textToTokens(text: string): string[] {
  const phrase = compact(text);
  if (!phrase) throw new Error('wake keyword is empty');
  const initials = pinyin(phrase, { pattern: 'initial', type: 'array' });
  const finals = pinyin(phrase, { pattern: 'final', toneType: 'symbol', type: 'array' });
  const characters = Array.from(phrase);
  const tokens: string[] = [];
  initials.forEach((initial, i) => {
    let final = finals[i] ?? '';
    // pinyin-pro silently returns nothing for digits, latin letters, punctuation…: refuse instead of dropping them
    if (!initial && !final) {
      throw new Error(`wake keyword "${phrase}" contains "${characters[i] ?? '?'}", which has no pinyin; use Chinese characters only`);
    }
    if (UMLAUT_DROPPING_INITIALS.has(initial)) final = final.replace(/[üǖǘǚǜ]/g, (c) => PLAIN_U[c] ?? c);
    if (initial) tokens.push(initial);
    if (final) tokens.push(final);
  });
  if (TONE_SANDHI_CHARACTERS.test(phrase)) {
    throw new Error(
      `wake keyword "${phrase}" contains 一 or 不, whose tone changes with the word that follows. ` +
      `The automatic conversion guesses "${tokens.join(' ')}", which the official sherpa-onnx ` +
      'text2token tool often spells differently — and because both spellings are valid model units, ' +
      'a wrong guess is accepted and then never matches anything. Pass { text, tokens } with the ' +
      'tokens that tool prints (see tools/kws-wasm/README.md, "polyphones and 一/不").',
    );
  }
  assertKnown(phrase, tokens);
  return tokens;
}

/** The `keywords` string sherpa-onnx expects: one "<tokens> @<display name>" line per wake phrase. */
export function buildKeywordsConfig(specs: readonly KeywordSpec[]): string {
  if (specs.length === 0) throw new Error('wake.keywords needs at least one keyword');
  const seen = new Set<string>();
  return specs
    .map((spec) => {
      const phrase = compact(typeof spec === 'string' ? spec : spec.text);
      if (!phrase) throw new Error('wake keyword is empty');
      if (seen.has(phrase)) throw new Error(`duplicate wake keyword "${phrase}"`);
      seen.add(phrase);
      let tokens: string[];
      if (typeof spec === 'string') {
        tokens = textToTokens(phrase);
      } else {
        tokens = spec.tokens.trim().split(/\s+/).filter(Boolean);
        if (tokens.length === 0) throw new Error(`wake keyword "${phrase}" has empty tokens`);
        assertKnown(phrase, tokens);
      }
      return `${tokens.join(' ')} @${phrase}`;
    })
    .join('\n');
}

