import type { KwsEngine, WakeOptions } from './types.ts';
import { WorkletAudioCapture, type AudioCapture } from './audio-capture.ts';
import { buildKeywordsConfig } from './keyword-tokens.ts';

export type { AudioCapture } from './audio-capture.ts';

export interface KwsWorkerLike {
  postMessage(message: unknown, transfer?: Transferable[]): void;
  terminate(): void;
  onmessage: ((ev: { data: unknown }) => void) | null;
  onerror: ((ev: { message?: string }) => void) | null;
}

export interface SherpaKwsDeps {
  createWorker(url: string): KwsWorkerLike;
  createCapture(workletUrl: string): AudioCapture;
  now(): number;
  loadTimeoutMs: number;
}

type WorkerMessage = { type: 'ready' } | { type: 'inited' } | { type: 'keyword'; keyword: string } | { type: 'fatal'; message: string };

const DEFAULTS = { threshold: 0.25, score: 1.0, cooldownMs: 1500, loadTimeoutMs: 30000 } as const;
const DISPOSED_MESSAGE = 'KWS engine was disposed while loading';

// The DOM Worker's handler properties are typed against MessageEvent/ErrorEvent, so it is not structurally a
// KwsWorkerLike; adapt it instead of widening the interface to DOM types (keeps fakes trivial).
function browserWorker(url: string): KwsWorkerLike {
  const worker = new Worker(url);
  const like: KwsWorkerLike = {
    postMessage: (message, transfer) => worker.postMessage(message, transfer ?? []),
    terminate: () => worker.terminate(),
    onmessage: null,
    onerror: null,
  };
  worker.onmessage = (ev: MessageEvent<unknown>) => like.onmessage?.({ data: ev.data });
  worker.onerror = (ev: ErrorEvent) => like.onerror?.({ message: ev.message });
  return like;
}

function isWorkerMessage(data: unknown): data is WorkerMessage {
  return typeof data === 'object' && data !== null && typeof (data as { type?: unknown }).type === 'string';
}

/** Local wake-word detection: sherpa-onnx KWS in a Web Worker, fed by an AudioWorklet. Audio never leaves the page. */
export class SherpaKwsEngine implements KwsEngine {
  private readonly deps: SherpaKwsDeps;
  private readonly handlers = new Set<(keyword: string) => void>();
  private readonly errorHandlers = new Set<(message: string) => void>();
  private worker: KwsWorkerLike | null = null;
  private capture: AudioCapture | null = null;
  private listening = false;
  private broken = false;
  private disposed = false;
  /** Set by handshake() while a load() is waiting on the worker; lets dispose() settle it immediately. */
  private cancelLoad: ((reason: Error) => void) | null = null;
  private lastHitAt = Number.NEGATIVE_INFINITY;
  /** The capture operation in flight, and the one desired state waiting for it — see setCaptureRunning(). */
  private captureOp: Promise<void> | null = null;
  private pendingCapture: (() => Promise<void>) | null = null;

  constructor(private readonly options: WakeOptions, deps: Partial<SherpaKwsDeps> = {}) {
    this.deps = {
      createWorker: browserWorker,
      createCapture: (url) => new WorkletAudioCapture(url),
      now: () => performance.now(),
      loadTimeoutMs: DEFAULTS.loadTimeoutMs,
      ...deps,
      // The option is the integrator's, so it outranks the default this class ships with.
      ...(options.loadTimeoutMs === undefined ? {} : { loadTimeoutMs: options.loadTimeoutMs }),
    };
  }

  onKeyword(handler: (keyword: string) => void): () => void {
    this.handlers.add(handler);
    return () => this.handlers.delete(handler);
  }

  onError(handler: (message: string) => void): () => void {
    this.errorHandlers.add(handler);
    return () => this.errorHandlers.delete(handler);
  }

  async load(mic: MediaStream): Promise<void> {
    const keywords = buildKeywordsConfig(this.options.keywords); // fail on bad config before fetching 12 MB of wasm
    // A keyword whose tokens are wrong is invisible — it simply never fires — so say out loud what
    // the spotter is being given. Once per load, and the only thing this module ever prints.
    console.info(`[dsh-voice-hub] 本地唤醒词模型音节：\n${keywords}`);
    const base = this.options.assetsPath.endsWith('/') ? this.options.assetsPath : `${this.options.assetsPath}/`;
    this.disposed = false;
    this.broken = false; // a stale `fatal` from a previous load on this instance must not silence the new one
    this.lastHitAt = Number.NEGATIVE_INFINITY;
    this.captureOp = null; // nothing queued against the previous capture may delay this one
    this.pendingCapture = null;
    try {
      const worker = this.deps.createWorker(`${base}kws-worker.js`);
      this.worker = worker;
      await this.handshake(worker, keywords); // rejects immediately with DISPOSED_MESSAGE if dispose() cancels it
      this.assertNotDisposed(); // dispose() may have landed in the microtask gap right after the handshake resolved
      const capture = this.deps.createCapture(`${base}kws-capture-worklet.js`);
      this.capture = capture;
      await capture.start(mic, (sampleRate, samples) => {
        if (this.listening && this.worker) this.worker.postMessage({ type: 'audio', sampleRate, samples }, [samples.buffer]);
      });
      this.assertNotDisposed(); // dispose() closed `capture` already; just fail the promise
      await capture.suspend();
      this.assertNotDisposed();
    } catch (e) {
      this.dispose();
      throw e;
    }
  }

  resume(): void {
    if (!this.worker || !this.capture) return;
    this.listening = true;
    this.setCaptureRunning(this.capture, true);
  }

  pause(): void {
    if (!this.worker || !this.capture) return;
    this.listening = false;
    this.worker.postMessage({ type: 'reset' });
    this.setCaptureRunning(this.capture, false);
  }

  dispose(): void {
    this.disposed = true;
    this.listening = false;
    this.pendingCapture = null; // whatever was queued is moot: this capture is being closed
    const cancelLoad = this.cancelLoad;
    this.cancelLoad = null;
    const { worker, capture } = this;
    this.worker = null;
    this.capture = null;
    if (worker) { worker.onmessage = null; worker.onerror = null; worker.terminate(); }
    if (capture) void this.quietly(capture.close());
    cancelLoad?.(new Error(DISPOSED_MESSAGE)); // wakes up a load() that is still waiting on the worker
  }

  /**
   * Starts or stops the flow of microphone blocks, one operation at a time.
   *
   * AudioContext.suspend()/resume() settle asynchronously, so a resume() issued while a suspend() is
   * still in flight used to see a context that still read 'running', skip its own work, and then have
   * the pending suspend land on top of it: the spotter went deaf on a suspended context while the SDK
   * believed it was listening, until the next full session. (A 429 BUSY or a LAN token error fails an
   * activation in milliseconds, which is all it takes.) Each request therefore waits for the previous
   * one to settle, and only the most recent one survives that wait.
   */
  private setCaptureRunning(capture: AudioCapture, running: boolean): void {
    const op = (): Promise<void> => this.quietly(running ? capture.resume() : capture.suspend());
    if (this.captureOp) {
      this.pendingCapture = op;
      return;
    }
    this.runCaptureOp(op);
  }

  private runCaptureOp(op: () => Promise<void>): void {
    this.captureOp = op().then(() => {
      this.captureOp = null;
      const next = this.pendingCapture;
      this.pendingCapture = null;
      if (next) this.runCaptureOp(next);
    });
  }

  /** Browsers can reject resume()/suspend()/close() under state races; none of that is news here. */
  private quietly(p: Promise<void>): Promise<void> {
    return p.catch(() => undefined);
  }

  /** Every await in load() is followed by this: a concurrent dispose() must fail the promise it interrupted. */
  private assertNotDisposed(): void {
    if (this.disposed) throw new Error(DISPOSED_MESSAGE);
  }

  private handshake(worker: KwsWorkerLike, keywords: string): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const settle = (done: () => void): void => {
        clearTimeout(timer);
        this.cancelLoad = null;
        done();
      };
      const timer = setTimeout(() => settle(() => reject(new Error(`KWS worker timed out after ${this.deps.loadTimeoutMs} ms`))), this.deps.loadTimeoutMs);
      this.cancelLoad = (reason) => settle(() => reject(reason));
      worker.onerror = (ev) => settle(() => reject(new Error(`KWS worker failed to load: ${ev.message ?? 'unknown error'}`)));
      worker.onmessage = (ev) => {
        if (!isWorkerMessage(ev.data)) return;
        const message = ev.data;
        if (message.type === 'ready') {
          worker.postMessage({
            type: 'init', keywords,
            threshold: this.options.threshold ?? DEFAULTS.threshold,
            score: this.options.score ?? DEFAULTS.score,
          });
        } else if (message.type === 'inited') {
          worker.onmessage = (later) => this.onWorkerMessage(later.data);
          worker.onerror = (later) => this.markBroken(`KWS worker failed: ${later.message ?? 'unknown error'}`);
          settle(resolve);
        } else if (message.type === 'fatal') {
          settle(() => reject(new Error(`KWS worker: ${message.message}`)));
        }
      };
    });
  }

  /**
   * The spotter is dead, and it happened after load() had already resolved — so there is no promise
   * left to reject. It never wakes the assistant again; whoever is listening gets told once.
   */
  private markBroken(message: string): void {
    if (this.broken) return;
    this.broken = true;
    for (const handler of [...this.errorHandlers]) handler(message);
  }

  private onWorkerMessage(data: unknown): void {
    if (!isWorkerMessage(data)) return;
    if (data.type === 'fatal') { this.markBroken(`KWS worker: ${data.message}`); return; }
    if (data.type !== 'keyword' || !this.listening || this.broken) return;
    const now = this.deps.now();
    if (now - this.lastHitAt < (this.options.cooldownMs ?? DEFAULTS.cooldownMs)) return;
    this.lastHitAt = now;
    for (const handler of [...this.handlers]) handler(data.keyword);
  }
}

/**
 * fork 新增：模型文件安全下载（SHA256 校验 + 上游白名单 + 断点续传）。
 *
 * 与上游实现的差异（安全加固）：
 *  - 每个模型文件下载完成后校验 SHA256（官方 LFS 指针哈希，写死于清单）；
 *  - 已存在的本地文件在首次加载时同样校验，不匹配即删除重下；
 *  - 下载目标 host 白名单（huggingface.co / hf-mirror.com），重定向跳转到
 *    白名单之外的域名一律拒绝；自定义镜像需显式 allowCustomModelHost；
 *  - 校验失败（篡改/损坏）跨全部上游重试后仍然失败时，fail-loud 上报。
 */
import { createHash } from 'node:crypto'
import { createWriteStream } from 'node:fs'
import { mkdir, rename, stat, unlink } from 'node:fs/promises'
import { join } from 'node:path'

/** 官方模型源（默认）。 */
export const HOST_PRIMARY = 'https://huggingface.co'
/** 国内镜像源（回退）。 */
export const HOST_FALLBACK = 'https://hf-mirror.com'

/** 默认允许的模型下载域名（严格白名单）。 */
export const ALLOWED_MODEL_HOSTNAMES = ['huggingface.co', 'hf.co', 'hf-mirror.com'] as const

export interface ModelFileSpec {
  /** 仓库内相对文件名（可含子目录）。 */
  file: string
  /** 官方内容 SHA256（LFS oid / 文本内容哈希）。 */
  sha256: string
}

export interface EnsureModelOptions {
  /** 模型仓库（org/repo）。 */
  repo: string
  /** 仓库本地目录（cacheDir/repo）。 */
  repoDir: string
  spec: ModelFileSpec
  /** 设置/配置指定的模型源（'' = 默认源）。 */
  primaryHost: string
  /** 是否允许白名单之外的模型源（默认关）。 */
  allowCustomHost: boolean
  broadcast: (event: string, payload: unknown) => void
}

/**
 * 校验并规范化模型源：仅 https + 白名单域名（或显式允许自定义）。
 * 返回规范化的 origin（无尾斜杠）；非法返回 null（调用方回退默认源）。
 */
export function validateModelHost(raw: string, allowCustomHost: boolean): string | null {
  if (!raw) return null
  let u: URL
  try {
    u = new URL(raw)
  } catch {
    return null
  }
  if (u.protocol !== 'https:') return null
  const hostname = u.hostname.toLowerCase()
  if (!(ALLOWED_MODEL_HOSTNAMES as readonly string[]).includes(hostname) && !allowCustomHost) {
    return null
  }
  return `${u.protocol}//${u.hostname}${u.port ? `:${u.port}` : ''}`
}

/** 响应最终 URL 的域名是否在允许范围内（防重定向逃逸白名单）。
 *  允许官方源与其子域（LFS 会重定向到 us.aws.cdn.hf.co / cdn-lfs.huggingface.co 等）。 */
export function redirectHostAllowed(finalUrl: string, allowCustomHost: boolean): boolean {
  try {
    const u = new URL(finalUrl)
    if (u.protocol !== 'https:') return false
    const hostname = u.hostname.toLowerCase()
    if (allowCustomHost) return true
    return (
      hostname === 'huggingface.co' ||
      hostname.endsWith('.huggingface.co') ||
      hostname === 'hf.co' ||
      hostname.endsWith('.hf.co') ||
      hostname === 'hf-mirror.com' ||
      hostname.endsWith('.hf-mirror.com')
    )
  } catch {
    return false
  }
}

/** 流式计算文件 SHA256。 */
export async function sha256OfFile(path: string): Promise<string> {
  const hash = createHash('sha256')
  const { createReadStream } = await import('node:fs')
  await new Promise<void>((resolve, reject) => {
    const stream = createReadStream(path)
    stream.on('data', (c) => { hash.update(c) })
    stream.on('error', reject)
    stream.on('end', () => resolve())
  })
  return hash.digest('hex')
}

/** 下载单个模型文件（带校验与上游回退）。 */
export async function ensureModelFile(opts: EnsureModelOptions): Promise<boolean> {
  const { repo, repoDir, spec, primaryHost, allowCustomHost, broadcast } = opts
  const localPath = join(repoDir, spec.file)
  const partPath = `${localPath}.part`

  // 1) 已有文件：校验哈希；不匹配 → 删除重下（篡改/损坏自愈）。
  if ((await stat(localPath).catch(() => null))?.isFile()) {
    const ok = (await sha256OfFile(localPath).catch(() => '')) === spec.sha256
    if (ok) return true
    await unlink(localPath).catch(() => undefined)
  }

  await mkdir(join(repoDir, spec.file.includes('/') ? spec.file.slice(0, spec.file.lastIndexOf('/')) : ''), {
    recursive: true,
  }).catch(() => undefined)

  const hosts = [...new Set([primaryHost, HOST_PRIMARY, HOST_FALLBACK].filter(Boolean))]
  let lastError = 'no upstream reachable'
  for (const host of hosts) {
    try {
      const done = await downloadVerified({ ...opts, host, partPath, localPath })
      if (done) return true
    } catch (e) {
      lastError = String(e)
    }
  }
  // 不删 .part：保留断点续传进度。慢网络（如 310MB Kokoro 主模型 @ ~250KB/s）
  // 单次请求无法下载完，删掉会让每次预览都从头开始、永远不完成。
  // 仅在校验失败（downloadVerified 内部 SHA 不匹配）时才清 .part——那里已处理。
  broadcast('asr-error', { file: spec.file, reason: 'checksum_or_download_failed', detail: lastError })
  return false
}

async function downloadVerified(opts: {
  repo: string
  repoDir: string
  spec: ModelFileSpec
  host: string
  allowCustomHost: boolean
  partPath: string
  localPath: string
  broadcast: (event: string, payload: unknown) => void
}): Promise<boolean> {
  const { repo, spec, host, allowCustomHost, partPath, localPath, broadcast } = opts
  const url = `${host}/${repo}/resolve/main/${spec.file}`
  const partSt = await stat(partPath).catch(() => null)
  const resumeFrom = partSt?.isFile() ? partSt.size : 0
  const headers: Record<string, string> = { 'user-agent': 'dsh-voice-hub' }
  if (resumeFrom > 0) headers.range = `bytes=${resumeFrom}-`

  const res = await fetch(url, { headers, redirect: 'follow' })
  // 重定向后的最终域名必须仍在白名单内（防恶意模型源把请求导去任意地址）。
  if (!redirectHostAllowed(res.url, allowCustomHost)) return false
  if (res.status === 416) {
    // Range 不可满足 = 已完整：直接校验后改名。
    if ((await sha256OfFile(partPath).catch(() => '')) === spec.sha256) {
      await rename(partPath, localPath)
      return true
    }
    await unlink(partPath).catch(() => undefined)
    return false
  }
  if (res.status !== 200 && res.status !== 206) return false
  // 续传只在服务端返回 206 时成立；若带已有 .part 却返回 200 全量（部分镜像/CDN
  // 忽略 Range），必须从头重写，否则在旧字节上追加全量 → 半旧半新损坏（SHA256 会拦下，但浪费一次全量下载）。
  const resume = res.status === 206 ? resumeFrom : 0
  const total = Number(res.headers.get('content-length') ?? 0) + resume
  const src = res.body
  if (!src) return false
  const sink = createWriteStream(partPath, resume > 0 ? { flags: 'a' } : {})
  const reader = src.getReader()
  let received = resume
  await new Promise<void>((resolve, reject) => {
    sink.on('error', (e) => reject(e))
    sink.on('finish', () => resolve())
    void (async () => {
      try {
        for (;;) {
          const { done, value } = await reader.read()
          if (done) break
          received += value.byteLength
          if (!sink.write(value)) {
            await new Promise<void>((r) => sink.once('drain', r))
          }
          if (total > 0) {
            broadcast('asr-progress', {
              file: spec.file,
              percent: Math.min(100, Math.round((received / total) * 100)),
            })
          }
        }
        sink.end()
      } catch (e) {
        sink.destroy(e as Error)
        reject(e)
      }
    })()
  })
  // 完整性校验：不匹配即弃（换下一个上游）。
  const actual = await sha256OfFile(partPath).catch(() => '')
  if (actual !== spec.sha256) {
    await unlink(partPath).catch(() => undefined)
    return false
  }
  await rename(partPath, localPath)
  return true
}

/**
 * 确保某仓库子目录内的全部文件存在（如 Kokoro 的 espeak-ng-data：按目录分发的 ~355 个
 * 语音表文件，无独立 SHA 清单）。与 ensureModelFile 不同：树文件靠「下载成功 + size>0」
 * 判定，不逐一校验 SHA（均为官方仓库的非权重资产；权重类仍走 ensureModelFile 强校验）。
 * 任一文件在所有上游失败时返回 false（上层可退避重试）。
 */
export async function ensureModelTree(opts: {
  repo: string
  repoDir: string
  subdir: string
  primaryHost: string
  allowCustomHost: boolean
  broadcast: (event: string, payload: unknown) => void
}): Promise<boolean> {
  const { repo, repoDir, subdir, primaryHost, allowCustomHost, broadcast } = opts
  const hosts = [...new Set([primaryHost, HOST_PRIMARY, HOST_FALLBACK].filter(Boolean))]
  // 取其父目录（子目录文件写入正确层）。
  const subRoot = join(repoDir, subdir)
  await mkdir(subRoot, { recursive: true }).catch(() => undefined)

  let tree: string[] = []
  for (const host of hosts) {
    try {
      const res = await fetch(host + '/api/models/' + repo + '?blobs=true', { headers: { 'user-agent': 'dsh-voice-hub' } })
      if (res.ok) {
        const j = (await res.json()) as { siblings?: Array<{ rfilename?: string }> }
        tree = (j.siblings ?? []).map((s) => s.rfilename ?? '').filter((f) => f.startsWith(subdir + '/') && f.length > 0)
        if (tree.length > 0) break
      }
    } catch {
      // 尝试下一个 host
    }
  }
  if (tree.length === 0) return false

  let allOk = true
  let done = 0
  const queue = [...tree]
  const worker = async (): Promise<void> => {
    for (;;) {
      const rel = queue.shift()
      if (rel === undefined) return
      const localPath = join(repoDir, rel)
      const partPath = localPath + '.part'
      if ((await stat(localPath).catch(() => null))?.isFile() && (await stat(localPath)).size > 0) {
        done++
        continue
      }
      await mkdir(join(repoDir, rel.slice(0, rel.lastIndexOf('/'))), { recursive: true }).catch(() => undefined)
      let ok = false
      for (const host of hosts) {
        try {
          const url = host + '/' + repo + '/resolve/main/' + encodeURIComponent(rel)
          const res = await fetch(url, { headers: { 'user-agent': 'dsh-voice-hub' }, redirect: 'follow' })
          if (!redirectHostAllowed(res.url, allowCustomHost)) continue
          if (res.status !== 200) continue
          const sink = createWriteStream(partPath)
          const reader = res.body?.getReader()
          if (!reader) continue
          let size = 0
          await new Promise<void>((resolve, reject) => {
            sink.on('error', reject)
            sink.on('finish', resolve)
            void (async () => {
              try {
                for (;;) {
                  const r = await reader.read()
                  if (r.done) break
                  size += r.value.byteLength
                  if (!sink.write(r.value)) await new Promise<void>((r2) => sink.once('drain', r2))
                }
                sink.end()
              } catch (e) {
                sink.destroy(e as Error)
                reject(e as Error)
              }
            })()
          })
          if (size > 0) {
            await rename(partPath, localPath)
            ok = true
            break
          }
        } catch {
          // 下一个 host
        }
      }
      if (ok) {
        done++
        broadcast('asr-progress', { file: rel, percent: Math.round((done / tree.length) * 100) })
      } else {
        allOk = false
      }
    }
  }
  // 限并发：表文件小而多，8 路足够。
  await Promise.all(Array.from({ length: 8 }, () => worker()))
  return allOk
}

import { createRequire } from 'node:module'
import type { ProsodyOptions } from 'msedge-tts'

// 宿主 ESM 构建产物旁的 CJS 包；避免 DSH profile 解析 msedge-tts 的 buffer/index 子路径。
const { MsEdgeTTS, OUTPUT_FORMAT } = createRequire(import.meta.url)('./msedge-tts.cjs') as typeof import('msedge-tts')

export { MsEdgeTTS, OUTPUT_FORMAT }
export type { ProsodyOptions }

/**
 * 线性插值重采样（客户端共用）：把任意采样率 Float32 音频重采样到目标采样率。
 * 用途：采集侧 Safari 忽略 AudioContext({sampleRate}) 选项（44.1k/48k 输出）
 * 需归一化到 16k；P3 回声参考（decodeAudioData 解出的 24kHz TTS PCM）亦需
 * 对齐到 16k 采集率。两倍率差值在可接受范围，线性插值足够。
 */

/** 线性插值重采样到目标采样率。 */
export function resampleLinear(src: Float32Array, srcRate: number, dstRate: number): Float32Array {
  if (srcRate === dstRate) return src
  if (src.length === 0) return src
  const ratio = srcRate / dstRate
  const outLen = Math.max(1, Math.floor(src.length / ratio))
  const out = new Float32Array(outLen)
  for (let i = 0; i < outLen; i++) {
    const pos = i * ratio
    const i0 = Math.floor(pos)
    const i1 = Math.min(i0 + 1, src.length - 1)
    const frac = pos - i0
    out[i] = src[i0] + (src[i1] - src[i0]) * frac
  }
  return out
}

/**
 * fork 新增：HTTP 面安全防护（回环校验 / 同源校验 / 限流）。
 *
 * 威胁模型与分层（详见 FORK.md）：
 *  - 第 2 层 网络边界：默认仅接受回环来源（allowLan=false）；局域网/公网
 *    暴露必须显式开启 allowLan 并自担风险（建议前置 dsh-web-auth 之类认证门）。
 *  - 第 1 层 浏览器 CSRF：状态变更端点（toggle/cancel/preview）校验 Origin
 *    与请求目标同源；跨站浏览器请求会被预检/Origin 拒绝。
 *  - 第 4 层 滥用抑制：按会话/IP 的滑动窗口限流，防打爆 ASR/TTS 队列。
 */
import type { IncomingMessage } from 'node:http'

const LOOPBACK_ADDRESSES = new Set(['127.0.0.1', '::1', '::ffff:127.0.0.1'])

/** 请求是否来自回环地址。 */
export function isLoopbackRequest(req: IncomingMessage): boolean {
  const addr = req.socket.remoteAddress ?? ''
  return LOOPBACK_ADDRESSES.has(addr)
}

/**
 * Origin 同源校验：POST 状态下浏览器必带 Origin；带则 host（含端口）必须等于
 * 请求自身。无 Origin（非浏览器客户端）放行——由回环层兜底。
 *
 * 反代兼容：经 HTTPS 反代访问时，dsh 只见回环 HTTP（TLS 在反代终止），
 * 此时 socket.encrypted=false 但浏览器 Origin 是 https，scheme 对不上会误拒。
 * 因此只比较 host（忽略 scheme），并优先取 X-Forwarded-Host（反代改写 Host 的场景）。
 */
export function sameOriginRequest(req: IncomingMessage): boolean {
  const origin = req.headers.origin
  if (!origin) return true
  try {
    const originHost = new URL(origin).host
    const xfh = req.headers['x-forwarded-host']
    const host = (typeof xfh === 'string' && xfh ? xfh.split(',')[0].trim() : '') || req.headers.host
    if (!host) return false
    return originHost === host
  } catch {
    return false
  }
}

/**
 * 有界滑动窗口限流器：key -> 时间戳队列。
 * maxKeys 兜底防内存无限增长（键满时拒绝新键）。
 */
export class RateLimiter {
  private readonly buckets = new Map<string, number[]>()
  private readonly maxKeys: number

  constructor(maxKeys = 10000) {
    this.maxKeys = maxKeys
  }

  /** 命中一次；返回是否允许。maxHits 次 / windowMs 毫秒。 */
  hit(key: string, maxHits: number, windowMs: number): boolean {
    const now = Date.now()
    const cutoff = now - windowMs
    let bucket = this.buckets.get(key)
    if (!bucket) {
      if (this.buckets.size >= this.maxKeys) return false
      bucket = []
      this.buckets.set(key, bucket)
    }
    while (bucket.length > 0 && bucket[0] <= cutoff) bucket.shift()
    if (bucket.length >= maxHits) return false
    bucket.push(now)
    return true
  }

  /** 定期清理（由调用方在低频路径触发即可）。 */
  prune(now = Date.now(), windowMs: number): void {
    const cutoff = now - windowMs
    for (const [key, bucket] of this.buckets) {
      while (bucket.length > 0 && bucket[0] <= cutoff) bucket.shift()
      if (bucket.length === 0) this.buckets.delete(key)
    }
  }
}

/**
 * 句子切分器：累积 raw text-delta，按终止标点输出完整句子（供 TTS 朗读）。
 * 与参照 dsh-voice 同源：markdown 剥离 + 中英日终止标点切分 + 强制上限。
 */

export interface SegmenterOptions {
  /** 无标点文本的强制切分上限（防 markdown 墙）。 */
  maxSentenceChars?: number
}

const TERMINAL = /[。！？!?；;…\n]/

const SKIP_PREFIX = /^[\s.,，、:：;；!?！？)\]）"'”’〉》】]+$/

/** 剥离 markdown 噪声后再合成（与 dsh-tts 的 plainText 滤镜同源）。 */
export function plainText(text: string): string {
  return String(text)
    .replace(/```[\s\S]*?```/g, ' ')
    .replace(/`([^`]*)`/g, '$1')
    .replace(/!\[[^\]]*\]\([^)]*\)/g, ' ')
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/\*([^*]+)\*/g, '$1')
    .replace(/^[-*+]\s+/gm, '')
    .replace(/^\d+\.\s+/gm, '')
    // 批 4 收口 B1 修复：原正则 /<\/?[a-zA-Z][^>]*>/g 把 emotion 标签一并剥掉，导致 emotion.ts 永远收不到标签。
    // 改为白名单：只剥真正块级 HTML 标签；emotion 标签（break/whisper|/whisper/laugh/sigh/emphasis）保留。
    // 零信任：未列入 HTML 集合的标签一律不剥（保留原样交给 emotion.ts 解析；非法标签会被 emotion.ts 正则忽略）。
    .replace(/<\/?(?:b|i|u|br|p|span|div|strong|em|s|sub|sup|h[1-6]|ul|ol|li|a|img|code|pre|blockquote|hr|table|tr|td|th)\b[^>]*>/gi, ' ')
}

/**
 * 单字符级 TTS 消毒：剔除会被 espeak 按英文念出的噪声字符
 * （asterisk/underscore/greater than/vertical bar…）。
 * plainText 是配对式剥离，流式增量下配对符可能被 chunk 截断（如 `**` 劈成
 * 两半），残留字符会被逐字念出——故对成句文本再做一遍单字符兜底。
 *
 * 批 4 收口 B1 修复：从字符集合中移除 `<` 和 `>`——plainText 已确保不再有合法 HTML 残留，
 * 剩下的 `<...>` 一定是 emotion 标签（break/whisper/laugh/sigh/emphasis），闭合 `>` 是
 * 标签的一部分，必须保留，否则 sanitize 会把 `<laugh>` 变成 `<laugh `（闭合 `>` 被吃）。
 * 未列入 emotion 集合的非法 `<xxx>` 一律保留原样（零信任），由 emotion.ts 正则忽略。
 */
export function sanitizeForTts(text: string): string {
  return String(text)
    .replace(/[*_#|^=+~`]/g, ' ')
    .replace(/\s{2,}/g, ' ')
    // 汉字之间的空格对中文合成无意义（噪声字符剔除的副产品），塌掉避免怪停顿。
    .replace(/([\u3400-\u9fff])\s+(?=[\u3400-\u9fff])/g, '$1')
    .trim()
}

/** 按终止标点切分一段文本，保留句尾在句子内、尾部悬挂在 tail。 */
export function splitSentences(chunk: string): { sentences: string[]; tail: string } {
  const sentences: string[] = []
  let start = 0
  // CJK 终止符 + ASCII 终止符；孤立的英文句点仅在空白/文末后算终止
  // （避免拆散 "3.14"、URL）。
  const re = /[。！？!?；;…\n]+|\.(?=\s|$)/g
  let m: RegExpExecArray | null
  let lastEnd = 0
  while ((m = re.exec(chunk)) !== null) {
    const end = m.index + m[0].length
    sentences.push(chunk.slice(start, end))
    start = end
    lastEnd = end
  }
  return { sentences, tail: chunk.slice(lastEnd) }
}

export class SentenceSegmenter {
  private buffer = ''
  private readonly maxChars: number

  constructor(options: SegmenterOptions = {}) {
    this.maxChars = options.maxSentenceChars ?? 200
  }

  /** 喂入一段 raw delta，返回它补全的完整句子。 */
  feed(chunk: string): string[] {
    const cleaned = plainText(chunk)
    if (!cleaned) return []
    this.buffer += cleaned
    const { sentences, tail } = splitSentences(this.buffer)
    this.buffer = tail
    const out: string[] = []
    for (const s of sentences) {
      const t = sanitizeForTts(s).trim()
      if (t && !SKIP_PREFIX.test(t)) out.push(t)
    }
    // 安全阀：一堵没有标点的文字墙。
    if (this.buffer.length > this.maxChars) {
      const cut = this.buffer.search(/[，,、\s]/)
      const idx = cut > 0 ? cut : Math.floor(this.maxChars / 2)
      const head = sanitizeForTts(this.buffer.slice(0, idx)).trim()
      this.buffer = this.buffer.slice(idx)
      if (head) out.push(head)
    }
    return out
  }

  /** 收尾：flush 剩余缓冲（流结束）。 */
  flush(): string[] {
    const t = sanitizeForTts(this.buffer).trim()
    this.buffer = ''
    if (t && !SKIP_PREFIX.test(t)) return [t]
    return []
  }
}

/** 默认语音发送命令；设置页可替换或清空。 */
export const DEFAULT_SEND_COMMANDS = ['发送', '确认发送', '确认'] as const

/** ASR 定稿可能带句末标点；只匹配完整短句，避免把「发送给我……」误判为发送。 */
export function normalizeSendCommand(text: string): string {
  return text.trim().replace(/[\s\u3000，。！？!?；;、,.]+/g, '')
}

export function matchesSendCommand(text: string, commands: readonly string[]): boolean {
  const phrase = normalizeSendCommand(text)
  return phrase !== '' && commands.some((command) => normalizeSendCommand(command) === phrase)
}

/**
 * SenseVoice 离线定稿解码的 worker 线程（P4-1 离主线程优化）。
 *
 * 问题背景：SenseVoice 的 rec.decode(stream) 是 sherpa-onnx WASM 同步 CPU 密集调用，
 * 在宿主主线程执行时会把事件循环占住整段解码时长（SSE 心跳/其它请求全部冻结），
 * 且主线程 Promise.race 的超时 timer 因事件循环被占而形同虚设。
 *
 * 本文件把「createOfflineRecognizer（约 1.5s 载入 228MB）+ 整段 decode」整体搬进
 * worker_threads：worker 常驻、持有 recognizer 缓存（create 后复用），decode 在
 * worker 内同步执行——不阻塞主线程事件循环。主线程侧经消息 RPC 异步等待回执，
 * 20s 兜底（在 asr-host.ts:595 真源）此时才真正可触发。
 *
 * 消息协议（JSON，request id 配对）：
 *   主 → worker: { id, op: 'create' } | { id, op: 'decode', samples: Float32Array }
 *   worker → 主: { id, ok: true, text } | { id, ok: false, error }
 *
 * 约束（与规划文档 §4 非目标一致）：
 *   - 不迁移 zipformer 流式识别（增量短阻塞，留在主线程）；
 *   - 单 worker 单 recognizer（228MB 模型实例只养一份，内存可控）；
 *   - 下载/退避/门控仍在主线程（ensureSenseModel 不动，worker 无网络职责）。
 */
import { parentPort, workerData } from 'node:worker_threads'

// sherpa-onnx 无 TS 声明：仅声明用到的极小面。
interface SherpaStream {
  acceptWaveform(sampleRate: number, samples: Float32Array): void
  free(): void
}
interface SherpaOfflineRecognizer {
  createStream(): SherpaStream
  decode(stream: SherpaStream): void
  getResult(stream: SherpaStream): { text: string }
  free(): void
}
interface SherpaModule {
  createOfflineRecognizer(config: Record<string, unknown>): SherpaOfflineRecognizer
}

/** worker 启动参数（主线程 new Worker 时经 workerData 传入）。 */
export interface SenseWorkerData {
  /** sherpa-onnx 包路径或包名（worker 内 import()）。 */
  sherpaModule: string
  /** SenseVoice 模型目录（model.int8.onnx 与 tokens.txt 所在）。 */
  modelDir: string
  /** 批 2：识别语言（host 已固定 'auto'，见 asr-host.ts:393-415；默认 'auto'）。 */
  language: string
  /** 批 2：是否启用逆文本归一化（ITN；默认 1 = 启用）。 */
  useITN: number
}

type WorkerLike = {
  postMessage(msg: unknown): void
  on?(ev: 'message' | 'error' | 'exit', fn: (...args: any[]) => void): unknown
  terminate?(): Promise<number>
}

/** 客户端 RPC（主线程侧）：把 worker 封装成 request/回执配对。 */
export interface SenseWorkerClient {
  /** 请求一次 decode（整段 PCM）；失败返回 null。 */
  request(op: 'decode', samples: Float32Array): Promise<string | null>
  request(op: 'create'): Promise<boolean>
  /** 监听 worker 崩溃/退出（供持有方清引用以便重建）。 */
  onDeath(fn: () => void): void
  terminate(): Promise<void>
}

/**
 * 纯协议客户端（不依赖真实 worker 线程/网络）：注入任何符合 WorkerLike 的对象即可，
 * 便于单测覆盖「配对/超时/崩溃」逻辑而不触碰 WASM。
 */
export function createSenseWorkerClient(worker: WorkerLike): SenseWorkerClient {
  let counter = 0
  const pending = new Map<
    number,
    { op: 'decode' | 'create'; resolve: (v: string | null | boolean) => void; reject: (e: Error) => void }
  >()
  let dead = false
  const deathFns = new Set<() => void>()
  const die = (): void => {
    if (dead) return
    dead = true
    for (const fn of deathFns) {
      try {
        fn()
      } catch {
        // ignore
      }
    }
  }

  worker.on?.('message', (msg: { id: number; ok?: boolean; text?: string; error?: string }) => {
    const p = pending.get(msg?.id)
    if (!p) return
    pending.delete(msg.id)
    if (!msg.ok) {
      p.resolve(null)
      return
    }
    // create 回执 = 布尔（recognizer 就绪）；decode 回执 = 文本。
    p.resolve(p.op === 'create' ? true : (msg.text ?? ''))
  })
  worker.on?.('error', (e: Error) => {
    die()
    const err = new Error('sense worker error: ' + String(e?.message ?? e))
    for (const [, p] of pending) p.reject(err)
    pending.clear()
  })
  worker.on?.('exit', () => {
    die()
    const err = new Error('sense worker exited')
    for (const [, p] of pending) p.reject(err)
    pending.clear()
  })

  const request = (op: 'decode' | 'create', samples?: Float32Array): Promise<string | null | boolean> => {
    if (dead) return Promise.reject(new Error('sense worker dead'))
    const id = counter++
    return new Promise((resolve, reject) => {
      pending.set(id, { op, resolve: resolve as (v: string | null | boolean) => void, reject })
      const msg: { id: number; op: string; samples?: Float32Array } = { id, op }
      if (samples) msg.samples = samples
      try {
        worker.postMessage(msg)
      } catch (e) {
        pending.delete(id)
        reject(e instanceof Error ? e : new Error(String(e)))
      }
    })
  }

  return {
    request: request as SenseWorkerClient['request'],
    onDeath(fn: () => void) {
      deathFns.add(fn)
    },
    terminate: async () => {
      dead = true
      const err = new Error('sense worker terminated')
      for (const [, p] of pending) p.reject(err)
      pending.clear()
      try {
        await worker.terminate?.()
      } catch {
        // ignore
      }
    },
  }
}

/** worker 线程入口：忙等消息并在线程内同步解码（不阻塞主线程）。 */
export function startSenseWorker(data: SenseWorkerData): void {
  const port = parentPort
  if (!port) return // 非 worker 上下文：静默
  let recognizer: SherpaOfflineRecognizer | null = null
  let sherpa: SherpaModule | null = null

  port.on('message', async (msg: { id: number; op: string; samples?: Float32Array }) => {
    try {
      if (msg.op === 'create' || msg.op === 'decode') {
        if (!sherpa) {
          sherpa = (await import(data.sherpaModule)) as unknown as SherpaModule
        }
        if (!recognizer) {
          recognizer = sherpa.createOfflineRecognizer({
            featConfig: { sampleRate: 16000, featureDim: 80 },
            modelConfig: {
              senseVoice: {
                model: data.modelDir + '/model.int8.onnx',
                language: data.language,
                useInverseTextNormalization: data.useITN,
              },
              tokens: data.modelDir + '/tokens.txt',
              provider: 'cpu',
              debug: 0,
            },
          })
        }
        if (msg.op === 'decode' && msg.samples) {
          const stream = recognizer.createStream()
          try {
            stream.acceptWaveform(16000, msg.samples)
            recognizer.decode(stream)
            const text = recognizer.getResult(stream).text.trim()
            port.postMessage({ id: msg.id, ok: true, text })
          } finally {
            try {
              stream.free()
            } catch {
              // ignore
            }
          }
          return
        }
        port.postMessage({ id: msg.id, ok: true, text: '' })
        return
      }
      port.postMessage({ id: msg.id, ok: false, error: 'unknown op: ' + msg.op })
    } catch (e) {
      port.postMessage({ id: msg.id, ok: false, error: String(e) })
    }
  })
}

// worker_threads 直接执行本文件时启动（主线程 import 本模块不触发）。
if (parentPort) {
  startSenseWorker(workerData as SenseWorkerData)
}

import { randomUUID } from 'node:crypto'
import WebSocket from 'ws'
import type { ServiceConfig } from './service-config.ts'

export interface ConnectionResult {
  ok: boolean
  ms: number
  message: string
}

async function measure(check: () => Promise<string>): Promise<ConnectionResult> {
  const start = Date.now()
  try {
    const message = await check()
    return { ok: true, ms: Date.now() - start, message }
  }
  catch (error) {
    const message = error instanceof Error && ['AbortError', 'TimeoutError', 'TypeError'].includes(error.name)
      ? '连接失败或超时，请检查地址和服务状态'
      : error instanceof Error ? error.message : '连接失败，请检查服务地址和运行状态'
    return { ok: false, ms: Date.now() - start,
      message }
  }
}

async function checkStream(url: string): Promise<string> {
  const socket = new WebSocket(url, { handshakeTimeout: 8000 })
  try {
    return await new Promise<string>((resolve, reject) => {
      const timer = setTimeout(() => reject(new Error('连接超时，请检查流式识别服务')), 8000)
      let settled = false
      const finish = (error?: Error): void => {
        if (settled) return
        settled = true
        clearTimeout(timer)
        if (error) reject(error)
        else resolve('WebSocket（实时连接）握手和 ASR 启动成功')
      }
      socket.once('open', () => socket.send(JSON.stringify({
        type: 'start', requestId: randomUUID(), sessionId: 'voice-service-check',
        turnId: randomUUID(), generationId: randomUUID().replaceAll('-', ''), traceId: randomUUID(),
        audio: { encoding: 'pcm_s16le', sampleRate: 16000, channels: 1 },
      })))
      socket.on('message', (data) => {
        let event: { type?: string; error?: { message?: string } }
        try { event = JSON.parse(String(data)) as typeof event } catch { return }
        if (event.type === 'started') finish()
        if (event.type === 'error') finish(new Error(`ASR（语音识别）启动失败：${event.error?.message ?? '服务返回错误'}`))
      })
      socket.once('error', () => finish(new Error('连接失败，请检查流式识别地址和服务状态')))
      socket.once('close', () => finish(new Error('服务在启动前关闭连接')))
    })
  } finally { socket.terminate() }
}

async function checkBatch(config: ServiceConfig): Promise<string> {
  const wav = Buffer.alloc(44 + 32000) // 1 秒、16 kHz、单声道、16 位静音
  wav.write('RIFF', 0)
  wav.writeUInt32LE(wav.length - 8, 4)
  wav.write('WAVEfmt ', 8)
  wav.writeUInt32LE(16, 16)
  wav.writeUInt16LE(1, 20)
  wav.writeUInt16LE(1, 22)
  wav.writeUInt32LE(16000, 24)
  wav.writeUInt32LE(32000, 28)
  wav.writeUInt16LE(2, 32)
  wav.writeUInt16LE(16, 34)
  wav.write('data', 36)
  wav.writeUInt32LE(wav.length - 44, 40)
  const form = new FormData()
  form.append('file', new Blob([new Uint8Array(wav)], { type: 'audio/wav' }), 'check.wav')
  form.append('model', config.asrModel)
  const response = await fetch(config.asrBatchUrl, {
    method: 'POST', body: form, signal: AbortSignal.timeout(15000),
  })
  if (!response.ok) throw new Error(`服务返回 HTTP（请求状态）${response.status}`)
  const body = await response.json() as { text?: unknown }
  if (typeof body.text !== 'string') throw new Error('服务响应缺少转写文本字段')
  return '转写接口已处理测试音频（静音结果为空属正常）'
}

async function checkTts(config: ServiceConfig): Promise<string> {
  const response = await fetch(config.ttsStreamUrl, {
    method: 'POST', headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ text: '你好，这是语音连接测试。', generationId: randomUUID().replaceAll('-', '') }),
    signal: AbortSignal.timeout(15000),
  })
  if (!response.ok) throw new Error(`服务返回 HTTP（请求状态）${response.status}`)
  const audio = await response.arrayBuffer()
  if (audio.byteLength < 2 || audio.byteLength % 2) throw new Error('语音合成返回空音频或无效音频')
  return '语音合成接口已返回音频'
}

/** 使用设置页当前输入值检查流式识别、批量识别与语音合成；取消接口只校验地址格式。 */
export async function checkServiceConnections(config: ServiceConfig): Promise<Record<'stream' | 'batch' | 'tts', ConnectionResult>> {
  const [stream, batch, tts] = await Promise.all([
    measure(() => checkStream(config.asrStreamUrl)),
    measure(() => checkBatch(config)),
    measure(() => checkTts(config)),
  ])
  return { stream, batch, tts }
}

import { readFileSync } from 'node:fs'
import { mkdir, rename, writeFile } from 'node:fs/promises'
import { randomUUID } from 'node:crypto'
import { homedir } from 'node:os'
import { dirname, join } from 'node:path'
import { DEFAULT_SEND_COMMANDS, normalizeSendCommand } from './send-command.ts'
import { splitWakeWords } from './wakeword.ts'
import { SUMMARY_DEFAULTS, type SummarySettings } from './speech-summary.ts'

/** 模型地址的用户配置。文件是设置页面的唯一持久化来源，插件 Config 只给初始默认值。 */
export interface ServiceConfig extends SummarySettings {
  asrStreamUrl: string
  asrBatchUrl: string
  asrModel: string
  ttsStreamUrl: string
  ttsCancelUrl: string
  wakeWord: string
  alwaysListen: boolean
  sendCommands: string[]
  approvalVoice: boolean
}

export function serviceConfigPath(): string {
  return join(process.env.DSH_HOME || join(homedir(), '.dsh'), 'voice-mode', 'service-config.json')
}

function validUrl(value: unknown, protocols: readonly string[], label: string): string {
  if (typeof value !== 'string' || !value.trim() || value.length > 2048) throw new Error(`${label}不能为空或过长`)
  let url: URL
  try { url = new URL(value.trim()) } catch { throw new Error(`${label}不是有效地址`) }
  if (!protocols.includes(url.protocol) || !url.hostname || url.username || url.password || url.hash) {
    throw new Error(`${label}协议或格式不正确`)
  }
  return url.toString()
}

function validCancelUrl(value: unknown): string {
  if (value === '') return ''
  if (typeof value !== 'string' || value.split('{generationId}').length !== 2) {
    throw new Error('语音合成取消地址需包含一个 {generationId}，或留空禁用服务端取消')
  }
  const marker = 'dshgenerationidplaceholder'
  return validUrl(value.replace('{generationId}', marker), ['http:', 'https:'], '语音合成取消地址')
    .replace(marker, '{generationId}')
}

export function validateServiceConfig(value: unknown): ServiceConfig {
  if (!value || typeof value !== 'object') throw new Error('语音服务配置格式不正确')
  const source = value as Record<string, unknown>
  const asrModel = source.asrModel
  if (typeof asrModel !== 'string' || !asrModel.trim() || asrModel.length > 128) throw new Error('批量识别模型名不能为空或过长')
  if (source.wakeWord !== undefined && typeof source.wakeWord !== 'string') throw new Error('唤醒词格式不正确')
  const wakeWords = splitWakeWords(typeof source.wakeWord === 'string' ? source.wakeWord : '')
  if (wakeWords.length > 10 || wakeWords.some((word) => word.length > 32)) throw new Error('唤醒词最多 10 个，每个不超过 32 个字符，请用分号隔开')
  if (new Set(wakeWords.map((word) => word.replace(/\s+/g, ''))).size !== wakeWords.length) throw new Error('唤醒词不能重复')
  if (source.alwaysListen !== undefined && typeof source.alwaysListen !== 'boolean') throw new Error('常开唤醒开关格式不正确')
  if (source.alwaysListen === true && (!wakeWords.length || wakeWords.some((word) => /[^\u3400-\u9fff\s]/u.test(word)))) throw new Error('常开唤醒需要设置中文唤醒词')
  const rawCommands = source.sendCommands === undefined ? [...DEFAULT_SEND_COMMANDS] : source.sendCommands
  if (!Array.isArray(rawCommands) || rawCommands.length > 10 || rawCommands.some((item) => typeof item !== 'string' || item.length > 32 || !normalizeSendCommand(item))) {
    throw new Error('发送触发词最多 10 个，每个不超过 32 个字符，请用分号隔开')
  }
  const sendCommands: string[] = []
  const seenCommands = new Set<string>()
  for (const item of rawCommands) {
    const normalized = normalizeSendCommand(item)
    if (!seenCommands.has(normalized)) { seenCommands.add(normalized); sendCommands.push(item.trim()) }
  }
  if (typeof source.approvalVoice !== 'boolean') throw new Error('审批语音提示开关格式不正确')
  const summaryLength = source.summaryLength ?? SUMMARY_DEFAULTS.summaryLength
  const summaryPrompt = source.summaryPrompt ?? SUMMARY_DEFAULTS.summaryPrompt
  const summaryModel = source.summaryModel ?? null
  if (typeof summaryLength !== 'number' || !Number.isInteger(summaryLength) || summaryLength < 10 || summaryLength > 300) throw new Error('摘要字数需为 10 至 300 的整数')
  if (typeof summaryPrompt !== 'string' || !summaryPrompt.trim() || summaryPrompt.length > 8000) throw new Error('摘要提示词不能为空且不能超过 8000 字符')
  if (summaryModel !== null && (typeof summaryModel !== 'object' || Array.isArray(summaryModel)
    || !['provider', 'model'].every((key) => typeof (summaryModel as Record<string, unknown>)[key] === 'string'
      && (summaryModel as Record<string, string>)[key].trim().length > 0
      && (summaryModel as Record<string, string>)[key].length <= 256))) throw new Error('摘要模型配置无效')
  return {
    asrStreamUrl: validUrl(source.asrStreamUrl, ['ws:', 'wss:'], '流式识别地址'),
    asrBatchUrl: validUrl(source.asrBatchUrl, ['http:', 'https:'], '批量识别地址'),
    asrModel: asrModel.trim(),
    ttsStreamUrl: validUrl(source.ttsStreamUrl, ['http:', 'https:'], '语音合成地址'),
    ttsCancelUrl: validCancelUrl(source.ttsCancelUrl),
    wakeWord: wakeWords.join('；'),
    alwaysListen: source.alwaysListen === true,
    sendCommands,
    approvalVoice: source.approvalVoice,
    summaryLength,
    summaryPrompt: summaryPrompt.trim(),
    summaryModel: summaryModel === null ? null : {
      provider: (summaryModel as { provider: string }).provider,
      model: (summaryModel as { model: string }).model,
    },
  }
}

export function loadServiceConfig(defaults: ServiceConfig): ServiceConfig {
  try {
    const saved = JSON.parse(readFileSync(serviceConfigPath(), 'utf8')) as Record<string, unknown>
    if (typeof saved.ttsBaseUrl === 'string' && saved.ttsStreamUrl === undefined) {
      const base = saved.ttsBaseUrl.replace(/\/+$/, '')
      saved.ttsStreamUrl = `${base}/tts/stream/cancellable`
      saved.ttsCancelUrl = `${base}/tts/cancel/{generationId}`
      if (typeof saved.asrBatchUrl === 'string') {
        const batchUrl = new URL(saved.asrBatchUrl)
        // 旧服务端也可能保存新版页面输入的完整地址；只有根地址可以安全补齐路径。
        if (batchUrl.pathname === '/') {
          batchUrl.pathname = '/v1/audio/transcriptions'
          saved.asrBatchUrl = batchUrl.toString()
        }
      }
    }
    if (Array.isArray(saved.sendCommands) && saved.sendCommands.length > 10) {
      console.warn('[dsh-voice-hub] 旧配置中的发送触发词超过 10 个，当前仅启用前 10 个；请在语音设置中检查并保存。')
      saved.sendCommands = saved.sendCommands.slice(0, 10)
    }
    return validateServiceConfig(saved)
  }
  catch (error) {
    if ((error as NodeJS.ErrnoException).code !== 'ENOENT') {
      console.warn(`[dsh-voice-hub] 语音服务配置读取失败，使用插件默认值：${error instanceof Error ? error.message : String(error)}`)
    }
    return defaults
  }
}

export async function saveServiceConfig(value: ServiceConfig): Promise<void> {
  const path = serviceConfigPath()
  await mkdir(dirname(path), { recursive: true })
  const temp = `${path}.${process.pid}.${randomUUID()}.tmp`
  await writeFile(temp, JSON.stringify(value, null, 2) + '\n', { mode: 0o600 })
  await rename(temp, path)
}

import * as React from 'react'
import { useEffect, useState } from 'react'
import { splitWakeWords } from './wakeword.ts'
import type { ServiceConfig } from './service-config.ts'

interface SummaryModelChoice { provider: string; model: string; name: string }

interface ConnectionResult { ok: boolean; ms: number; message: string }
type ConnectionResults = Record<'stream' | 'batch' | 'tts', ConnectionResult>

const BASE = '/voice-mode/service-config'
const fieldStyle: React.CSSProperties = {
  width: '100%', padding: '9px 11px', borderRadius: 8,
  color: 'var(--dsw-alias-label-primary)', background: 'var(--dsw-alias-bg-layer-2)',
  border: '1px solid var(--dsw-alias-border-l2)', fontSize: 13,
}

export function VoiceServiceSettingsPage(): React.ReactElement {
  const [value, setValue] = useState<ServiceConfig | null>(null)
  const [message, setMessage] = useState('正在读取语音服务配置…')
  const [busy, setBusy] = useState(false)
  const [checking, setChecking] = useState(false)
  const [results, setResults] = useState<ConnectionResults | null>(null)
  const [sendCommandsText, setSendCommandsText] = useState('')
  const [models, setModels] = useState<SummaryModelChoice[]>([])
  const [modelsError, setModelsError] = useState('')
  const resultsRef = React.useRef<HTMLUListElement>(null)
  useEffect(() => { if (results) resultsRef.current?.scrollIntoView({ block: 'nearest' }) }, [results])
  useEffect(() => {
    let alive = true
    void fetch('/voice-mode/summary-models').then(async (res) => {
      if (!res.ok) throw new Error('无法读取模型')
      return res.json() as Promise<{ models: SummaryModelChoice[] }>
    }).then((data) => { if (alive) setModels(data.models) })
      .catch(() => { if (alive) setModelsError('模型列表读取失败，可继续使用跟随主模型。') })
    void fetch(BASE).then(async (res) => {
      if (!res.ok) throw new Error(`HTTP（请求状态）${res.status}`)
      return res.json() as Promise<ServiceConfig>
    }).then((data) => {
      if (!alive) return
      if (typeof data.ttsStreamUrl !== 'string' || typeof data.ttsCancelUrl !== 'string') {
        setMessage('语音插件服务端仍在运行旧版本，请重启 DSH Web 并刷新页面。')
        return
      }
      setValue(data)
      setSendCommandsText(data.sendCommands.join('；'))
      setMessage('')
    })
      .catch(() => { if (alive) setMessage('读取语音服务配置失败，请检查插件是否启用。') })
    return () => { alive = false }
  }, [])

  const change = <K extends keyof ServiceConfig>(name: K, next: ServiceConfig[K]): void => {
    if (value) { setValue({ ...value, [name]: next }); setResults(null) }
  }
  const currentValue = (): ServiceConfig => ({
    ...value!,
    wakeWord: splitWakeWords(value!.wakeWord).join('；'),
    sendCommands: sendCommandsText.split(/[;；]/).map((item) => item.trim()).filter(Boolean),
  })

  const check = async (): Promise<void> => {
    if (!value || busy || checking) return
    setChecking(true)
    setResults(null)
    setMessage('正在测试语音服务连接…')
    try {
      const res = await fetch('/voice-mode/service-check', {
        method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(currentValue()),
      })
      const data = await res.json() as { error?: string; results?: ConnectionResults }
      if (!res.ok || !data.results) throw new Error(data.error ?? `HTTP（请求状态）${res.status}`)
      setResults(data.results)
      setMessage(Object.values(data.results).every((item) => item.ok) ? '流式识别、批量识别和语音合成连接成功；取消地址已检查格式。' : '部分语音服务连接失败，请查看下方结果。')
    } catch (error) { setMessage(`测试连接失败：${error instanceof Error ? error.message : String(error)}`) }
    finally { setChecking(false) }
  }
  const save = async (): Promise<void> => {
    if (!value || busy) return
    setBusy(true)
    setMessage('正在保存…')
    try {
      const res = await fetch(BASE, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(currentValue()) })
      const data = await res.json() as { error?: string; config?: ServiceConfig }
      if (!res.ok) throw new Error(data.error ?? `HTTP（请求状态）${res.status}`)
      if (data.config) { setValue(data.config); setSendCommandsText(data.config.sendCommands.join('；')) }
      window.dispatchEvent(new Event('dshvm-config-saved'))
      setMessage('已保存。摘要配置用于下一次播报；常开唤醒及唤醒词在返回聊天页后生效，发送触发词在下次进入语音模式时生效。')
    } catch (error) { setMessage(`保存失败：${error instanceof Error ? error.message : String(error)}`) }
    finally { setBusy(false) }
  }

  const fields: Array<{ key: 'asrStreamUrl' | 'asrBatchUrl' | 'asrModel' | 'ttsStreamUrl' | 'ttsCancelUrl' | 'wakeWord'; label: string; hint: string }> = [
    { key: 'asrStreamUrl', label: '流式语音识别地址', hint: 'WebSocket（实时连接）完整地址，用于实时字幕和语音命令。' },
    { key: 'asrBatchUrl', label: '批量语音识别地址', hint: 'HTTP（网络请求）转写接口完整地址，流式失败时用于定稿兜底。' },
    { key: 'asrModel', label: '批量识别模型', hint: '批量转写请求中的 model（模型名）参数。' },
    { key: 'ttsStreamUrl', label: '语音合成地址', hint: 'HTTP（网络请求）流式合成接口完整地址，回复与待处理事项提醒共用。' },
    { key: 'ttsCancelUrl', label: '语音合成取消地址', hint: '填写完整接口地址，{generationId} 由插件自动替换，无需手填编号；留空时仅中断当前请求。' },
    { key: 'wakeWord', label: '唤醒词', hint: '最多 10 个，用中文分号「；」或英文分号「;」隔开；常开唤醒时说任意一个即可。手动点击麦克风无需说唤醒词。' },
  ]
  return <section data-dshvm-service-settings="page" style={{ maxWidth: 640, padding: '4px 0 32px', color: 'var(--dsw-alias-label-primary)' }}>
    <h2 style={{ fontSize: 20, margin: '0 0 8px' }}>语音设置</h2>
    <p style={{ fontSize: 13, color: 'var(--dsw-alias-label-secondary)', lineHeight: 1.6 }}>
      配置语音识别与合成服务。回复播报和待处理事项提醒共用合成服务，只需配置一次。
    </p>
    {value && <>
      {fields.map(({ key, label, hint }) => <label key={key} style={{ display: 'block', marginTop: 18 }}>
        <span style={{ display: 'block', fontSize: 13, fontWeight: 600, marginBottom: 4 }}>{label}</span>
        <span style={{ display: 'block', fontSize: 12, color: 'var(--dsw-alias-label-tertiary)', marginBottom: 7 }}>{hint}</span>
        <input style={fieldStyle} disabled={busy || checking} value={String(value[key])} onChange={(event) => change(key, event.target.value)} />
      </label>)}
      <label style={{ display: 'block', marginTop: 18 }}>
        <span style={{ display: 'block', marginBottom: 7 }}>自动播报摘要字数</span>
        <input aria-label="自动播报摘要字数" type="number" min={10} max={300} step={1} style={fieldStyle}
          disabled={busy || checking} value={value.summaryLength} onChange={(event) => change('summaryLength', Number(event.target.value))} />
        <span style={{ fontSize: 12 }}>默认约 30 字，按每次模型调用已完成的正文生成；实际字数由模型决定。</span>
      </label>
      <label style={{ display: 'block', marginTop: 18 }}>
        <span style={{ display: 'block', marginBottom: 7 }}>摘要模型</span>
        <select aria-label="摘要模型" style={fieldStyle} disabled={busy || checking}
          value={value.summaryModel ? JSON.stringify(value.summaryModel) : ''}
          onChange={(event) => change('summaryModel', event.target.value ? JSON.parse(event.target.value) as ServiceConfig['summaryModel'] : null)}>
          <option value="">跟随本次主模型</option>
          {value.summaryModel && !models.some((model) => model.provider === value.summaryModel?.provider && model.model === value.summaryModel?.model)
            && <option value={JSON.stringify(value.summaryModel)}>{value.summaryModel.provider} / {value.summaryModel.model}（当前配置）</option>}
          {models.map((model) => <option key={JSON.stringify([model.provider, model.model])}
            value={JSON.stringify({ provider: model.provider, model: model.model })}>{model.name}</option>)}
        </select>
        <span style={{ fontSize: 12 }}>{modelsError || '使用 DSH 已配置的模型和凭据。每条自动播报额外调用一次模型。'}</span>
      </label>
      <label style={{ display: 'block', marginTop: 18 }}>
        <span style={{ display: 'block', marginBottom: 7 }}>摘要提示词</span>
        <textarea aria-label="摘要提示词" rows={5} style={fieldStyle} disabled={busy || checking}
          value={value.summaryPrompt} onChange={(event) => change('summaryPrompt', event.target.value)} />
        <span style={{ fontSize: 12 }}>{'{length} 会替换为上面的目标字数。保存后用于下一条摘要。'}</span>
      </label>
      <label style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 20, fontSize: 13 }}>
        <input type="checkbox" disabled={busy || checking} checked={value.alwaysListen} onChange={(event) => change('alwaysListen', event.target.checked)} />
        常开唤醒（{value.alwaysListen ? '已开启' : '已关闭'}）
      </label>
      <p style={{ margin: '6px 0 0 25px', fontSize: 12, lineHeight: 1.6, color: 'var(--dsw-alias-label-tertiary)' }}>
        开启后，聊天页可见时在浏览器本机监听唤醒词，喊中才启动语音识别；首次需允许麦克风。关闭或切走页面即停用待机监听。
      </p>
      <label style={{ display: 'block', marginTop: 18 }}>
        <span style={{ display: 'block', fontSize: 13, fontWeight: 600, marginBottom: 4 }}>发送触发词</span>
        <span style={{ display: 'block', fontSize: 12, color: 'var(--dsw-alias-label-tertiary)', marginBottom: 7 }}>最多 10 个，用中文分号「；」或英文分号「;」隔开；已有草稿时说出任一完整短句即可发送。留空则只使用手动发送。</span>
        <input style={fieldStyle} disabled={busy || checking} value={sendCommandsText} onChange={(event) => { setSendCommandsText(event.target.value); setResults(null) }} />
      </label>
      <label style={{ display: 'flex', alignItems: 'center', gap: 8, marginTop: 22, fontSize: 13 }}>
        <input type="checkbox" disabled={busy || checking} checked={value.approvalVoice} onChange={(event) => change('approvalVoice', event.target.checked)} />
        待审批、待回答和计划审阅时播放语音提示（{value.approvalVoice ? '已开启' : '已关闭'}）
      </label>
      <div style={{ display: 'flex', gap: 10, marginTop: 24, flexWrap: 'wrap' }}>
        <button type="button" disabled={busy || checking} onClick={() => void check()}
          style={{ padding: '9px 18px', border: '1px solid var(--dsw-alias-border-l2)', borderRadius: 8,
            cursor: checking ? 'wait' : 'pointer', color: 'var(--dsw-alias-label-primary)', background: 'var(--dsw-alias-bg-layer-2)' }}>
          {checking ? '正在测试…' : '测试连接'}
        </button>
        <button type="button" disabled={busy || checking} onClick={() => void save()}
          style={{ padding: '9px 18px', border: 0, borderRadius: 8, cursor: busy ? 'wait' : 'pointer',
            color: 'white', background: 'var(--dsw-alias-brand-primary)' }}>保存配置</button>
      </div>
