/** 按精度构造 Kokoro 校验清单（主模型文件 + 各自 SHA256；支持文件共用）。 */
export function kokoroSpec(model: KokoroModel): EngineSpec {
  const main: ModelFileSpec =
    model === 'fp32'
      ? { file: 'model.onnx', sha256: 'acc4adc175b9d9986106cd20060329673ad5a2e12ef3c557d2d3745b694f8b38' }
      : { file: 'model.int8.onnx', sha256: 'bda15858163726a492d02a9a727bc263551b86ac77f90812c4b30ff41d380e26' }
  return {
    files: [main, ...KOKORO_SHARED_FILES],
    workerPaths: (dir) => kokoroWorkerPaths(dir, main.file),
    defaultVoice: 'zf_xiaobei',
    toSid: kokoroVoiceToSid,
  }
}

/**
 * 本地 TTS 引擎（TtsEngine 实现，vits / kokoro 共用骨架）。懒加载：首次合成才
 * 校验模型并在子进程创建引擎实例；失败抛错（上层走退避重试）。
 * 子进程崩溃时自动重建（下次合成触发）。kokoro 走原生 addon，无"每 3 句重启"。
 */
export function createSherpaLocalEngine(options: LocalEngineOptions): TtsEngine {
  const { cacheDir, modelHost, allowCustomHost, broadcast } = options
  /** 当前模型下载进度（ensureModelFile/Tree 以 asr-progress 广播时更新，供设置面板轮询展示）。 */
  let downloadProgress: { file: string; percent: number } | null = null
  const trackedBroadcast = (event: string, payload: unknown): void => {
    if (event === 'asr-progress' && payload && typeof payload === 'object') {
      const pr = payload as { file?: unknown; percent?: unknown }
      if (typeof pr.file === 'string' && typeof pr.percent === 'number') {
        downloadProgress = { file: pr.file, percent: Math.min(100, Math.max(0, pr.percent)) }
      }
    }
    broadcast(event, payload)
  }
  const kokoroModel: KokoroModel = options.model ?? 'int8'
  const spec = options.kind === 'kokoro' ? kokoroSpec(kokoroModel) : VITS_SPEC
  const repoName = options.kind === 'kokoro' ? kokoroModelDir(kokoroModel) : TTS_MODEL_REPO
  const repoDir = join(cacheDir, repoName)
  /** 子进程脚本路径：与 lib/index.js 同目录（构建产物 lib/tts-vits-worker.cjs，CJS 以获得 IPC）。 */
  const workerPath = fileURLToPath(new URL('./tts-vits-worker.cjs', import.meta.url))

  let child: ChildProcess | null = null
  /** 当前子进程是否已完成 init（避免每句合成都重建引擎实例——旧实现
   *  ensureReady 每次都会发 init，导致 WASM 每句重载模型 3-5 秒 + 实例泄漏）。 */
  let childInit = false

  /** 杀掉子进程（下一句合成时自动重启）。 */
  const respawnChild = async (): Promise<void> => {
    if (child) {
      child.kill()
      child = null
    }
    childInit = false
    ready = null
  }
  let voice = spec.defaultVoice
  let speed = 1.0
  let ready: Promise<void> | null = null
  /** 引擎/模型现状（设置面板轮询）：加载中 / 最近错误。 */
  let engineLoading = false
  let engineError: string | undefined
  let nextId = 1
  const pending = new Map<number, { resolve: (r: WorkerResponse) => void; reject: (e: Error) => void }>()

  /** 主线程 ↔ 合成子进程的请求-应答（带 id 关联，支持并发排队）。 */
  const call = (msg: Record<string, unknown>): Promise<WorkerResponse> =>
    new Promise<WorkerResponse>((resolve, reject) => {
      if (!child) {
        reject(new Error('tts child not running'))
        return
      }
      const id = nextId++
      pending.set(id, { resolve, reject })
      child.send({ id, ...msg })
    })

  const rejectAll = (e: Error): void => {
    for (const p of pending.values()) p.reject(e)
    pending.clear()
  }

  const ensureReady = (): Promise<void> => {
    if (ready && child) return ready
    if (!ready) {
      ready = (async () => {
        engineLoading = true
        engineError = undefined
        downloadProgress = null
        try {
        // 冷启动/重建时才校验模型与 init（旧实现每句合成都重哈希数百 MB 模型
        // 文件并重建引擎实例——句间 3-5 秒停顿的真正元凶）。
        if (!child || !childInit) {
          // 1) 模型文件：主线程校验/下载（带 共用连接 进度广播）。
          for (const f of spec.files) {
            const ok = await ensureModelFile({
              repo: repoName,
              repoDir,
              spec: f,
              primaryHost: modelHost(),
              allowCustomHost,
              broadcast: trackedBroadcast,
            })
            if (!ok) throw new Error('local TTS model download/verify failed: ' + f.file)
          }
          // 1b) Kokoro：espeak-ng-data 是按目录分发的 ~355 个语音表文件，spec 只列
          //     phontab 作哨兵；必须整树补全，否则 worker 报 "phonindex does not exist"。
          if (options.kind === 'kokoro') {
            const treeOk = await ensureModelTree({
              repo: repoName,
              repoDir,
              subdir: 'espeak-ng-data',
              primaryHost: modelHost(),
              allowCustomHost,
              broadcast: trackedBroadcast,
            })
            if (!treeOk) throw new Error('local TTS model download failed: espeak-ng-data')
          }
          // 2) 子进程：加载模型并合成（同步 CPU 在子进程内，不阻塞主线程；
          //    kokoro 走原生 addon（稳定无 Abort），vits 走 WASM（子进程主线程实测稳定）。
          if (!child) {
            child = fork(workerPath, [], { stdio: ['ignore', 'ignore', 'pipe', 'ipc'] })
            // 过滤 sherpa 原生 addon 的已知噪音日志（英文句每句一条 "Skip unknown phonemes"）；
            // 其余 stderr 原样转发，便于诊断真实错误。
            // 注意：stderr 分块可能把一行劈成两半，必须按行缓冲后再过滤，否则
            // 后半截含关键词的碎行会漏出来刷屏（2026-08 实测）。
            let stderrTail = ''
            child.stderr?.on('data', (chunk: Buffer) => {
              stderrTail += String(chunk)
              const lines = stderrTail.split('\n')
              stderrTail = lines.pop() ?? ''
              for (const line of lines) {
                const s = line.trim()
                if (!s) continue
                if (/Skip unknown phonemes/.test(s)) continue
                console.error(`[tts-worker:${options.kind}] ${s}`)
              }
            })
            child.on('message', (m: WorkerResponse) => {
              const p = pending.get(m.id)
              if (!p) return
              pending.delete(m.id)
              if (m.ok) p.resolve(m)
              else p.reject(new Error(m.error ?? 'tts child error'))
            })
            child.on('error', (e) => {
              rejectAll(e instanceof Error ? e : new Error(String(e)))
              child = null
              childInit = false
              ready = null
            })
            child.on('exit', (code) => {
              rejectAll(new Error(`tts child exited with code ${code}`))
              child = null
              childInit = false
              ready = null
            })
          }
          if (!childInit) {
            const init = await call({ type: 'init', kind: options.kind, paths: spec.workerPaths(repoDir) })
            if (!init.ok) throw new Error(init.error ?? 'tts child init failed')
            childInit = true
          }
        }
        broadcast('tts-ready', { engine: options.kind, worker: true })
        } catch (e) {
          engineError = e instanceof Error ? e.message : String(e)
          throw e
        } finally {
          engineLoading = false
        }
      })().finally(() => {
        ready = null
      })
    }
    return ready
  }

  return {
    mime: 'audio/wav',
    updateVoice(nextVoice: string, nextRate?: number): void {
      voice = nextVoice || voice
      if (typeof nextRate === 'number' && Number.isFinite(nextRate)) {
        speed = Math.min(2, Math.max(0.5, nextRate))
      }
    },
    status(): TtsEngineStatus {
      // 本地引擎：按 spec 清单统计当前模型文件现状（存在/字节），用于设置面板展示。
      // local.ready = 全部必需模型文件已就绪（缓存完整）；引擎 ready = 子进程已 init。
      const files = spec.files.map((f: ModelFileSpec): TtsFileStatus => {
        const p = join(repoDir, f.file)
        let exists = false
        let size = 0
        try {
          const st = statSync(p)
          exists = st.isFile()
          size = st.size
        } catch {
          // 文件不存在：exists=false
        }
        return { name: f.file, exists, size }
      })
      return {
        engine: options.kind,
        ready: childInit === true,
        loading: engineLoading,
        error: engineError,
        progress: downloadProgress ?? undefined,
        local: {
          repo: repoName,
          ready: files.every((f) => f.exists),
          loading: engineLoading,
          error: engineError,
          files,
        },
      }
    },
    // 设置面板「下载」按钮：无文本也触发模型下载 + 子进程初始化（与首次合成路径一致）。
    prepare: () => ensureReady(),
    async synthesize(text: string, opts: { voice?: string; rate?: number } = {}): Promise<Buffer> {
      await ensureReady()
      const sid = spec.toSid(opts.voice ?? voice)
      const spd =
        typeof opts.rate === 'number' && Number.isFinite(opts.rate)
          ? Math.min(2, Math.max(0.5, opts.rate))
          : speed
      // 批 4 / ADR-0007 步 1：解析 emotion 标签为段序列（break/whisper/laugh/sigh/emphasis）。
      // 处理点全收在 synthesize 内部，tts-queue pump 与帧协议零触碰（I4/I5 天然无风险）。
      // 无标签（常规文本）→ 段序列 = [{text, whisper:false}]，行为与改造前逐字节等价（I10）。
      const segments = parseEmotionTags(text)
      if (segments.length === 0) {
        // 全部都是单标签（laugh/sigh/emphasis）—— 不产生音频，返回最短 WAV（44 字节 RIFF 头 + 0 长度 PCM）。
        return pcmToWav(Buffer.alloc(0), 16000)
      }
      // 逐段调子进程合成 + 拼 PCM；段间插静音（紧跟 break）；whisper 段乘 0.5。
      const chunks: Float32Array[] = []
      let resolvedSampleRate = 0
      let needsRespawn = true // Aborted 重试只对第一段生效（避免多段重复重启）
      for (let i = 0; i < segments.length; i++) {
        const seg = segments[i]
        const preBreak = (seg as { preBreakMs?: number }).preBreakMs ?? 0
        let res = await call({ type: 'synth', text: seg.text, sid, speed: spd })
        if (!res.ok && /Aborted/.test(res.error ?? '') && needsRespawn) {
          await respawnChild()
          res = await call({ type: 'synth', text: seg.text, sid, speed: spd })
          needsRespawn = false
        }
        if (!res.ok) throw new Error(res.error ?? 'local TTS synthesis failed')
        if (typeof res.samples !== 'string' || res.samples.length === 0) continue
        const bytes = Buffer.from(res.samples, 'base64')
        const samples = new Float32Array(bytes.buffer, bytes.byteOffset, bytes.byteLength / 4)
        if (samples.length === 0) continue
        const sr = res.sampleRate || 16000
        if (!resolvedSampleRate) resolvedSampleRate = sr
        // whisper 作用域内：增益 ×0.5
        if (seg.whisper) {
          for (let j = 0; j < samples.length; j++) samples[j] *= 0.5
        }
        // 段样本
        chunks.push(samples)
        // 段后置静音（plan §6.0「段后置静音」语义：preBreakMs 标在「 break 之前的最后一段」上，
        //   tts-local 合成该段 PCM 后插静音 PCM；末尾 break 由 emotion.ts 收尾挂在 out[last]）。
        if (preBreak > 0 && resolvedSampleRate) {
          chunks.push(new Float32Array(Math.round((resolvedSampleRate * preBreak) / 1000)))
        }
      }
      if (chunks.length === 0) {
        // 全部段都返回了空 samples（罕见——合成器空响应）
        return pcmToWav(Buffer.alloc(0), resolvedSampleRate || 16000)
      }
      const total = chunks.reduce((acc, c) => acc + c.length, 0)
      const merged = new Float32Array(total)
      let off = 0
      for (const c of chunks) {
        merged.set(c, off)
        off += c.length
      }
      return pcmToWav(floatToPcm16(merged), resolvedSampleRate || 16000)
    },
    async close(): Promise<void> {
      // 先捕获引用再 await：await 期间子进程可能退出、exit 回调把 child 置 null，
      // 回来再 child.kill() 会打到 null（dsh 关停时曾因此 fatal load failure）。
      const c = child
      if (c) {
        try {
          await call({ type: 'close' })
        } catch {
          // ignore
        }
        try {
          c.kill()
        } catch {
          // ignore（关闭路径绝不抛错）
        }
      }
      child = null
      childInit = false
      ready = null
    },
    interrupt(): void {
      // 打断时立刻杀子进程：在途合成句已被作废，杀掉立即释放满核 CPU
      // （否则会饿死主进程的 ASR 解码——打断后定稿等待分钟级的实测根因）。
      // 下一句合成自动重建（约 1 秒模型加载）。
      void respawnChild()
    },
  }
}

/** 兼容旧导出：VITS 本地引擎。 */
export function createSherpaVitsEngine(options: Omit<LocalEngineOptions, 'kind'>): TtsEngine {
  return createSherpaLocalEngine({ ...options, kind: 'vits' })
}

/** Kokoro 中英本地引擎。 */
export function createSherpaKokoroEngine(options: Omit<LocalEngineOptions, 'kind'>): TtsEngine {
  return createSherpaLocalEngine({ ...options, kind: 'kokoro' })
}

/**
 * 逐会话 TTS 队列：串行合成 + SSE 广播。
 *
 * 合成引擎抽象为 TtsEngine 接口——EdgeTtsEngine（微软云端 Edge TTS）与本地
 * VITS/Kokoro（tts-local.ts）都实现同一接口，队列/分句/打断/退避逻辑完全复用。
 *
 * 分块转发协议（P1-1，与 client 拼帧兼容）：引擎整句合成得到 Buffer 后，pump
 * 以「单个 chunk + final 帧」下发——Edge 与本地引擎统一走同一协议，客户端按句
 * 拼帧解码起播（本地 VITS/Kokoro 为单 chunk WAV，Edge 为单 chunk MP3）。
 *
 * 打断（Q2/Q8）：cancel() 提升会话 epoch——积压句子全弃，合成中句子在下一
 * chunk 到达时被丢弃，实现真正的静音。
 */
import { MsEdgeTTS, OUTPUT_FORMAT, type ProsodyOptions } from './msedge-tts-compat.ts'

/** 合成引擎统一接口（云端/本地实现互替）。 */
export interface TtsEngine {
  /** 产出音频的 MIME（audio/mpeg = Edge；audio/wav = 本地 VITS/Kokoro）。 */
  readonly mime: string
  /** 热更新音色/语速（设置变更即时生效）。 */
  updateVoice(voice: string, rate?: number): void
  /** 合成一段文本为音频字节；失败抛错（上层退避重试）。 */
  synthesize(text: string, options?: { voice?: string; rate?: number }): Promise<Buffer>
  /** 打断：立刻中止在途合成并释放计算资源（本地引擎杀子进程；下一句自动重建）。 */
  interrupt?(): void
  /** 释放引擎资源（插件卸载/热重载）。 */
  close(): Promise<void>
  /** 引擎/模型现状（设置面板状态区轮询；可选）。 */
  status?(): TtsEngineStatus
  /** 预热/下载本地模型并初始化（设置面板「下载」按钮；Edge 无操作，缺省不实现）。 */
  prepare?(): Promise<void>
}

/** 单个模型文件的存在状态（用于设置面板现状展示）。 */
export interface TtsFileStatus {
  name: string
  exists: boolean
  size: number
}

/** 本地引擎某模型的组状态（仓库内文件 + 就绪/加载/失败）。 */
export interface TtsModelGroup {
  repo: string
  /** 组内全部必需文件已就绪（校验通过）。 */
  ready: boolean
  /** 正在初始化/加载（下载/子进程 init）。 */
  loading: boolean
  /** 最近一次加载/下载错误（可读字符串）。 */
  error?: string
  files: TtsFileStatus[]
}

/** 引擎/模型现状（设置面板轮询）。 */
export interface TtsEngineStatus {
  /** 当前生效引擎。 */
  engine: 'edge' | 'vits' | 'kokoro' | 'remote'
  /** 当前引擎是否就绪（本地：模型校验 + 子进程 init；edge：恒 true）。 */
  ready: boolean
  /** 当前引擎正在初始化/加载。 */
  loading: boolean
  /** 当前引擎最近一次错误。 */
  error?: string
  /** 当前模型下载进度（本地引擎下载时；edge 无）。 */
  progress?: { file: string; percent: number }
  /** 当前引擎的模型组（edge 无 local）。 */
  local?: TtsModelGroup
}

/** TTS 分块帧（P1-1）：单 chunk 合成场景下 chunkId 固定 0，final=true 帧携带字幕文本。 */
export interface TtsChunkFrame {
  sessionId: string
  /** 句序号（句级不变；客户端按句拼帧）。 */
  sentenceId: number
  /** chunk 序号（句内递增；单 chunk 场景恒为 0）。 */
  chunkId: number
  /** true = 本句最后一个 chunk，此后客户端拼帧完成可起播。 */
  final: boolean
  /** 句子文本（剥离 markdown 后；仅 final 帧携带）。 */
  text?: string
  /** base64 音频分片。 */
  audio: string
  /** 音频 MIME（client 据此构造 Blob 类型：audio/wav 或 audio/mpeg）。 */
  mime?: string
}

export type FrameListener = (frame: TtsChunkFrame) => void

const MP3_MAGIC = 0xff

/** setMetadata 的统一选项：句子/词边界回调都不需要（帧内无字幕元数据）。 */
const TTS_METADATA = { wordBoundaryEnabled: false, sentenceBoundaryEnabled: false } as const

function prosodyFromRate(rate?: number): ProsodyOptions | undefined {
  if (rate !== undefined && rate > 0 && rate !== 1) return { rate }
  return undefined
}

/** 合法 MP3 帧以同步字开头；空音频（如英文音色读不了中文）视同无效。 */
function isValidMp3(buf: Buffer): boolean {
  return buf.length > 0 && buf[0] === MP3_MAGIC
}

/** Edge TTS 引擎（微软语音服务，云端；被朗读文本发送到微软）。 */
export class EdgeTtsEngine implements TtsEngine {
  private voice: string
  private rate?: number

  constructor(voice = 'zh-CN-XiaoxiaoNeural', rate?: number) {
    this.voice = voice
    this.rate = rate
  }

  readonly mime = 'audio/mpeg'

  updateVoice(voice: string, rate?: number): void {
    this.voice = voice
    if (rate !== undefined && Number.isFinite(rate)) this.rate = rate
  }

  async synthesize(text: string, options: { voice?: string; rate?: number } = {}): Promise<Buffer> {
    // Edge 直传云端，SSML 未启用，strip 另开批。
    const tts = new MsEdgeTTS()
    try {
      await tts.setMetadata(
        options.voice ?? this.voice,
        OUTPUT_FORMAT.AUDIO_24KHZ_48KBITRATE_MONO_MP3,
        TTS_METADATA,
      )
      const { audioStream } = tts.toStream(text, prosodyFromRate(options.rate ?? this.rate))
      const chunks: Buffer[] = []
      for await (const chunk of audioStream) chunks.push(chunk as Buffer)
      const buf = Buffer.concat(chunks)
      if (!isValidMp3(buf)) throw new Error('empty or invalid audio')
      return buf
    } finally {
      try {
        await tts.close()
      } catch {
        // ignore
      }
    }
  }

  async close(): Promise<void> {
    // 无持久连接（每句独立连接），无需清理。
  }
}

/** Edge 音色列表（重命名缓存；/voice-mode/voices 用；失败抛错由调用方处理）。 */
let edgeVoicesCache: Array<{ ShortName: string; Locale: string; Gender: string; FriendlyName: string }> | null = null
export async function listEdgeVoices(force = false): Promise<Array<{ ShortName: string; Locale: string; Gender: string; FriendlyName: string }>> {
  if (edgeVoicesCache && !force) return edgeVoicesCache
  const tts = new MsEdgeTTS()
  try {
    const voices = await tts.getVoices()
    edgeVoicesCache = voices.map((v) => ({
      ShortName: v.ShortName,
      Locale: v.Locale,
      Gender: v.Gender,
      FriendlyName: v.FriendlyName,
    }))
    return edgeVoicesCache
  } finally {
    try {
      await tts.close()
    } catch {
      // ignore
    }
  }
}

interface QueuedSentence {
  text: string
  epoch: number
  onSettled?: () => void
}

interface SessionQueue {
  pending: QueuedSentence[]
  busy: boolean
  seq: number
  /** cancel() 时提升；携带旧 epoch 的句子被丢弃。 */
  epoch: number
  /** TTS 不可达已通知过（去重，直到下一帧成功才复位）。 */
  errorNotified: boolean
  /** 错误退避毫秒（成功后清零）。 */
  backoff: number
}

export class TtsQueue {
  private readonly queues = new Map<string, SessionQueue>()
  private readonly listeners = new Set<FrameListener>()
  private engine: TtsEngine
  /** TTS 全体不可达通知（每会话去重，成功后复位）。 */
  private readonly onError?: (sessionId: string) => void
  /** 单句合成重试耗尽被跳过通知（每句一次；此前是静默丢句——真机「回复偶尔不朗读」根因之一）。 */
  private readonly onSkip?: (sessionId: string, text: string) => void

  constructor(options: {
    engine: TtsEngine
    onError?: (sessionId: string) => void
    onSkip?: (sessionId: string, text: string) => void
  }) {
    this.engine = options.engine
    this.onError = options.onError
    this.onSkip = options.onSkip
  }

  /** 当前引擎音频 MIME（/preview 的 Content-Type 也用它）。 */
  get mime(): string {
    return this.engine.mime
  }

  /**
   * 运行时切换引擎（设置面板「朗读引擎」即时生效）：
   * 关闭旧引擎、清空所有会话队列；新句子用新引擎合成。
   */
  setEngine(engine: TtsEngine): void {
    const old = this.engine
    this.engine = engine
    for (const q of this.queues.values()) {
      q.epoch++
      q.pending.length = 0
    }
    this.queues.clear()
    void old.close().catch(() => {})
  }

  /** 动态更换音色/语速（设置即时生效；正在合成的句子不受影响）。 */
  updateVoice(voice: string, rate?: number): void {
    this.engine.updateVoice(voice, rate)
  }

  /** 当前引擎/模型现状（设置面板状态区轮询）。 */
  status(): TtsEngineStatus {
    const s = this.engine.status?.()
    if (s) return s
    // Edge 云端引擎：无本地模型，视为恒就绪。
    return { engine: 'edge', ready: true, loading: false }
  }

  /** 触发当前引擎预热/下载模型并初始化（设置面板「下载」按钮；Edge 为无操作）。 */
  async prepare(): Promise<void> {
    await this.engine.prepare?.()
  }

  /**
   * 一次性合成（设置卡「试听」用）：委托当前引擎；不干扰朗读队列的在途合成。
   * 失败（含非法音色）抛错。
   */
  async synthesize(text: string, options: { voice?: string; rate?: number } = {}): Promise<Buffer> {
    return this.engine.synthesize(text, options)
  }

  subscribe(listener: FrameListener): () => void {
    this.listeners.add(listener)
    return () => {
      this.listeners.delete(listener)
    }
  }

  /** 为某会话入队一句；若泵空闲则启动。 */
  enqueue(sessionId: string, text: string, onSettled?: () => void): void {
    let q = this.queues.get(sessionId)
    if (!q) {
      q = { pending: [], busy: false, seq: 0, epoch: 0, errorNotified: false, backoff: 0 }
      this.queues.set(sessionId, q)
    }
    // 队列上限（防病理性积压失控）。20 → 500：长回复流式文本比 Edge 合成快时，
    // 积压超 20 就会静默丢最旧句子——「长话跳句」的另一来源。500 覆盖任意正常回复
    // 长度（每句仅几十字，内存无忧），仍留病理性护栏；超限告警而非静默。
    if (q.pending.length >= 500) {
      console.warn('[dsh-voice-hub] TTS（语音合成）队列已满，最早一句未播报')
      q.pending.shift()
    }
    q.pending.push({ text, epoch: q.epoch, onSettled })
    void this.pump(sessionId, q)
  }

  /**
   * 弃掉某会话的所有积压并作废正在合成的句子（打断）。之后入队的句子
   * 获得新 epoch 正常播放。同时立刻中止在途合成（本地引擎杀子进程释放 CPU）。
   */
  cancel(sessionId: string): void {
    const q = this.queues.get(sessionId)
    if (q) {
      q.epoch++
      q.pending.length = 0
    }
    // 立刻中止在途合成：本地引擎杀子进程释放 CPU（在途句已被作废；否则其
    // 满核合成会饿死主进程的 ASR 解码，打断后定稿等待可达分钟级——实测根因）。
    this.engine.interrupt?.()
  }

  /** 会话退出/被抢占时彻底清理其队列（防止 Map 长期累积）。 */
  prune(sessionId: string): void {
    const q = this.queues.get(sessionId)
    if (q) {
      // 双重奏根治：孤儿泵不死——prune 只 delete queue 不提升 epoch 时，旧 q 的 pump
      // 继续合成并广播旧回合句子（item.epoch === q.epoch 对旧 q 永真），与新泵并行 →
      // 客户端同时收到旧/新两套句子（双重奏）。提升 epoch 让孤儿泵在下一句检查时
      // break，停止广播；重入的新回合用新 queue（seq/epoch 从头）。
      q.epoch++
      q.pending.length = 0
    }
    this.queues.delete(sessionId)
  }

  private async pump(sessionId: string, q: SessionQueue): Promise<void> {
    if (q.busy) return
    q.busy = true
    try {
      while (q.pending.length > 0) {
        const item = q.pending.shift()!
        const settle = (): void => { try { item.onSettled?.() } catch { /* 通知失败不影响后续合成 */ } }
        // 单句合成有界重试：Edge 云端 WebSocket 偶发 ETIMEDOUT（实测日志），
        // 失败即静默丢句会表现为「长话没规律跳过几句」——重试 3 次、退避后仍失败才跳过。
        const MAX_SYNTH_ATTEMPTS = 3
        let buf: Buffer | null = null
        for (let attempt = 0; attempt < MAX_SYNTH_ATTEMPTS; attempt++) {
          if (item.epoch !== q.epoch) break // 打断：停止重试
          try {
            buf = await this.engine.synthesize(item.text)
            break
          } catch (e) {
            console.warn(`[dsh-voice-hub] 语音合成失败，重试 ${attempt + 1}/${MAX_SYNTH_ATTEMPTS}：${String(e)}`)
            if (attempt < MAX_SYNTH_ATTEMPTS - 1) {
              await new Promise((r) => setTimeout(r, 400 * (attempt + 1)))
            }
          }
        }
        if (item.epoch !== q.epoch) {
          settle()
          continue
        }
        if (buf === null) {
          // 重试耗尽：跳过该句（不阻塞队列），但**显式通知**调用方——静默丢句在真机上
          // 表现为「AI 回复偶尔整条/某句不朗读」，用户无从判断是网络还是功能坏了。
          this.onSkip?.(sessionId, item.text)
          settle()
          continue
        }
        q.errorNotified = false // 有帧成功：复位不可达提示
        q.backoff = 0 // 成功后退避清零，防下次失败时退避窗口无限递增
        const sentenceId = q.seq++
        const mime = this.engine.mime
        // 单 chunk（整句音频）+ final 帧（字幕文本）：客户端按句拼帧后解码起播。
        const dataFrame: TtsChunkFrame = {
          sessionId,
          sentenceId,
          chunkId: 0,
          final: false,
          audio: buf.toString('base64'),
          mime,
        }
        for (const fn of this.listeners) {
          try {
            fn(dataFrame)
          } catch {
            // listener 错误不得杀死泵
          }
        }
        const finalFrame: TtsChunkFrame = {
          sessionId,
          sentenceId,
          chunkId: 1,
          final: true,
          text: item.text,
          audio: '',
          mime,
        }
        for (const fn of this.listeners) {
          try {
            fn(finalFrame)
          } catch {
            // listener 错误不得杀死泵
          }
        }
        settle()
      }
    } catch (e) {
      // 引擎级失败：把句子推回以便重试；每会话只提示一次。
      // 批 A：补 sessionId 上下文（item / attempt 是 while/for 内部 const/let，
      // 外层 catch 不可见——不做捕获重构以保持外科手术式改动）。
      console.warn(`[dsh-voice-hub] TTS（语音合成）不可用：会话=${sessionId}，原因=${String(e)}`)
      if (!q.errorNotified) {
        q.errorNotified = true
        this.onError?.(sessionId)
      }
    } finally {
      q.busy = false
      // 防御：prune 后同会话立即重入时，孤儿泵不得带着残余 pending 重启
      // （否则与新的 SessionQueue 双泵并行合成）。
      if (this.queues.get(sessionId) !== q) return
      if (q.pending.length > 0) {
        // 失败退避：1s 指数递增至多 8s；成功/无错误即时。
        const delay = q.errorNotified ? q.backoff : 0
        q.backoff = Math.min(8000, delay + 1000)
        if (delay > 0) setTimeout(() => void this.pump(sessionId, q), delay)
        else void this.pump(sessionId, q)
      }
    }
  }

  async close(): Promise<void> {
    for (const sessionId of this.queues.keys()) this.cancel(sessionId)
    await this.engine.close()
  }
}

import { randomUUID } from 'node:crypto'
import type { TtsEngine, TtsEngineStatus } from './tts-queue.ts'

/** talk-sdk 的可取消流输出是 24 kHz、单声道、16 位 little-endian PCM。 */
export function pcm24ToWav(pcm: Buffer): Buffer {
  if (!pcm.length || pcm.length % 2) throw new Error('TTS（语音合成）返回空音频或未按 PCM（原始音频）16 位对齐')
  const wav = Buffer.allocUnsafe(44 + pcm.length)
  wav.write('RIFF', 0)
  wav.writeUInt32LE(36 + pcm.length, 4)
  wav.write('WAVEfmt ', 8)
  wav.writeUInt32LE(16, 16)
  wav.writeUInt16LE(1, 20)
  wav.writeUInt16LE(1, 22)
  wav.writeUInt32LE(24000, 24)
  wav.writeUInt32LE(48000, 28)
  wav.writeUInt16LE(2, 32)
  wav.writeUInt16LE(16, 34)
  wav.write('data', 36)
  wav.writeUInt32LE(pcm.length, 40)
  pcm.copy(wav, 44)
  return wav
}

export class RemoteTtsEngine implements TtsEngine {
  readonly mime = 'audio/wav'
  private readonly streamUrl: () => string
  private readonly cancelUrl: () => string
  private inFlight: { id: string; abort: AbortController } | null = null
  private lastError: string | undefined

  constructor(streamUrl: () => string, cancelUrl: () => string) {
    this.streamUrl = streamUrl
    this.cancelUrl = cancelUrl
  }

  updateVoice(): void {
    // talk-sdk 当前没有音色和语速入参；设置页在远端模式下不展示这两个控件。
  }

  async synthesize(text: string): Promise<Buffer> {
    const id = randomUUID().replaceAll('-', '')
    const abort = new AbortController()
    this.inFlight = { id, abort }
    try {
      const res = await fetch(this.streamUrl(), {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ text, generationId: id }),
        signal: abort.signal,
      })
      if (!res.ok) throw new Error(`TTS（语音合成）HTTP（请求状态）${res.status}`)
      const pcm = Buffer.from(await res.arrayBuffer())
      const wav = pcm24ToWav(pcm)
      this.lastError = undefined
      return wav
    } catch (error) {
      this.lastError = error instanceof Error ? error.message : String(error)
      throw error
    } finally {
      if (this.inFlight?.id === id) this.inFlight = null
    }
  }

  interrupt(): void {
    const active = this.inFlight
    if (!active) return
    active.abort.abort()
    this.inFlight = null
    const cancelUrl = this.cancelUrl()
    if (!cancelUrl) return
    void fetch(cancelUrl.replace('{generationId}', encodeURIComponent(active.id)), {
      method: 'POST', signal: AbortSignal.timeout(3000),
    }).catch((error) => console.warn(`[dsh-voice-hub] TTS（语音合成）取消失败：${String(error)}`))
  }

  status(): TtsEngineStatus {
    return { engine: 'remote', ready: !this.lastError, loading: !!this.inFlight, error: this.lastError }
  }

  async close(): Promise<void> {
    this.interrupt()
  }
}

/**
 * fork 新增：本地 TTS 合成子进程（child_process.fork），支持 vits / kokoro 两种引擎。
 *
 * 运行时分工：
 *  - vits（纯中文）：sherpa-onnx WASM（createOfflineTts）。WASM 在 worker_threads
 *    下有 Abort() 缺陷，子进程主线程形态实测稳定，故仍走子进程。
 *  - kokoro（中英多语言）：sherpa-onnx-node 原生 addon（new OfflineTts）。
 *    原生 onnxruntime 无 WASM 内存上限/累积 Abort 问题，2026-08 spike 实测
 *    连续 98+ 句合成无崩溃，不再需要"每 3 句重启子进程"；numThreads=4 时
 *    RTF≈0.55（WASM 无真线程）。
 *
 * 协议（主进程 → 子进程）：
 *   init { type:'init', id, kind:'vits'|'kokoro', paths }
 *     vits   paths: { model, lexicon, tokens, date, phone, number }
 *     kokoro paths: { model, voices, tokens, dataDir, lexicon }
 *   { type: 'synth', id, text, sid, speed }  → 回 { id, ok, sampleRate, samples(base64 f32) }
 *   { type: 'close', id }                    → 回 { id, ok }
 */
import sherpa_onnx from 'sherpa-onnx'
import sherpa_node from 'sherpa-onnx-node'
import { sanitizeForTts } from './segmenter'

interface WasmTts {
  generate(input: { text: string; sid: number; speed: number }): { samples: Float32Array; sampleRate: number }
  free(): void
}

interface NativeTts {
  generate(input: { text: string; generationConfig: unknown }): { samples: Float32Array; sampleRate: number }
  free(): void
}

const { createOfflineTts } = sherpa_onnx as unknown as {
  createOfflineTts(config: Record<string, unknown>): WasmTts
}

const { OfflineTts, GenerationConfig } = sherpa_node as unknown as {
  OfflineTts: new (config: Record<string, unknown>) => NativeTts
  GenerationConfig: new (opts: Record<string, unknown>) => unknown
}

const send = (msg: Record<string, unknown>): void => {
  if (typeof process.send === 'function') process.send(msg)
}

let wasmTts: WasmTts | null = null
let nativeTts: NativeTts | null = null
let initKind: 'vits' | 'kokoro' = 'vits'
let initPaths: Record<string, string> = {}

function createEngine(): void {
  if (initKind === 'kokoro') {
    nativeTts = new OfflineTts({
      model: {
        kokoro: {
          model: initPaths.model,
          voices: initPaths.voices,
          tokens: initPaths.tokens,
          dataDir: initPaths.dataDir,
          lexicon: initPaths.lexicon,
        },
        // 2 线程：留核给主进程的 ASR 解码（4 线程满核会饿死识别，
        // 打断后定稿等待分钟级；2 线程 RTF≈1 仍实时）。
        numThreads: 2,
        debug: 0,
        provider: 'cpu',
      },
      // 中文数字/日期/电话规范化（与 VITS 同源 FST）：阿拉伯数字按中文读。
      ruleFsts: [initPaths.date, initPaths.phone, initPaths.number].filter(Boolean).join(','),
      maxNumSentences: 1,
    })
    return
  }
  wasmTts = createOfflineTts({
    model: {
      vits: {
        model: initPaths.model,
        lexicon: initPaths.lexicon,
        tokens: initPaths.tokens,
      },
      numThreads: 1,
      debug: 0,
      provider: 'cpu',
    },
    ruleFsts: [initPaths.date, initPaths.phone, initPaths.number].join(','),
    ruleFars: '',
    maxNumSentences: 1,
  })
}

function reply(id: unknown, payload: Record<string, unknown>): void {
  send({ id: typeof id === 'number' ? id : 0, ...payload })
}

process.on('message', (msg: Record<string, unknown>) => {
  try {
    if (msg.type === 'init') {
      initKind = msg.kind === 'kokoro' ? 'kokoro' : 'vits'
      initPaths = msg.paths as Record<string, string>
      createEngine()
      reply(msg.id, { ok: true })
      return
    }
    if (msg.type === 'synth') {
      // 剥离 emoji/特殊符号（本地引擎词表不认识，逐字打 "Unknown token" 噪音）；
      // "1. 2."式编号消毒：数字后接 ASCII 句点改为顿号；
      // 再兜底剔除会被英文念出的 markdown 噪声字符（试听等不经分句器的路径）。
      const text = sanitizeForTts(
        String(msg.text ?? '')
          .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2190}-\u{21FF}\u{2B00}-\u{2BFF}]/gu, ' ')
          .replace(/(\d)[.．]\s*/g, '$1、'),
      )
      if (!text.trim()) {
        // 清洗后为空（纯 emoji/符号段）：回 0.2s 静音，避免引擎报
        // "Failed to convert '' to token IDs" 噪音（队列继续、该句无声）。
        const sr = 24000
        reply(msg.id, {
          ok: true,
          sampleRate: sr,
          samples: Buffer.alloc(Math.floor(sr * 0.2) * 4).toString('base64'),
        })
        return
      }
      const sid = Number(msg.sid ?? 0)
      const speed = Number(msg.speed ?? 1)
      let audio: { samples: Float32Array; sampleRate: number }
      if (initKind === 'kokoro') {
        if (!nativeTts) {
          reply(msg.id, { ok: false, error: 'tts child not initialized' })
          return
        }
        const gc = new GenerationConfig({ sid, speed, silenceScale: 0.2 })
        audio = nativeTts.generate({ text, generationConfig: gc })
      } else {
        if (!wasmTts) {
          reply(msg.id, { ok: false, error: 'tts child not initialized' })
          return
        }
        audio = wasmTts.generate({ text, sid, speed })
      }
      // 本环境 fork IPC 为 JSON 序列化（Buffer/ArrayBuffer 会被降级成对象）——
      // 用 base64 字符串传输样本（帧约数百 KB，开销可忽略）。
      const buf = Buffer.from(audio.samples.buffer, audio.samples.byteOffset, audio.samples.byteLength)
      reply(msg.id, { ok: true, sampleRate: audio.sampleRate, samples: buf.toString('base64') })
      return
    }
    if (msg.type === 'close') {
      try {
        wasmTts?.free()
      } catch {
        // ignore
      }
      try {
        nativeTts?.free()
      } catch {
        // ignore
      }
      wasmTts = null
      nativeTts = null
      reply(msg.id, { ok: true })
      return
    }
    reply(msg.id, { ok: false, error: `unknown message type: ${String(msg.type)}` })
  } catch (e) {
    reply(typeof msg?.id === 'number' ? msg.id : 0, { ok: false, error: String(e) })
  }
})

import type { Context } from '@deepseek-ai/cordis'
import { Remote, TypertRemoteService } from '@deepseek-ai/dsh-typert-protocol'

/** 主模型完成一次正文后，供语音消费者使用的独立摘要。 */
export interface SpeechSummaryEvent {
  type: 'speech-summary'
  sessionId: string
  sourceMessageId: string
  turn: number
  step: number
  text: string
  targetTabId: string
  generationMs: number
}

export type VoiceStatusData = Record<string, string | number | boolean | null>
export type VoiceEvent = SpeechSummaryEvent | {
  type: 'voice-status'
  event: string
  data: VoiceStatusData
}

/** 音频和状态复用 DSH 的 remote.mux 连接；不写入 Session 历史。 */
export class VoiceModeRemote extends TypertRemoteService {
  constructor(ctx: Context, private readonly subscribe: (tabId: string, send: (event: VoiceEvent) => void) => () => void) {
    super(ctx, 'voiceMode')
  }

  @Remote({ mode: 'stream' })
  async *follow(tabId: string, signal: AbortSignal): AsyncIterable<VoiceEvent> {
    if (!tabId || tabId.length > 64) throw new Error('标签页无效')
    signal.throwIfAborted()
    const pending: VoiceEvent[] = []
    let wake: (() => void) | undefined
    const stop = this.subscribe(tabId, (event) => {
      pending.push(event)
      wake?.()
    })
    const abort = (): void => { stop(); wake?.() }
    signal.addEventListener('abort', abort, { once: true })
    try {
      while (!signal.aborted) {
        if (!pending.length) await new Promise<void>((resolve) => { wake = resolve })
        wake = undefined
        while (!signal.aborted && pending.length) yield pending.shift()!
      }
    } finally {
      signal.removeEventListener('abort', abort)
      stop()
    }
  }
}

/**
 * 唤醒词匹配（客户端，纯函数可单测）。
 *
 * 语义：唤醒词是「待机态 → 激活态」的门。由于 host zipformer2 返回的是
 * 当前段累计识别文本（增量的是音频），这里做归一化后的**词首子串**匹配：
 * 唤醒词出现在段文本头部即命中，避免「xx你好小D」中段偶然命中。
 *
 * 容错慢路径（issue #10 问题 1）：startsWith 严格快路径未命中时，允许
 * ① 前导字符平移（窗口起点在开头 WAKE_LEAD_CHARS 字符内——吸收「呃/喂/我说」
 * 这类非白名单前导）；② 窗口与唤醒词之间 Levenshtein 编辑距离 ≤ WAKE_MAX_EDITS
 * （吸收同音字替换「小莫→小墨」与首字错「→晓莫」）。窗口长度限制在
 * 「唤醒词长度 ± 1」且 ≥2 字（否则「小」与「小莫」距离为 1，零散字符会误触发）。
 * 单字唤醒词不走慢路径（1 字词的编辑距离 1 = 全匹配，保持精确匹配现状）。
 *
 * 当前常开唤醒由浏览器本地 sherpa-onnx KWS 执行；这些函数仍用于旧 ASR 待机路径。
 */

/** 容错慢路径参数：前导噪声窗口宽度（吸收「呃/喂/我说」类前导字符）。 */
const WAKE_LEAD_CHARS = 3
/** 容错慢路径参数：窗口与唤醒词之间允许的最大编辑距离（吸收同音字/首字错）。 */
const WAKE_MAX_EDITS = 1

/** 设置页和服务配置共用的唤醒词分隔规则。 */
export function splitWakeWords(value: string): string[] {
  return value.split(/[;；]/).map((word) => word.trim()).filter(Boolean)
}

/** 归一化：去空白/全半角统一/小写（对中文无影响，兼容英文唤醒词）+ 剥离前置语气词
 *  ("嗯/哎/呃/这个/那个/so/um/uh/er/well")，让"嗯你好小D"也能命中唤醒词"你好小D"。 */
export function normalizeWake(text: string): string {
  return String(text ?? '')
    .replace(/[\s\u3000]+/g, '')
    .toLowerCase()
    .replace(/[，。！？!?；;、,.]/g, '')
    .replace(/^(嗯+|哎+|呃+|这个+|那个+|so|um|uh|er|well)[，。！？!?；;、,.\s\u3000]*/, '')
}

/** 带提前退出的 Levenshtein 编辑距离（行最小值超 max 即返回 max+1，慢路径专用）。 */
function editDistanceWithin(a: string, b: string, max: number): number {
  const la = a.length
  const lb = b.length
  if (Math.abs(la - lb) > max) return max + 1
  let prev = new Array<number>(lb + 1)
  let cur = new Array<number>(lb + 1)
  for (let j = 0; j <= lb; j++) prev[j] = j
  for (let i = 1; i <= la; i++) {
    cur[0] = i
    let rowMin = cur[0]
    for (let j = 1; j <= lb; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + cost)
      if (cur[j] < rowMin) rowMin = cur[j]
    }
    if (rowMin > max) return max + 1
    const tmp = prev
    prev = cur
    cur = tmp
  }
  return prev[lb]
}

/**
 * 唤醒词在段文本头部占用的**原始字符数**（定稿时剥词头用）。
 * 容错口径与 matchWakeWord 一致（前导语气词剥离 + 编辑距离 ≤ WAKE_MAX_EDITS），
 * 但**要求归一化长度 ≥ 唤醒词全长**——不取「w-1 提前命中」的窗口，否则会把命令
 * 首字一起切掉。找不到（如定稿文本与流式 partial 不一致）返回 0：宁可不剥，也不丢内容。
 */
export function wakePrefixLength(text: string, wakeWord: string): number {
  const w = normalizeWake(wakeWord)
  if (!w || w.length < 2) return 0
  const raw = String(text ?? '')
  for (let i = 1; i <= raw.length; i++) {
    const p = normalizeWake(raw.slice(0, i))
    if (p.length < w.length) continue
    if (p.length > w.length + WAKE_MAX_EDITS) break // 归一化长度单调不减：再长也不可能命中
    if (editDistanceWithin(p, w, WAKE_MAX_EDITS) <= WAKE_MAX_EDITS) return i
  }
  return 0
}

/** 剥掉段文本头部的唤醒词（含前导语气词），再去掉残留的前导空白/标点。
 *  找不到唤醒词时原样返回——**保内容优先**（多留一个词好过丢一句命令）。 */
export function stripWakePrefix(text: string, wakeWord: string): string {
  const n = wakePrefixLength(text, wakeWord)
  const raw = String(text ?? '')
  if (n <= 0) return raw
  return raw.slice(n).replace(/^[\s\u3000，。！？!?；;、,.]+/, '')
}

/**
 * 匹配唤醒词：唤醒词归一化后是候选文本的一个**前缀**（允许前导标点/语气词
 * 被剥离），即候选串去掉尾部多余字后以唤醒词开头 → 命中。
 * 快路径未命中走容错慢路径（前导平移 + 编辑距离；见文件头）。
 * @param partial host 返回的段内累计识别文本（可能带尾字/语气词）。
 * @param wakeWord 配置的唤醒词；空串 = 关闭（永不命中）。
 */
export function matchWakeWord(partial: string, wakeWord: string): boolean {
  const w = normalizeWake(wakeWord)
  if (!w) return false
  const p = normalizeWake(partial)
  if (!p) return false
  if (p.startsWith(w)) return true
  // 候选比唤醒词短（正在说但还没说完）→ 不命中（等下一轮 partial）。
  if (w.length < 2) return false // 单字唤醒词不走容错（1 编辑距离 = 全匹配）
  // 容错慢路径：起点在前 WAKE_LEAD_CHARS 字符内平移（从 0 起——首字被转错时
  // 候选可能与唤醒词等长，起点从 1 起会切不出等长窗口），窗口长度 w±1。
  const maxStart = Math.min(WAKE_LEAD_CHARS, p.length - 1)
  for (let start = 0; start <= maxStart; start++) {
    const available = p.length - start
    const minLen = Math.max(1, w.length - WAKE_MAX_EDITS)
    const maxLen = Math.min(w.length + WAKE_MAX_EDITS, available)
    for (let len = minLen; len <= maxLen; len++) {
      if (len < 2 && w.length >= 2) continue // 单字窗口对 ≥2 字唤醒词过松
      const window = p.slice(start, start + len)
      if (editDistanceWithin(window, w, WAKE_MAX_EDITS) <= WAKE_MAX_EDITS) return true
    }
  }
  return false
}

/**
 * NlmsAec 数值单测（P3-1，纯合成信号，无需浏览器/麦克风）：
 *  1) 回声消除收敛：mic = 0.6 × 延迟参考 + 环境噪声 → 输出中回声分量显著降低；
 *  2) 无参考（静音播放）透传：mic 原样保留（不突变）；
 *  3) 人声保留：mic 含人声 + 回声，参考只有 TTS → 人声分量基本完整。
 */
import assert from 'node:assert/strict'
import { NlmsAec, estimateBulkDelay } from '../src/aec.ts'

let passed = 0
const t = (name, fn) => {
  fn()
  passed++
  console.log(`  ✓ ${name}`)
}

const SAMPLE_RATE = 16000
const DUR = 1.0 // 秒
const N = Math.floor(SAMPLE_RATE * DUR)

/** 确定性伪随机（mulberry32），生成白噪声。 */
function noise(seed) {
  let a = seed >>> 0
  return () => {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/** 能量（均方根）。 */
function rms(x) {
  let s = 0
  for (let i = 0; i < x.length; i++) s += x[i] * x[i]
  return Math.sqrt(s / x.length)
}

t('回声消除：合成回声（0.6×延迟 64 的参考 + 噪声）被显著削弱（收敛后 ≥10dB）', () => {
  const rng = noise(42)
  const ref = new Float32Array(N)
  for (let i = 0; i < N; i++) ref[i] = rng() * 2 - 1
  const mic = new Float32Array(N)
  const D = 64
  for (let i = 0; i < N; i++) {
    mic[i] = (i >= D ? 0.6 * ref[i - D] : 0) + (rng() * 2 - 1) * 0.02
  }
  const aec = new NlmsAec({ delay: 64 })
  const block = 1024
  const out = new Float32Array(N)
  for (let off = 0; off < N; off += block) {
    const m = mic.subarray(off, Math.min(off + block, N))
    const r = ref.subarray(off, Math.min(off + block, N))
    out.set(aec.process(m, r), off)
  }
  const tailMic = mic.subarray(Math.floor(N * 0.6))
  const tailOut = out.subarray(Math.floor(N * 0.6))
  const echoRms = rms(tailMic)
  const outRms = rms(tailOut)
  const db = 20 * Math.log10((outRms + 1e-9) / (echoRms + 1e-9))
  assert.ok(outRms < echoRms * 0.32, `收敛不足: echoRms=${echoRms.toFixed(4)} outRms=${outRms.toFixed(4)} (${db.toFixed(1)}dB)`)
})

t('无参考（未播放 TTS）时透传：输出不突变、能量与输入一致', () => {
  const rng = noise(7)
  const mic = new Float32Array(N)
  for (let i = 0; i < N; i++) mic[i] = (rng() * 2 - 1) * 0.05
  const aec = new NlmsAec()
  const block = 1024
  const out = new Float32Array(N)
  for (let off = 0; off < N; off += block) {
    const m = mic.subarray(off, Math.min(off + block, N))
    out.set(aec.process(m, new Float32Array(0)), off)
  }
  assert.ok(Math.abs(rms(out) - rms(mic)) < rms(mic) * 0.1, '透传后能量偏移过大')
})

t('人声保留：mic 含人声 + 回声，参考仅 TTS → 人声部分不被误消', () => {
  const rng = noise(99)
  const ref = new Float32Array(N)
  for (let i = 0; i < N; i++) ref[i] = rng() * 2 - 1
  const D = 64
  const speech = new Float32Array(N)
  for (let i = 0; i < N; i++) {
    const tSec = i / SAMPLE_RATE
    if (tSec > 0.2 && tSec < 0.8) speech[i] = 0.3 * Math.sin(2 * Math.PI * 440 * (tSec - 0.2))
  }
  const mic = new Float32Array(N)
  for (let i = 0; i < N; i++) {
    mic[i] = (i >= D ? 0.5 * ref[i - D] : 0) + speech[i] + (rng() * 2 - 1) * 0.01
  }
  const aec = new NlmsAec({ delay: 64 })
  const block = 1024
  const out = new Float32Array(N)
  for (let off = 0; off < N; off += block) {
    const m = mic.subarray(off, Math.min(off + block, N))
    const r = ref.subarray(off, Math.min(off + block, N))
    out.set(aec.process(m, r), off)
  }
  const a = Math.floor(SAMPLE_RATE * 0.5)
  const b = Math.floor(SAMPLE_RATE * 0.75)
  const speechRms = rms(speech.subarray(a, b))
  const outSegRms = rms(out.subarray(a, b))
  assert.ok(outSegRms > speechRms * 0.7, `人声被过度消除: speech=${speechRms.toFixed(4)} out=${outSegRms.toFixed(4)}`)
})


t('发散防护：麦大声 + 近零参考反复喂不产 NaN/Inf，且之后仍可收敛', () => {
  const rng = noise(5)
  const N2 = 32000 // 2s
  const ref = new Float32Array(N2)
  for (let i = 0; i < N2; i++) ref[i] = rng() * 2 - 1
  const aec = new NlmsAec({ delay: 64 })
  // 前半段：麦大声、参考近零（最恶劣发散场景）
  const block = 1024
  let hadNaN = false
  for (let off = 0; off < N2 / 2; off += block) {
    const m = new Float32Array(block).fill(1.0)
    const r = new Float32Array(block)
    for (let i = 0; i < block && i < 64; i++) r[i] = 0.001
    const out = aec.process(m, r)
    for (let i = 0; i < out.length; i++) if (!Number.isFinite(out[i])) hadNaN = true
  }
  assert.ok(!hadNaN, '近零参考产生了 NaN/Inf')
  // 后半段：正常回声进入，应仍能收敛（权重未被炸毁）
  for (let off = N2 / 2; off < N2; off += block) {
    const m = new Float32Array(block)
    const r = ref.subarray(off, off + block)
    for (let i = 0; i < block; i++) m[i] = (i - 64 >= 0 ? 0.6 * ref[off + i - 64] : 0) + (rng() * 2 - 1) * 0.02
    aec.process(m, r)
  }
  const out = aec.process(new Float32Array(block).fill(0.5), new Float32Array(block).fill(0.4))
  assert.ok(Number.isFinite(rms(out)), '收敛后输出非有限')
  assert.ok(rms(out) < 0.3, `发散防护后无法再收敛: rms=${rms(out).toFixed(3)}`)
})

t('短路径（耳机 5ms=80 samples）回声被消除——模拟真实 windowAt 预移位语义', () => {
  const rng = noise(5)
  const N = 32000 // 2s
  const ref = new Float32Array(N)
  for (let i = 0; i < N; i++) ref[i] = rng() * 2 - 1
  // mic = 5ms(80 samples) 延迟的回声
  const D = 80
  const mic = new Float32Array(N)
  for (let i = 0; i < N; i++) mic[i] = (i >= D ? 0.6 * ref[i - D] : 0) + (rng() * 2 - 1) * 0.02
  // 真实 client：refWindowAt 归零后，NLMS 在全窗口自适应；这里把 ref 直接喂（同基准对齐即模拟 pre=0）。
  const aec = new NlmsAec({ filterLength: 2560, delay: 0 })
  const block = 1024
  const out = new Float32Array(N)
  for (let off = 0; off < N; off += block) {
    out.set(aec.process(mic.subarray(off, off + block), ref.subarray(off, off + block)), off)
  }
  const a = Math.floor(N * 0.6)
  const echoRms = rms(mic.subarray(a))
  const outRms = rms(out.subarray(a))
  // 期望 10ms 内被显著削弱（合成模型约 11.3dB ≈ ×0.27）
  assert.ok(outRms < echoRms * 0.5, `耳机短路径回声未消除: echo=${echoRms.toFixed(4)} out=${outRms.toFixed(4)}`)
})

t('长路径（外放 120ms=1920 samples）与短路径同一滤波器内共存消除', () => {
  const rng = noise(9)
  const N = 32000
  const ref = new Float32Array(N)
  for (let i = 0; i < N; i++) ref[i] = rng() * 2 - 1
  const D = 1920
  const mic = new Float32Array(N)
  for (let i = 0; i < N; i++) mic[i] = (i >= D ? 0.6 * ref[i - D] : 0) + (rng() * 2 - 1) * 0.02
  const aec = new NlmsAec({ filterLength: 2560, delay: 0 })
  const block = 1024
  const out = new Float32Array(N)
  for (let off = 0; off < N; off += block) {
    out.set(aec.process(mic.subarray(off, off + block), ref.subarray(off, off + block)), off)
  }
  const a = Math.floor(N * 0.6)
  const echoRms = rms(mic.subarray(a))
  const outRms = rms(out.subarray(a))
  assert.ok(outRms < echoRms * 0.5, `长路径回声未消除: echo=${echoRms.toFixed(4)} out=${outRms.toFixed(4)}`)
})

t('bulk delay：检测 80ms 延迟回声（合成，允许下采样误差）', () => {
  const rng = noise(42)
  const N = 16000
  const ref = new Float32Array(N)
  for (let i = 0; i < N; i++) ref[i] = rng() * 2 - 1
  const D = Math.floor(0.08 * SAMPLE_RATE)
  const mic = new Float32Array(N)
  for (let i = 0; i < N; i++) mic[i] = (i >= D ? 0.6 * ref[i - D] : 0) + (rng() * 2 - 1) * 0.01
  const { lag, peak } = estimateBulkDelay(mic, ref, { sampleRate: SAMPLE_RATE })
  assert.ok(Math.abs(lag - D) <= 8, `延迟估计偏差过大: 期望 ${D} 得 ${lag}`)
  assert.ok(peak > 0.5, `峰值过低（无清晰回声）: ${peak.toFixed(3)}`)
})

t('bulk delay：无参考（静音）→ peak=0', () => {
  const rng = noise(7)
  const N = 16000
  const mic = new Float32Array(N)
  for (let i = 0; i < N; i++) mic[i] = rng() * 2 - 1
  const { lag, peak } = estimateBulkDelay(mic, new Float32Array(N), { sampleRate: SAMPLE_RATE })
  assert.equal(peak, 0)
  assert.equal(lag, 0)
})

t('bulk delay：无回声（mic/ref 不相关）→ peak 低', () => {
  const r1 = noise(1)
  const r2 = noise(2)
  const N = 16000
  const mic = new Float32Array(N)
  const ref = new Float32Array(N)
  for (let i = 0; i < N; i++) {
    mic[i] = r1() * 2 - 1
    ref[i] = r2() * 2 - 1
  }
  const { peak } = estimateBulkDelay(mic, ref, { sampleRate: SAMPLE_RATE })
  assert.ok(peak < 0.3, `不相关信号峰值应低: ${peak.toFixed(3)}`)
})

t('双讲冻结：frozen 时权重不更新（回声不被消除，输出≈输入）', () => {
  const rng = noise(42)
  const N = 32000
  const ref = new Float32Array(N)
  for (let i = 0; i < N; i++) ref[i] = rng() * 2 - 1
  const D = 64
  const mic = new Float32Array(N)
  for (let i = 0; i < N; i++) mic[i] = (i >= D ? 0.6 * ref[i - D] : 0) + (rng() * 2 - 1) * 0.02
  const aec = new NlmsAec({ delay: 64 })
  aec.setFrozen(true)
  const block = 1024
  const out = new Float32Array(N)
  for (let off = 0; off < N; off += block) {
    out.set(aec.process(mic.subarray(off, off + block), ref.subarray(off, off + block)), off)
  }
  const a = Math.floor(N * 0.6)
  assert.ok(
    rms(out.subarray(a)) > rms(mic.subarray(a)) * 0.7,
    `frozen 时不应消除回声: out=${rms(out.subarray(a)).toFixed(4)} mic=${rms(mic.subarray(a)).toFixed(4)}`,
  )
})

