 *   runtimeBargeInMode 初始 = config.bargeInMode ?? 'auto'；detect 时按 aecOn 落 auto/manual。
 */
const resolveBargeInMode = (setting, aecOn) => {
  let runtime = setting ?? 'auto'
  if (setting === 'detect') {
    runtime = aecOn ? 'auto' : 'manual'
  }
  return runtime
}

