cfgForCb.onBackchannel = new Function('cfg', 'bus', `
  return cfg.backchannelYield
    ? () => {
        bus.skipAudio();
        bus.setBackchannelHold(Date.now() + (cfg.yieldMs ?? 1500));
      }
    : undefined;
`)(cfgForCb, mockBus)

