    echoGateDb: typeof c.echoGateDb === 'number' ? Math.min(12, Math.max(3, c.echoGateDb)) : 6,
    shortcut: typeof c.shortcut === 'string' ? c.shortcut : '',
    wakeWord: typeof c.wakeWord === 'string' ? c.wakeWord : '',
    toolBeep: c.toolBeep === true,
