"""Deterministic projection into entity-local and relationship evidence.

The functions in this module only reshape sourced facts.  They do not classify
behaviour as malicious, choose a verdict, or infer whether an action succeeded.
"""

from __future__ import annotations

import hashlib
import json
from collections import defaultdict
from typing import Any, Iterable, Mapping

from fusion_pipeline import parse_datetime_utc


MAX_TEXT_CHARS = 1024


def _mapping(value: Any) -> Mapping[str, Any]:
    return value if isinstance(value, Mapping) else {}


def _list(value: Any) -> list[Any]:
    return value if isinstance(value, list) else []


def _nonempty(value: Any) -> bool:
    return value not in (None, "", [], {})


def _text(value: Any) -> str | None:
    if value in (None, ""):
        return None
    return str(value).strip() or None


def _bounded(value: Any) -> str | None:
    text = _text(value)
    if text is None or len(text) <= MAX_TEXT_CHARS:
        return text
    digest = hashlib.sha256(text.encode("utf-8")).hexdigest()[:16]
    marker = f" ...[TRUNCATED sha256={digest} chars={len(text)}]... "
    return text[: MAX_TEXT_CHARS - len(marker) - 128] + marker + text[-128:]


def _sparse(value: Any) -> Any:
    if isinstance(value, Mapping):
        compact = {str(key): _sparse(item) for key, item in value.items()}
        return {key: item for key, item in compact.items() if _nonempty(item)}
    if isinstance(value, list):
        compact = [_sparse(item) for item in value]
        return [item for item in compact if _nonempty(item)]
    return value


def _first(*values: Any) -> Any:
    for value in values:
        if _nonempty(value):
            return value
    return None


def _stable(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, default=str)


def _sorted_unique(values: Iterable[Any]) -> list[str]:
    return sorted({str(value) for value in values if value not in (None, "")})


def build_judgement_target(
    incident: Mapping[str, Any], reasoning_rule: Mapping[str, Any] | None
) -> dict[str, Any]:
    """Freeze the declared incident claim without interpreting evidence."""

    claim_type = _first(
        incident.get("incidentType"),
        incident.get("incident_type"),
        incident.get("title"),
        incident.get("name"),
    )
    if not claim_type:
        raise ValueError("incident has no declared threat type")
    rule = _mapping(reasoning_rule)
    rule_id = _first(
        rule.get("ruleId"),
        rule.get("rule_id"),
        incident.get("reasoningRuleId"),
        incident.get("reasoning_rule_id"),
        incident.get("ruleId"),
    )
    anchor_rule = _sparse(
        {
            "id": str(rule_id) if rule_id is not None else None,
            "name": rule.get("name"),
            "description": rule.get("description"),
        }
    )
    result: dict[str, Any] = {
        "claim_family": "incident_declared_threat",
        "claim_type": str(claim_type),
        "target_source": (
            "incident.incidentType"
            if incident.get("incidentType") not in (None, "")
            else "incident.metadata"
        ),
    }
    if anchor_rule:
        result["anchor_rule"] = anchor_rule
    return result


def build_anchor_search_targets(
    entities: Iterable[Mapping[str, Any]],
) -> list[dict[str, str]]:
    """Return primary and time-bound alias lookups for every explicit anchor."""

    result: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for entity in entities:
        if entity.get("role") != "anchor":
            continue
        entity_ref = _text(entity.get("entity_ref"))
        kind = _text(entity.get("entity_type"))
        if not entity_ref or not kind:
            continue
        candidates: list[tuple[str, str]] = []
        if kind == "asset" and _text(entity.get("asset_id")):
            candidates.append(
                ("ocsf.device.asset.uid.keyword", str(entity["asset_id"]))
            )
            for alias in _list(entity.get("aliases")):
                current = _mapping(alias)
                alias_type = _text(current.get("type"))
                alias_value = _text(current.get("value"))
                if alias_type == "ip" and alias_value:
                    candidates.append(("ocsf.device.ip.keyword", alias_value))
                elif alias_type == "hostname" and alias_value:
                    candidates.append(("ocsf.device.hostname.keyword", alias_value))
        elif kind == "ip" and _text(entity.get("value")):
            candidates.append(("ocsf.device.ip.keyword", str(entity["value"])))
        elif kind == "hostname" and _text(entity.get("value")):
            candidates.append(("ocsf.device.hostname.keyword", str(entity["value"])))
        elif kind == "user" and _text(entity.get("value")):
            candidates.append(("ocsf.actor.user.name.keyword", str(entity["value"])))
        for field, value in candidates:
            if (field, value) in seen:
                continue
            seen.add((field, value))
            result.append({"entity_ref": entity_ref, "field": field, "value": value})
    return result


def select_endpoint_pairs(
    records: Iterable[Mapping[str, Any]],
    *,
    anchor_refs: set[str],
    max_pairs: int,
) -> list[dict[str, Any]]:
    """Select distinct observed endpoint pairs connected to an anchor."""

    groups: dict[tuple[str, str], dict[str, Any]] = {}
    for record in records:
        source_ip = _text(record.get("source_ip"))
        destination_ip = _text(record.get("destination_ip"))
        refs = {
            str(value)
            for value in _list(record.get("entity_refs"))
            if value not in (None, "")
        }
        for field in ("source_entity_ref", "destination_entity_ref", "entity_ref"):
            if record.get(field):
                refs.add(str(record[field]))
        if not source_ip or not destination_ip or not refs.intersection(anchor_refs):
            continue
        key = (source_ip, destination_ip)
        group = groups.setdefault(
            key,
            {
                "source_ip": source_ip,
                "destination_ip": destination_ip,
                "destination_ports": set(),
                "protocols": set(),
                "entity_refs": set(),
                "observation_count": 0,
                "event_rows": [],
            },
        )
        if record.get("destination_port") not in (None, ""):
            group["destination_ports"].add(record["destination_port"])
        if protocol := _text(record.get("protocol")):
            group["protocols"].add(protocol)
        group["entity_refs"].update(refs)
        group["observation_count"] += 1
        if record.get("event_time") not in (None, ""):
            group["event_rows"].append({"event_time": record["event_time"]})
    ranked = sorted(
        groups.values(),
        key=lambda row: (
            -len(set(row["entity_refs"]) & anchor_refs),
            -int(row["observation_count"]),
            str(row["source_ip"]),
            str(row["destination_ip"]),
        ),
    )[: max(0, max_pairs)]
    return [
        {
            **{
                key: value
                for key, value in row.items()
                if key
                not in {
                    "destination_ports",
                    "protocols",
                    "entity_refs",
                    "event_rows",
                }
            },
            "destination_ports": sorted(row["destination_ports"], key=str),
            "protocols": sorted(row["protocols"], key=str),
            "entity_refs": sorted(row["entity_refs"]),
            "time_range": _time_bounds(row["event_rows"]),
        }
        for row in ranked
    ]


def _time_bounds(rows: Iterable[Mapping[str, Any]]) -> list[str]:
    values = sorted(
        parsed
        for parsed in (parse_datetime_utc(row.get("event_time")) for row in rows)
        if parsed is not None
    )
    if not values:
        return []
    return [
        values[0].isoformat().replace("+00:00", "Z"),
        values[-1].isoformat().replace("+00:00", "Z"),
    ]


def _provenance(row: Mapping[str, Any]) -> dict[str, Any]:
    return _sparse(
        {
            "sources": _sorted_unique([row.get("source")]),
            "alert_ids": _sorted_unique(_list(row.get("alert_ids"))),
            "rule_ids": _sorted_unique(_list(row.get("rule_ids"))),
            "sample_record_ids": _sorted_unique([row.get("record_key")])[:3],
        }
    )


def _aggregate(rows: Iterable[dict[str, Any]], signature_fields: tuple[str, ...]) -> list[dict[str, Any]]:
    groups: dict[str, dict[str, Any]] = {}
    for row in rows:
        signature = {field: row.get(field) for field in signature_fields}
        key = _stable(signature)
        current = groups.get(key)
        if current is None:
            current = dict(row)
            current["count"] = 1
            current["first_seen"] = row.get("event_time")
            current["last_seen"] = row.get("event_time")
            current.pop("event_time", None)
            groups[key] = current
            continue
        current["count"] += 1
        times = [value for value in (current.get("first_seen"), row.get("event_time")) if value]
        if times:
            current["first_seen"] = min(times)
        times = [value for value in (current.get("last_seen"), row.get("event_time")) if value]
        if times:
            current["last_seen"] = max(times)
        for name in ("sources", "alert_ids", "rule_ids", "sample_record_ids", "process_uids"):
            current[name] = _sorted_unique([*_list(current.get(name)), *_list(row.get(name))])
            if name == "sample_record_ids":
                current[name] = current[name][:3]
            if name == "process_uids":
                current[name] = current[name][:3]
    for current in groups.values():
        alert_ids = _sorted_unique(_list(current.get("alert_ids")))
        rule_ids = _sorted_unique(_list(current.get("rule_ids")))
        current["alert_id_count"] = len(alert_ids)
        current["rule_id_count"] = len(rule_ids)
        current["alert_ids"] = alert_ids[:3]
        current["rule_ids"] = rule_ids[:5]
        current["sources"] = _sorted_unique(_list(current.get("sources")))[:3]
    return sorted(
        (_sparse(row) for row in groups.values()),
        key=lambda row: (str(row.get("first_seen") or ""), _stable(row)),
    )


def _compact_process_activity(row: Mapping[str, Any]) -> dict[str, Any]:
    parent = _mapping(row.get("parent"))
    return _sparse(
        {
            "image": row.get("image"),
            "cmdline": row.get("cmdline"),
            "user": row.get("user"),
            "parent": {
                "image": parent.get("image"),
                "cmdline": parent.get("cmdline"),
                "process_uid": parent.get("process_uid"),
                "pid": parent.get("pid"),
            },
            "process_uids": row.get("process_uids"),
            "pid": row.get("pid"),
            "native_result": row.get("native_result"),
            "action": row.get("action"),
            "count": row.get("count"),
            "first_seen": row.get("first_seen"),
            "last_seen": row.get("last_seen"),
            "sources": row.get("sources"),
            "alert_ids": row.get("alert_ids"),
            "rule_ids": row.get("rule_ids"),
            "sample_record_ids": row.get("sample_record_ids"),
            "alert_id_count": row.get("alert_id_count"),
            "rule_id_count": row.get("rule_id_count"),
        }
    )


def _project_entity_records(records: list[Mapping[str, Any]]) -> dict[str, list[dict[str, Any]]]:
    process_rows: list[dict[str, Any]] = []
    file_rows: list[dict[str, Any]] = []
    network_rows: list[dict[str, Any]] = []
    auth_rows: list[dict[str, Any]] = []
    other_rows: list[dict[str, Any]] = []
    for record in records:
        provenance = _provenance(record)
        process = _mapping(record.get("process"))
        parent = _mapping(process.get("parent"))
        has_process = any(
            _nonempty(process.get(field))
            for field in ("uid", "pid", "name", "path", "cmdline")
        )
        if has_process:
            process_rows.append(
                _sparse(
                    {
                        "image": _first(process.get("path"), process.get("name")),
                        "cmdline": _bounded(process.get("cmdline")),
                        "user": _mapping(record.get("user")).get("name"),
                        "parent": {
                            "image": _first(parent.get("path"), parent.get("name")),
                            "cmdline": _bounded(parent.get("cmdline")),
                            "process_uid": parent.get("uid"),
                            "pid": parent.get("pid"),
                        },
                        "process_uids": _sorted_unique([process.get("uid")]),
                        "pid": process.get("pid"),
                        "native_result": record.get("native_result"),
                        "action": (
                            record.get("alert_type")
                            if record.get("record_origin") == "anchor_event_search"
                            else record.get("event_type")
                        ),
                        "event_time": record.get("event_time"),
                        **provenance,
                    }
                )
            )
        for operation in _list(record.get("file_operations")):
            current = _mapping(operation)
            if not current:
                continue
            file_rows.append(
                _sparse(
                    {
                        "path": _bounded(current.get("path")),
                        "operation": current.get("operation"),
                        "hashes": _sorted_unique(_list(current.get("hashes"))),
                        "process_uid": process.get("uid"),
                        "process_image": _first(process.get("path"), process.get("name")),
                        "event_time": record.get("event_time"),
                        **provenance,
                    }
                )
            )
        has_network = any(
            _nonempty(record.get(field))
            for field in ("source_ip", "destination_ip", "source_port", "destination_port")
        )
        if has_network:
            network_rows.append(
                _sparse(
                    {
                        "source_ip": record.get("source_ip"),
                        "source_port": record.get("source_port"),
                        "destination_ip": record.get("destination_ip"),
                        "destination_port": record.get("destination_port"),
                        "protocol": record.get("protocol"),
                        "network_session_id": record.get("network_session_id"),
                        "disposition": record.get("disposition"),
                        "process_uid": process.get("uid"),
                        "process_image": _first(process.get("path"), process.get("name")),
                        "event_time": record.get("event_time"),
                        **provenance,
                    }
                )
            )
        has_auth = bool(record.get("authentication_session_id") or record.get("native_result"))
        if has_auth:
            auth_rows.append(
                _sparse(
                    {
                        "user": _mapping(record.get("user")).get("name"),
                        "session_id": record.get("authentication_session_id"),
                        "result": record.get("native_result"),
                        "source_ip": record.get("source_ip"),
                        "destination_ip": record.get("destination_ip"),
                        "event_type": record.get("alert_type") or record.get("event_type"),
                        "event_time": record.get("event_time"),
                        **provenance,
                    }
                )
            )
        if not (has_process or _list(record.get("file_operations")) or has_network or has_auth):
            other_rows.append(
                _sparse(
                    {
                        "event_type": record.get("alert_type") or record.get("event_type"),
                        "request_path": _bounded(record.get("request_path")),
                        "disposition": record.get("disposition"),
                        "event_time": record.get("event_time"),
                        **provenance,
                    }
                )
            )
    return {
        "process_activities": [
            _compact_process_activity(row)
            for row in _aggregate(
                process_rows,
                ("image", "cmdline", "user", "parent", "native_result", "action"),
            )
        ],
        "file_operations": _aggregate(
            file_rows, ("path", "operation", "hashes", "process_image")
        ),
        "network_details": _aggregate(
            network_rows,
            (
                "source_ip",
                "source_port",
                "destination_ip",
                "destination_port",
                "protocol",
                "network_session_id",
                "disposition",
                "process_image",
            ),
        ),
        "authentication_activities": _aggregate(
            auth_rows,
            ("user", "session_id", "result", "source_ip", "destination_ip", "event_type"),
        ),
        "other_activities": _aggregate(
            other_rows, ("event_type", "request_path", "disposition")
        ),
    }


def project_edr_domain(
    entities: Iterable[Mapping[str, Any]], records: Iterable[Mapping[str, Any]]
) -> dict[str, Any]:
    by_entity: dict[str, list[Mapping[str, Any]]] = defaultdict(list)
    for record in records:
        if record.get("entity_ref"):
            by_entity[str(record["entity_ref"])].append(record)
    result: list[dict[str, Any]] = []
    for entity in entities:
        entity_ref = str(entity.get("entity_ref"))
        rows = by_entity.get(entity_ref, [])
        segments: list[dict[str, Any]] = []
        if rows:
            segment = {
                "segment_id": f"{entity_ref}-SEG-001",
                "scope": "anchor_entity" if entity.get("role") == "anchor" else "related_entity",
                "time_range": _time_bounds(rows),
                **_project_entity_records(rows),
            }
            segments.append(segment)
        result.append(
            _sparse(
                {
                    "entity_ref": entity_ref,
                    "asset_id": entity.get("asset_id"),
                    "activity_segments": segments,
                }
            )
        )
        result[-1].setdefault("activity_segments", [])
    return {"entities": result}


def _topology_neighbors(topology: Mapping[str, Any]) -> list[Mapping[str, Any]]:
    value = _first(topology.get("neighbors"), topology.get("relatedAssets"), [])
    return [row for row in _list(value) if isinstance(row, Mapping)]


def _endpoint_entity_index(
    entities: Iterable[Mapping[str, Any]],
) -> dict[str, dict[str, Any]]:
    candidates: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for entity in entities:
        entity_ref = _text(entity.get("entity_ref"))
        if not entity_ref:
            continue
        hostname = None
        ips: set[str] = set()
        if entity.get("entity_type") == "ip" and (value := _text(entity.get("value"))):
            ips.add(value)
        for alias in _list(entity.get("aliases")):
            current = _mapping(alias)
            if current.get("type") == "ip" and (value := _text(current.get("value"))):
                ips.add(value)
            elif current.get("type") == "hostname" and not hostname:
                hostname = _text(current.get("value"))
        descriptor = _sparse(
            {
                "ref": entity_ref,
                "asset_id": entity.get("asset_id"),
                "host": hostname,
                "role": entity.get("role"),
                "entity_type": entity.get("entity_type"),
            }
        )
        for ip in ips:
            candidates[ip].append(descriptor)
    result: dict[str, dict[str, Any]] = {}
    for ip, rows in candidates.items():
        result[ip] = sorted(
            rows,
            key=lambda row: (
                row.get("role") != "anchor",
                row.get("entity_type") != "asset",
                str(row.get("ref") or ""),
            ),
        )[0]
    return result


def _path_hints(
    endpoint_pairs: Iterable[Mapping[str, Any]],
    entities: Iterable[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    endpoint_index = _endpoint_entity_index(entities)
    result: list[dict[str, Any]] = []
    for pair in endpoint_pairs:
        source_ip = _text(pair.get("source_ip"))
        destination_ip = _text(pair.get("destination_ip"))
        if not source_ip or not destination_ip:
            continue
        source = endpoint_index.get(source_ip, {})
        destination = endpoint_index.get(destination_ip, {})
        result.append(
            _sparse(
                {
                    "src_ref": source.get("ref"),
                    "src_asset_id": source.get("asset_id"),
                    "src_host": source.get("host"),
                    "src_ip": source_ip,
                    "dst_ref": destination.get("ref"),
                    "dst_asset_id": destination.get("asset_id"),
                    "dst_host": destination.get("host"),
                    "dst_ip": destination_ip,
                    "protocols": pair.get("protocols"),
                    "dst_ports": pair.get("destination_ports"),
                    "count": pair.get("observation_count"),
                    "time_range": pair.get("time_range"),
                    "basis": "event",
                }
            )
        )
    return result[:100]


def _ids_probe_alerts(records: list[Mapping[str, Any]]) -> list[dict[str, Any]]:
    groups: dict[str, dict[str, Any]] = {}
    for record in records:
        if record.get("record_origin") != "contributing_alert":
            continue
        signature = {
            "source": record.get("source"),
            "event_type": record.get("alert_type") or record.get("event_type"),
            "source_ip": record.get("source_ip"),
            "destination_ip": record.get("destination_ip"),
            "destination_port": record.get("destination_port"),
            "disposition": record.get("disposition"),
        }
        key = _stable(signature)
        current = groups.setdefault(
            key,
            {
                **_sparse(signature),
                "count": 0,
                "first_seen": record.get("event_time"),
                "last_seen": record.get("event_time"),
                "alert_ids": [],
                "rule_ids": [],
                "entity_refs": [],
            },
        )
        current["count"] += 1
        current["first_seen"] = min(
            [value for value in (current.get("first_seen"), record.get("event_time")) if value],
            default=None,
        )
        current["last_seen"] = max(
            [value for value in (current.get("last_seen"), record.get("event_time")) if value],
            default=None,
        )
        current["alert_ids"] = _sorted_unique(
            [*current["alert_ids"], *_list(record.get("alert_ids"))]
        )
        current["rule_ids"] = _sorted_unique(
            [*current["rule_ids"], *_list(record.get("rule_ids"))]
        )
        current["entity_refs"] = _sorted_unique(
            [*current["entity_refs"], *_list(record.get("entity_refs"))]
        )
    for current in groups.values():
        alert_ids = _sorted_unique(_list(current.get("alert_ids")))
        rule_ids = _sorted_unique(_list(current.get("rule_ids")))
        current["alert_id_count"] = len(alert_ids)
        current["rule_id_count"] = len(rule_ids)
        current["alert_ids"] = alert_ids[:3]
        current["rule_ids"] = rule_ids[:5]
    return sorted(
        (_sparse(row) for row in groups.values()),
        key=lambda row: (str(row.get("first_seen") or ""), _stable(row)),
    )[:100]


def project_graph_domain(
    *,
    entities: Iterable[Mapping[str, Any]],
    records: Iterable[Mapping[str, Any]],
    endpoint_pairs: Iterable[Mapping[str, Any]],
    topology_by_entity: Mapping[str, Mapping[str, Any]],
    account_rows: Iterable[Mapping[str, Any]],
    login_sequences: Iterable[Mapping[str, Any]],
    firewall_sessions: Iterable[Mapping[str, Any]],
) -> dict[str, Any]:
    entity_rows = [dict(row) for row in entities]
    record_rows = [dict(row) for row in records]
    related_hosts: list[dict[str, Any]] = []
    endpoint_pair_rows = [dict(row) for row in endpoint_pairs]
    topology_summary: list[dict[str, Any]] = []
    for entity_ref in sorted(topology_by_entity):
        topology = _mapping(topology_by_entity[entity_ref])
        neighbors = _topology_neighbors(topology)
        for neighbor in neighbors[:100]:
            related_hosts.append(
                _sparse(
                    {
                        "entity_ref": entity_ref,
                        "asset_id": _first(neighbor.get("assetId"), neighbor.get("asset_id")),
                        "hostname": neighbor.get("hostname"),
                        "ip": neighbor.get("ip"),
                        "direction": neighbor.get("direction"),
                    }
                )
            )
        blast = _mapping(topology.get("blastRadius"))
        topology_summary.append(
            _sparse(
                {
                    "entity_ref": entity_ref,
                    "asset_in_graph": topology.get("assetInGraph"),
                    "neighbor_count": _first(topology.get("neighborCount"), len(neighbors)),
                    "neighbors_truncated": topology.get("neighborsTruncated"),
                    "graph_stale": topology.get("graphStale"),
                    "reachable_asset_count": blast.get("reachableAssetCount"),
                    "reachable_truncated": blast.get("reachableTruncated"),
                }
            )
        )

    related_users: list[dict[str, Any]] = []
    for wrapper in account_rows:
        entity_ref = wrapper.get("entity_ref")
        for account in _list(wrapper.get("accounts")):
            if not isinstance(account, Mapping):
                continue
            related_users.append(
                _sparse(
                    {
                        "entity_ref": entity_ref,
                        "name": _first(
                            account.get("name"),
                            account.get("account"),
                            account.get("username"),
                        ),
                        "privilege": account.get("privilege"),
                        "role": account.get("role"),
                    }
                )
            )

    related_hosts = list(
        {
            _stable(row): row
            for row in related_hosts
            if row
        }.values()
    )
    related_users = list(
        {
            _stable(row): row
            for row in related_users
            if row
        }.values()
    )

    return {
        "related_hosts": related_hosts,
        "related_users": related_users[:100],
        "connection_history": [],
        "firewall_sessions": [dict(row) for row in firewall_sessions],
        "ids_probe_alerts": _ids_probe_alerts(record_rows),
        "trust_info": None,
        "path_hints": _path_hints(endpoint_pair_rows, entity_rows),
        "asset_group": [
            _sparse(
                {
                    "entity_ref": entity.get("entity_ref"),
                    "asset_id": entity.get("asset_id"),
                    "business_systems": _mapping(
                        topology_by_entity.get(str(entity.get("entity_ref")), {})
                    ).get("sameBizAssets"),
                }
            )
            for entity in entity_rows
            if entity.get("entity_type") == "asset"
        ],
        "cross_device_corroboration": [],
        "topology_summary": topology_summary,
        "login_sequence": [dict(row) for row in login_sequences],
    }


def project_asset_domain(
    entities: Iterable[Mapping[str, Any]],
    asset_context_by_entity: Mapping[str, Mapping[str, Any]],
) -> dict[str, Any]:
    result: list[dict[str, Any]] = []
    for entity in entities:
        entity_ref = str(entity.get("entity_ref"))
        if entity.get("entity_type") != "asset":
            continue
        wrapper = _mapping(asset_context_by_entity.get(entity_ref))
        detail = _mapping(wrapper.get("detail"))
        importance = _mapping(wrapper.get("importance"))
        bindings = [row for row in _list(wrapper.get("bindings")) if isinstance(row, Mapping)]
        tags = []
        raw_tags = detail.get("tagsJson")
        if isinstance(raw_tags, str):
            try:
                raw_tags = json.loads(raw_tags)
            except json.JSONDecodeError:
                raw_tags = [raw_tags]
        tags.extend(_list(raw_tags))
        if detail.get("assetType"):
            tags.append(detail["assetType"])
        tags.extend(
            f"collector:{row['deviceType']}"
            for row in bindings
            if row.get("deviceType")
        )
        criticality = importance.get("importance")
        if criticality in (None, "", "unknown"):
            criticality = None
        result.append(
            _sparse(
                {
                    "entity_ref": entity_ref,
                    "asset_id": entity.get("asset_id"),
                    "hostname": _first(detail.get("hostname"), detail.get("hostName")),
                    "ip": _first(detail.get("ip"), detail.get("ipAddress")),
                    "asset_criticality": criticality,
                    "asset_owner": _first(detail.get("opsOwnerName"), detail.get("ownerName")),
                    "business_system": wrapper.get("business_system"),
                    "exposure": _first(detail.get("exposure"), detail.get("internetExposed")),
                    "tags": _sorted_unique(tags),
                    "maintenance_window": detail.get("maintenanceWindow"),
                    "collectors": bindings,
                }
            )
        )
    return {"entities": result}


def project_threat_intel_domain(
    indicators: Iterable[Mapping[str, Any]],
    intelligence_by_value: Mapping[str, Mapping[str, Any]],
) -> dict[str, Any]:
    result: list[dict[str, Any]] = []
    for indicator in indicators:
        value = _text(indicator.get("value"))
        if not value:
            continue
        intelligence = _mapping(intelligence_by_value.get(value))
        matches = _list(intelligence.get("matches"))
        queried = intelligence.get("queried") is True
        row: dict[str, Any] = {
            "indicator_type": indicator.get("indicator_type"),
            "value": value,
            "entity_refs": _sorted_unique(_list(indicator.get("entity_refs"))),
            "intel_hit": bool(matches) if queried else None,
        }
        if matches:
            row["matches"] = matches
        result.append(_sparse(row))
    return {"indicators": result}


def _login_text(value: Any) -> str | None:
    """登录聚合保留原始空白，避免改变已有分组键。"""
    return str(value) if _nonempty(value) else None


def compact_login_sequences(
    account_sequences: Iterable[Mapping[str, Any]],
    *,
    max_rows: int = 100,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Aggregate login observations by account and endpoint relation.

    The graph MCP may return hundreds of timestamp-only repetitions for the
    same account and host pair.  Keeping every repetition adds no relation
    information, so the fusion layer retains the relation, its time boundary,
    and its count.  No login success or attack meaning is inferred here.
    """

    groups: dict[tuple[Any, ...], dict[str, Any]] = {}
    input_count = 0
    for wrapper in account_sequences:
        fallback_account = _login_text(wrapper.get("account"))
        sequence = wrapper.get("sequence")
        if isinstance(sequence, Mapping):
            rows = sequence.get("items") or sequence.get("records") or []
        else:
            rows = sequence or []
        if not isinstance(rows, list):
            continue
        for source in rows:
            if not isinstance(source, Mapping):
                continue
            input_count += 1
            account = _login_text(source.get("account")) or fallback_account
            source_ip = _login_text(source.get("srcIp") or source.get("source_ip"))
            destination_ip = _login_text(source.get("dstIp") or source.get("destination_ip"))
            destination_host = _login_text(
                source.get("dstHost") or source.get("destination_host")
            )
            destination_port = source.get("dstPort")
            if destination_port is None:
                destination_port = source.get("destination_port")
            timestamp = source.get("tsEpochMs")
            if timestamp is None:
                timestamp = source.get("timestamp_epoch_ms")
            signature = (
                account,
                source_ip,
                destination_ip,
                destination_host,
                destination_port,
            )
            current = groups.get(signature)
            if current is None:
                groups[signature] = {
                    "account": account,
                    "source_ip": source_ip,
                    "destination_ip": destination_ip,
                    "destination_host": destination_host,
                    "destination_port": destination_port,
                    "first_seen_epoch_ms": timestamp,
                    "last_seen_epoch_ms": timestamp,
                    "occurrence_count": 1,
                }
                continue
            current["occurrence_count"] += 1
            if timestamp is not None:
                if (
                    current["first_seen_epoch_ms"] is None
                    or timestamp < current["first_seen_epoch_ms"]
                ):
                    current["first_seen_epoch_ms"] = timestamp
                if (
                    current["last_seen_epoch_ms"] is None
                    or timestamp > current["last_seen_epoch_ms"]
                ):
                    current["last_seen_epoch_ms"] = timestamp

    values = sorted(
        groups.values(),
        key=lambda row: (
            row.get("first_seen_epoch_ms") is None,
            row.get("first_seen_epoch_ms") or 0,
            str(row),
        ),
    )
    selected = values[:max_rows]
    return selected, {
        "input_count": input_count,
        "unique_count": len(values),
        "output_count": len(selected),
        "truncated": len(values) > len(selected),
        "retention_policy": "earliest_distinct_account_endpoint_relations",
    }

"""五源富化前，使用事件直接证据进行只读名单快速分类。"""
from __future__ import annotations

import ipaddress
import json
import re
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timezone
from urllib.parse import urlsplit, urlunsplit
from zoneinfo import ZoneInfo

from fusion_contract import CallOutcome
from fusion_pipeline import normalize_alert

SUCCESS = {CallOutcome.SUCCESS_WITH_DATA, CallOutcome.SUCCESS_EMPTY}


def normalize_ioc(kind: str, value: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError('empty IOC')
    value = value.strip()
    if kind == 'IP':
        return str(ipaddress.ip_address(value))
    if kind == 'DOMAIN':
        value = value.rstrip('.').encode('idna').decode('ascii').lower()
        if len(value) > 253 or any(not re.fullmatch(r'[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?', part) for part in value.split('.')):
            raise ValueError('invalid domain')
        return value
    if kind == 'URL':
        parts = urlsplit(value)
        if parts.scheme.lower() not in {'http', 'https'} or not parts.hostname or parts.username or parts.password:
            raise ValueError('invalid URL')
        try:
            host = str(ipaddress.ip_address(parts.hostname))
            if ':' in host:
                host = '[' + host + ']'
        except ValueError:
            host = normalize_ioc('DOMAIN', parts.hostname)
        port = parts.port
        authority = host + (f':{port}' if port is not None else '')
        return urlunsplit((parts.scheme.lower(), authority, parts.path, parts.query, parts.fragment))
    if kind == 'HASH':
        if not re.fullmatch(r'(?:[a-fA-F0-9]{32}|[a-fA-F0-9]{40}|[a-fA-F0-9]{64}|[a-fA-F0-9]{128})', value):
            raise ValueError('invalid hash')
        return value.lower()
    if kind in {'ASSET_ID', 'USERNAME'}:
        return value
    raise ValueError('unsupported IOC type')


def _object(value, default):
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            return default
    return value if isinstance(value, type(default)) else default


def extract_indicators(incident, alerts, *, errors=None):
    """只读取有类型的直接字段，不从规则名称或自由文本推断 IOC。"""
    output, seen = [], set()
    errors = errors if errors is not None else []

    def add(kind, value, ref, role=None, rule_id=None):
        if value is None or value == "":
            return
        try:
            normalized = normalize_ioc(kind, str(value))
        except ValueError:
            errors.append(ref)
            return
        row = dict(kind=kind, value=normalized, evidence_ref=ref, role=role, rule_id=rule_id)
        key = (kind, normalized, ref, role, str(rule_id))
        if key not in seen:
            seen.add(key)
            output.append(row)

    fields = {'sourceIp': ('IP', 'SRC_IP'), 'source_ip': ('IP', 'SRC_IP'),
              'attackerIp': ('IP', 'SRC_IP'), 'targetIp': ('IP', 'DEST_IP'),
              'destination_ip': ('IP', 'DEST_IP'), 'destinationIp': ('IP', 'DEST_IP'),
              'affectedAssetId': ('ASSET_ID', 'ASSET_ID'), 'affected_asset_id': ('ASSET_ID', 'ASSET_ID'),
              'domain': ('DOMAIN', None), 'url': ('URL', None),
              'file_hash': ('HASH', None), 'sha256': ('HASH', None), 'md5': ('HASH', None)}
    aliases = {'IP_ADDRESS': 'IP', 'IP': 'IP', 'DOMAIN': 'DOMAIN', 'DOMAIN_NAME': 'DOMAIN',
               'URL': 'URL', 'HASH': 'HASH', 'FILE_HASH': 'HASH', 'ASSET': 'ASSET_ID', 'USER': 'USERNAME'}
    for index, record in enumerate([incident, *alerts]):
        ref = 'incident' if index == 0 else f'alerts[{index-1}]({record.get("alert_id", record.get("id", ""))})'
        rule_id = record.get('rule_id', record.get('ruleId')) if index else None
        for field, (kind, role) in fields.items():
            add(kind, record.get(field), f'{ref}.{field}', role, rule_id)
        entities = _object(record.get('entitiesJson', record.get('entities_json', record.get('entities', []))), [])
        observables = _object(record.get('observables', []), [])
        ocsf = _object(record.get('ocsf', {}), {})
        observables = observables + _object(ocsf.get('observables', []), [])
        for item in entities + observables:
            if not isinstance(item, dict):
                continue
            kind = aliases.get(str(item.get('type', item.get('entityType', item.get('iocType', '')))).upper())
            # 对齐仓库 OCSF 1.8 observable.json：2=IP、6=URL、8=Hash；3 是 MAC。
            kind = kind or {2: 'IP', 6: 'URL', 8: 'HASH'}.get(item.get('type_id'))
            field = str(item.get('field', item.get('name', '')))
            kind = kind or ({'ip': 'IP', 'domain': 'DOMAIN', 'url': 'URL', 'url_string': 'URL',
                             'md5': 'HASH', 'sha1': 'HASH', 'sha256': 'HASH', 'sha512': 'HASH'}.get(field.split('.')[-1]))
            if kind:
                add(kind, item.get('value', item.get('iocValue', item.get('ip', item.get('assetId')))), ref, None, rule_id)
        if index:
            normalized = normalize_alert(record)
            for name, kind, role in [('source_ip', 'IP', 'SRC_IP'), ('destination_ip', 'IP', 'DEST_IP'),
                                     ('affected_asset_id', 'ASSET_ID', 'ASSET_ID')]:
                add(kind, normalized.get(name), ref, role, normalized.get('rule_id'))
            asset = normalized.get('asset') or {}
            add('IP', asset.get('ip'), f'{ref}.ocsf.device.ip', None, rule_id)
            user = normalized.get('user') or {}
            add('USERNAME', user.get('name'), ref, 'USERNAME', rule_id)
            raw = _object(_object(record.get('triggering_event'), {}).get('raw'), {})
            embedded = _object(ocsf.get('raw_data'), {})
            for payload in [raw, embedded]:
                data = _object(payload.get('data'), {})
                win = _object(data.get('win', payload.get('win')), {})
                event_data = _object(win.get('eventdata'), {})
                # Sysmon hashes 是明确的 algorithm=digest 字段。
                hashes = event_data.get('hashes')
                if isinstance(hashes, str):
                    for pair in hashes.split(','):
                        algorithm, separator, digest = pair.partition('=')
                        if separator and algorithm.strip().upper() in {'MD5', 'SHA1', 'SHA256', 'SHA512'}:
                            add('HASH', digest.strip(), ref, None, rule_id)
        nodes = [(ocsf, f'{ref}.ocsf')]
        for n, evidence in enumerate(_object(ocsf.get('evidences', []), [])):
            if isinstance(evidence, dict):
                nodes.append((evidence, f'{ref}.ocsf.evidences[{n}]'))
        for node, path in nodes:
            for endpoint, role in [('src_endpoint', 'SRC_IP'), ('dst_endpoint', 'DEST_IP')]:
                obj = node.get(endpoint, {})
                if isinstance(obj, dict):
                    add('IP', obj.get('ip'), f'{path}.{endpoint}.ip', role, rule_id)
                    add('DOMAIN', obj.get('domain'), f'{path}.{endpoint}.domain', None, rule_id)
            def walk_typed(obj, current):
                if not isinstance(obj, dict):
                    return
                for key, value in obj.items():
                    child = f'{current}.{key}'
                    if key in {'hashes', 'hash'}:
                        for n, hash_row in enumerate(value if isinstance(value, list) else [value]):
                            add('HASH', hash_row.get('value') if isinstance(hash_row, dict) else hash_row, f'{child}[{n}]', None, rule_id)
                    elif key == 'url':
                        add('URL', value.get('url_string') if isinstance(value, dict) else value, child, None, rule_id)
                    elif key == 'domain':
                        add('DOMAIN', value, child, None, rule_id)
                    elif key in {'file', 'process', 'actor', 'http_request', 'dns', 'query'}:
                        walk_typed(value, child)
            walk_typed(node, path)
    return output


def _active(entry, expiry_field, now, list_timezone):
    if entry.get('enabled') not in (True, 1):
        if entry.get('enabled') in (False, 0):
            return False
        raise ValueError('missing or invalid enabled flag')
    expiry = entry.get(expiry_field)
    if expiry:
        end = datetime.fromisoformat(str(expiry).replace('Z', '+00:00'))
        if end.tzinfo is None:
            if not list_timezone:
                raise ValueError('naive expiry requires configured list timezone')
            end = end.replace(tzinfo=ZoneInfo(list_timezone))
        if end <= now:
            return False
    return True


def classify(incident, alerts, whitelist, intel, *, complete, queried_at, now=None, list_timezone=None, audit=None):
    """返回最小结果；返回 None 时沿用完整五源流程。"""
    if audit is None:
        audit = {}
    if not complete:
        audit["reason"] = "incomplete_queries_or_alerts"
        return None
    now = now or datetime.now(timezone.utc)
    errors = []
    indicators = extract_indicators(incident, alerts, errors=errors)
    if errors:
        audit.update(reason="invalid_direct_indicator", invalid_evidence_refs=errors)
        return None
    matches = []
    try:
        for source, rows in [('alert_whitelist', whitelist), ('intel', intel)]:
            for entry in rows:
                if not isinstance(entry, dict):
                    raise ValueError('invalid list entry')
                if not _active(entry, 'expiresAt' if source == 'alert_whitelist' else 'validUntil', now, list_timezone):
                    continue
                actual_source = source
                if source == 'intel':
                    disposition = entry.get('disposition')
                    if disposition == 'INDICATOR':
                        continue
                    actual_source = {'WHITELIST': 'intel_whitelist', 'BLACKLIST': 'intel_blacklist'}.get(disposition)
                    if not actual_source:
                        raise ValueError('unknown disposition')
                entry_id = entry.get('whitelistId') or entry.get('id')
                if entry_id is None:
                    raise ValueError('missing entry ID')
                kind = entry.get('type') if source == 'alert_whitelist' else entry.get('iocType')
                value = entry.get('value') if source == 'alert_whitelist' else entry.get('iocValue')
                scope = entry.get('scopeRuleIds') or []
                if not isinstance(scope, list):
                    raise ValueError('invalid rule scope')
                if kind == 'IP_CIDR':
                    target = ipaddress.ip_network(value, strict=False)
                else:
                    target = normalize_ioc('IP' if kind in {'SRC_IP', 'DEST_IP'} else kind, value)
                grouped = {}
                for indicator in indicators:
                    if scope and str(indicator['rule_id']) not in {str(v) for v in scope}:
                        continue
                    if source == 'alert_whitelist' and kind in {'SRC_IP', 'DEST_IP', 'IP_CIDR'}:
                        if indicator['role'] != ('SRC_IP' if kind == 'IP_CIDR' else kind):
                            continue
                    expected = 'IP' if kind in {'SRC_IP', 'DEST_IP', 'IP_CIDR'} else kind
                    if indicator['kind'] != expected:
                        continue
                    hit = ipaddress.ip_address(indicator['value']) in target if kind == 'IP_CIDR' else indicator['value'] == target
                    if hit:
                        grouped.setdefault(indicator['value'], []).append(indicator['evidence_ref'])
                for entity_value, refs in grouped.items():
                    matches.append(dict(source=actual_source, entry_id=str(entry_id), entity_value=entity_value,
                                        evidence_refs=sorted(set(refs)), list_version=None, queried_at=queried_at))
    except (ValueError, TypeError, KeyError):
        audit["reason"] = "invalid_list_entry_or_unconfigured_expiry_timezone"
        audit["matches"] = matches
        return None
    sides = {m['source'] == 'intel_blacklist' for m in matches}
    audit["matches"] = matches
    audit["reason"] = "conflicting_matches" if len(sides) == 2 else "one_sided_match" if sides else "no_match"
    if len(sides) != 1:
        return None
    return {'verdict': '真实告警' if True in sides else '误报', 'matches': matches}


def collect_lists(runner, *, page_size=200, max_pages=100):
    """并发读取两侧名单；分页未完整读取时禁止提前分类。"""
    queried_at = datetime.now(timezone.utc).isoformat()

    def fetch_white():
        result = runner.call(resource='ai_soc_detect', tool='ai_soc_detect__list_detect_whitelist',
                             purpose='快速分类读取告警白名单', arguments={}, argument_sources={}, domain='fast_classification')
        if result.outcome not in SUCCESS or not isinstance(result.data, list):
            raise ValueError('alert whitelist query incomplete')
        return result.data

    def fetch_intel():
        rows, ids, expected = [], set(), None
        for page in range(1, max_pages + 1):
            result = runner.call(resource='ai_soc_correlate', tool='ai_soc_correlate__get_correlate_threat_intel',
                                 purpose='快速分类完整读取情报名单', arguments={'pageNum': page, 'pageSize': page_size},
                                 argument_sources={'pageNum': 'pagination', 'pageSize': 'bounded list query'}, domain='fast_classification')
            data = result.data
            if result.outcome not in SUCCESS or not isinstance(data, dict) or not isinstance(data.get('rows'), list):
                raise ValueError('threat intel query incomplete')
            total = data.get('total')
            if not isinstance(total, int) or isinstance(total, bool) or total < 0 or (expected is not None and total != expected):
                raise ValueError('invalid or changing pagination total')
            expected = total
            for row in data['rows']:
                if not isinstance(row, dict) or row.get('id') is None or str(row['id']) in ids:
                    raise ValueError('missing or repeated pagination ID')
                ids.add(str(row['id']))
                rows.append(row)
            if len(rows) == total:
                return rows
            if len(rows) > total or not data['rows']:
                raise ValueError('inconsistent pagination')
        raise ValueError('threat intel page limit reached')

    values, errors = {}, []
    with ThreadPoolExecutor(max_workers=2) as pool:
        futures = {name: pool.submit(fn) for name, fn in [('whitelist', fetch_white), ('intel', fetch_intel)]}
        for name, future in futures.items():
            try:
                values[name] = future.result()
            except Exception as exc:
                # 异常文本可能携带凭据或远端响应，仅记录类型。
                errors.append({'source': name, 'error_type': type(exc).__name__})
    return values.get('whitelist', []), values.get('intel', []), {'complete': not errors, 'errors': errors, 'queried_at': queried_at}

"""Validation contract for the multi-anchor five-source output."""

from __future__ import annotations

from enum import Enum
from typing import Any, Mapping


DOMAIN_NAMES = ("graph", "edr_detail", "asset", "threat_intel", "history")
GRAPH_FIELDS = {
    "related_hosts",
    "related_users",
    "connection_history",
    "firewall_sessions",
    "ids_probe_alerts",
    "trust_info",
    "path_hints",
    "asset_group",
    "cross_device_corroboration",
    "topology_summary",
    "login_sequence",
}

MODEL_ENTITY_AUDIT_ONLY_FIELDS = {"aliases", "provenance", "valid_during"}
MODEL_EDR_AUDIT_ONLY_FIELDS = {
    "process_activities",
    "process_uid",
    "process_uids",
    "pid",
    "sources",
    "alert_ids",
    "sample_record_ids",
    "alert_id_count",
    "rule_id_count",
    "first_seen",
    "last_seen",
}


def _mapping(value: Any, name: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise ValueError(f"{name} must be an object")
    return value


def validate_five_source_output(payload: Mapping[str, Any]) -> None:
    snapshot = _mapping(payload.get("event_snapshot"), "event_snapshot")
    target = _mapping(snapshot.get("judgement_target"), "judgement_target")
    if "primary_entity" in target or "peer_entities" in target:
        raise ValueError("primary_entity/peer_entities are forbidden in the entity-based contract")
    for field in ("claim_family", "claim_type", "target_source"):
        if target.get(field) in (None, ""):
            raise ValueError(f"judgement_target.{field} is required")
    time_range = snapshot.get("time_range")
    if not isinstance(time_range, list) or len(time_range) != 2 or not all(time_range):
        raise ValueError("event_snapshot.time_range must contain start and end")
    entities = snapshot.get("entities")
    if not isinstance(entities, list) or not entities:
        raise ValueError("event_snapshot.entities must contain at least one anchor")
    refs = []
    for entity in entities:
        current = _mapping(entity, "event_snapshot.entities[]")
        if current.get("role") not in {"anchor", "related"}:
            raise ValueError("entity role must be anchor or related")
        if not current.get("entity_ref"):
            raise ValueError("entity_ref is required")
        refs.append(str(current["entity_ref"]))
    if len(refs) != len(set(refs)):
        raise ValueError("entity_ref values must be unique")
    if not any(entity.get("role") == "anchor" for entity in entities):
        raise ValueError("at least one anchor entity is required")

    context = _mapping(payload.get("enriched_context"), "enriched_context")
    if set(context) != set(DOMAIN_NAMES):
        raise ValueError(f"enriched_context domains must be exactly {DOMAIN_NAMES}")
    graph = _mapping(context["graph"], "graph")
    missing_graph = GRAPH_FIELDS - set(graph)
    if missing_graph:
        raise ValueError(f"graph missing fields: {sorted(missing_graph)}")
    edr = _mapping(context["edr_detail"], "edr_detail")
    asset = _mapping(context["asset"], "asset")
    intel = _mapping(context["threat_intel"], "threat_intel")
    history = _mapping(context["history"], "history")
    if not isinstance(edr.get("entities"), list):
        raise ValueError("edr_detail.entities must be a list")
    if not isinstance(asset.get("entities"), list):
        raise ValueError("asset.entities must be a list")
    if not isinstance(intel.get("indicators"), list):
        raise ValueError("threat_intel.indicators must be a list")
    if not isinstance(history.get("records"), list):
        raise ValueError("history.records must be a list")
    score = payload.get("data_completeness")
    if not isinstance(score, (int, float)) or not 0 <= float(score) <= 1:
        raise ValueError("data_completeness must be between 0 and 1")


def _reject_audit_only_edr_fields(value: Any, path: str) -> None:
    if isinstance(value, Mapping):
        for key, item in value.items():
            if key in MODEL_EDR_AUDIT_ONLY_FIELDS:
                raise ValueError(f"audit-only field is forbidden in model input: {path}.{key}")
            _reject_audit_only_edr_fields(item, f"{path}.{key}")
    elif isinstance(value, list):
        for index, item in enumerate(value):
            _reject_audit_only_edr_fields(item, f"{path}[{index}]")


def validate_model_input(payload: Mapping[str, Any]) -> None:
    """Validate the compact model projection without weakening the audit contract."""

    validate_five_source_output(payload)
    snapshot = _mapping(payload["event_snapshot"], "event_snapshot")
    entity_refs = {
        str(_mapping(entity, "event_snapshot.entities[]")["entity_ref"])
        for entity in snapshot["entities"]
    }
    for entity in snapshot["entities"]:
        current = _mapping(entity, "event_snapshot.entities[]")
        forbidden = MODEL_ENTITY_AUDIT_ONLY_FIELDS & set(current)
        if forbidden:
            raise ValueError(
                "audit-only entity fields are forbidden in model input: "
                f"{sorted(forbidden)}"
            )

    edr = _mapping(payload["enriched_context"]["edr_detail"], "edr_detail")
    for entity_index, entity in enumerate(edr["entities"]):
        current_entity = _mapping(entity, f"edr_detail.entities[{entity_index}]")
        entity_ref = current_entity.get("entity_ref")
        if str(entity_ref) not in entity_refs:
            raise ValueError(f"unknown EDR entity_ref: {entity_ref}")
        segments = current_entity.get("activity_segments")
        if not isinstance(segments, list):
            raise ValueError("edr_detail activity_segments must be a list")
        for segment_index, segment in enumerate(segments):
            current_segment = _mapping(
                segment,
                f"edr_detail.entities[{entity_index}].activity_segments[{segment_index}]",
            )
            processes = current_segment.get("processes", [])
            if not isinstance(processes, list):
                raise ValueError("processes must be a list")
            process_refs: set[str] = set()
            for process in processes:
                current_process = _mapping(process, "processes[]")
                process_ref = current_process.get("ref")
                if process_ref in (None, ""):
                    raise ValueError("process ref is required")
                process_ref = str(process_ref)
                if process_ref in process_refs:
                    raise ValueError(f"duplicate process ref: {process_ref}")
                process_refs.add(process_ref)
            for process in processes:
                parent_ref = _mapping(process, "processes[]").get("parent_ref")
                if parent_ref not in (None, "") and str(parent_ref) not in process_refs:
                    raise ValueError(f"unknown parent_ref: {parent_ref}")
            for field in ("file_operations", "network_details", "authentication_events", "other_events"):
                rows = current_segment.get(field, [])
                if not isinstance(rows, list):
                    raise ValueError(f"{field} must be a list")
                for row in rows:
                    process_ref = _mapping(row, f"{field}[]").get("process_ref")
                    if process_ref not in (None, "") and str(process_ref) not in process_refs:
                        raise ValueError(f"unknown process_ref: {process_ref}")
        _reject_audit_only_edr_fields(
            current_entity,
            f"edr_detail.entities[{entity_index}]",
        )


SENSITIVE_KEY_PARTS = ("password", "passwd", "token", "secret", "credential")


class CallOutcome(str, Enum):
    SUCCESS_WITH_DATA = "success_with_data"
    SUCCESS_EMPTY = "success_empty"
    TRUNCATED = "truncated"
    FAILED = "failed"
    NOT_QUERIED = "not_queried"


def canonical_tool_name(exact_tool_name: str) -> str:
    return exact_tool_name.rsplit("__", 1)[-1]


def _redact(value: Any) -> Any:
    if isinstance(value, Mapping):
        result: dict[str, Any] = {}
        for key, child in value.items():
            normalized = str(key).lower()
            result[str(key)] = (
                "***REDACTED***"
                if any(part in normalized for part in SENSITIVE_KEY_PARTS)
                else _redact(child)
            )
        return result
    if isinstance(value, list):
        return [_redact(item) for item in value]
    return value


def make_ledger_entry(
    *,
    call_id: str,
    resource: str,
    exact_tool_name: str,
    purpose: str,
    key_arguments: Mapping[str, Any],
    argument_sources: Mapping[str, str],
    outcome: CallOutcome,
    result_count: int | None,
    latency_ms: int,
    output_domain: str,
    raw_response_file: str,
) -> dict[str, Any]:
    """Create a concise user-facing row with exact invocation data in audit."""

    return {
        "call_id": call_id,
        "tool": canonical_tool_name(exact_tool_name),
        "purpose": purpose,
        "key_arguments": _redact(dict(key_arguments)),
        "argument_sources": dict(argument_sources),
        "status": outcome.value,
        "result_count": result_count,
        "latency_ms": latency_ms,
        "output_domain": output_domain,
        "audit": {
            "resource": resource,
            "exact_tool": exact_tool_name,
            "raw_response_file": raw_response_file,
        },
    }

"""Deterministic incident scope and evidence fusion primitives.

This module deliberately performs no threat reasoning.  It freezes the incident
claim, canonicalises explicitly declared entities, links only structurally
related records, removes duplicate source events and applies auditable budgets.
"""

from __future__ import annotations

import copy
import hashlib
import json
from collections import defaultdict, deque
from datetime import datetime, timedelta, timezone
from typing import Any, Iterable, Mapping

from fusion_pipeline import parse_datetime_utc


def _mapping(value: Any) -> Mapping[str, Any]:
    return value if isinstance(value, Mapping) else {}


def _list(value: Any) -> list[Any]:
    return value if isinstance(value, list) else []


def _json(value: Any, fallback: Any) -> Any:
    if not isinstance(value, str):
        return value if value is not None else fallback
    try:
        return json.loads(value)
    except json.JSONDecodeError:
        return fallback


def _text(value: Any) -> str | None:
    if value in (None, ""):
        return None
    return str(value).strip() or None


def _iso(value: datetime) -> str:
    return value.astimezone(timezone.utc).isoformat().replace("+00:00", "Z")


def _first(*values: Any) -> Any:
    for value in values:
        if value not in (None, "", [], {}):
            return value
    return None


def _add_candidate(
    rows: list[dict[str, str]],
    seen: set[tuple[str, str]],
    entity_type: str,
    value: Any,
    provenance: str,
) -> None:
    text = _text(value)
    if not text:
        return
    key = (entity_type, text.casefold() if entity_type in {"hostname", "user"} else text)
    if key in seen:
        return
    seen.add(key)
    rows.append(
        {"entity_type": entity_type, "value": text, "provenance": provenance}
    )


def extract_incident_entities(incident: Mapping[str, Any]) -> list[dict[str, str]]:
    """Extract only entities explicitly declared by the incident object.

    Contributing-alert order and reasoning-chain steps are intentionally absent
    from this function, so they cannot silently choose a single primary host.
    """

    rows: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()
    top_level = (
        ("asset", incident.get("affectedAssetId"), "incident.affectedAssetId"),
        ("asset", incident.get("attackerAssetId"), "incident.attackerAssetId"),
        ("ip", incident.get("sourceIp"), "incident.sourceIp"),
        ("ip", incident.get("targetIp"), "incident.targetIp"),
        ("ip", incident.get("attackerIp"), "incident.attackerIp"),
        ("user", incident.get("account"), "incident.account"),
    )
    for entity_type, value, provenance in top_level:
        _add_candidate(rows, seen, entity_type, value, provenance)

    entities = _json(
        _first(
            incident.get("entitiesJson"),
            incident.get("entities_json"),
            incident.get("entities"),
        ),
        [],
    )
    for index, item in enumerate(_list(entities)):
        current = _mapping(item)
        kind = str(current.get("type") or current.get("entityType") or "").upper()
        provenance = f"incident.entitiesJson[{index}]"
        if kind == "ASSET":
            _add_candidate(
                rows,
                seen,
                "asset",
                _first(current.get("assetId"), current.get("asset_id"), current.get("id")),
                provenance,
            )
        elif kind in {"IP", "IP_ADDRESS"}:
            _add_candidate(
                rows,
                seen,
                "ip",
                _first(current.get("ip"), current.get("value")),
                provenance,
            )
        elif kind in {"HOST", "HOSTNAME"}:
            _add_candidate(
                rows,
                seen,
                "hostname",
                _first(current.get("hostname"), current.get("name"), current.get("value")),
                provenance,
            )
        elif kind in {"USER", "ACCOUNT"}:
            _add_candidate(
                rows,
                seen,
                "user",
                _first(current.get("account"), current.get("username"), current.get("name")),
                provenance,
            )
    return rows


def derive_effective_time_range(
    incident: Mapping[str, Any], records: Iterable[Mapping[str, Any]]
) -> list[str]:
    """Use alert business time, with incident first/last time only as fallback."""

    times = sorted(
        parsed
        for parsed in (parse_datetime_utc(row.get("event_time")) for row in records)
        if parsed is not None
    )
    if times:
        return [_iso(times[0]), _iso(times[-1])]
    start = parse_datetime_utc(
        _first(
            incident.get("firstSeenTime"),
            incident.get("first_seen_time"),
            incident.get("firstSeen"),
        )
    )
    end = parse_datetime_utc(
        _first(
            incident.get("lastSeenTime"),
            incident.get("last_seen_time"),
            incident.get("lastSeen"),
        )
    )
    if start is None or end is None:
        raise ValueError("incident has no valid contributing-alert or incident time range")
    if end < start:
        raise ValueError("incident time range is reversed")
    return [_iso(start), _iso(end)]


def _asset_id(asset: Mapping[str, Any]) -> str | None:
    return _text(_first(asset.get("assetId"), asset.get("asset_id"), asset.get("id")))


def _asset_ip(asset: Mapping[str, Any]) -> str | None:
    return _text(_first(asset.get("ip"), asset.get("ipAddress"), asset.get("ip_address")))


def _asset_hostname(asset: Mapping[str, Any]) -> str | None:
    return _text(
        _first(asset.get("hostname"), asset.get("hostName"), asset.get("host_name"), asset.get("name"))
    )


def canonicalize_entities(
    candidates: Iterable[Mapping[str, Any]],
    asset_records: Iterable[Mapping[str, Any]],
    time_range: list[str],
) -> tuple[list[dict[str, Any]], dict[str, str], dict[str, Any]]:
    """Canonicalise entities with asset ID as the authoritative key.

    An IP/hostname becomes an asset alias only when it maps to exactly one known
    asset.  Ambiguous mappings remain independent entities and are audited.
    """

    candidate_rows = [dict(row) for row in candidates]
    assets_by_id = {
        asset_id: dict(row)
        for row in asset_records
        if (asset_id := _asset_id(row)) is not None
    }
    requested_assets = {
        str(row["value"])
        for row in candidate_rows
        if row.get("entity_type") == "asset" and row.get("value") is not None
    }
    for asset_id in requested_assets:
        assets_by_id.setdefault(asset_id, {"assetId": asset_id})

    ip_to_assets: dict[str, set[str]] = defaultdict(set)
    host_to_assets: dict[str, set[str]] = defaultdict(set)
    for asset_id, asset in assets_by_id.items():
        if ip := _asset_ip(asset):
            ip_to_assets[ip].add(asset_id)
        if hostname := _asset_hostname(asset):
            host_to_assets[hostname.casefold()].add(asset_id)

    provisional: list[dict[str, Any]] = []
    key_to_position: dict[tuple[str, str], int] = {}
    conflicts: list[dict[str, Any]] = []

    for asset_id in sorted(requested_assets, key=lambda value: (not value.isdigit(), value)):
        asset = assets_by_id[asset_id]
        aliases: list[dict[str, Any]] = []
        for alias_type, value in (("ip", _asset_ip(asset)), ("hostname", _asset_hostname(asset))):
            if value:
                aliases.append(
                    {
                        "type": alias_type,
                        "value": value,
                        "valid_during": list(time_range),
                        "provenance": ["asset_lookup"],
                    }
                )
        key_to_position[("asset", asset_id)] = len(provisional)
        provisional.append(
            {
                "entity_type": "asset",
                "role": "anchor",
                "asset_id": asset_id,
                "aliases": aliases,
                "provenance": sorted(
                    {
                        str(row.get("provenance"))
                        for row in candidate_rows
                        if row.get("entity_type") == "asset"
                        and str(row.get("value")) == asset_id
                        and row.get("provenance")
                    }
                ),
            }
        )

    for row in candidate_rows:
        kind = str(row.get("entity_type") or "")
        value = _text(row.get("value"))
        if not value or kind == "asset":
            continue
        mapped_assets: set[str] = set()
        if kind == "ip":
            mapped_assets = ip_to_assets.get(value, set()) & requested_assets
        elif kind == "hostname":
            mapped_assets = host_to_assets.get(value.casefold(), set()) & requested_assets
        if len(mapped_assets) == 1:
            asset_id = next(iter(mapped_assets))
            entity = provisional[key_to_position[("asset", asset_id)]]
            alias_key = (kind, value.casefold() if kind == "hostname" else value)
            existing = {
                (
                    str(alias.get("type")),
                    str(alias.get("value")).casefold()
                    if alias.get("type") == "hostname"
                    else str(alias.get("value")),
                )
                for alias in entity["aliases"]
            }
            if alias_key not in existing:
                entity["aliases"].append(
                    {
                        "type": kind,
                        "value": value,
                        "valid_during": list(time_range),
                        "provenance": [str(row.get("provenance") or "incident")],
                    }
                )
            continue
        if len(mapped_assets) > 1:
            conflicts.append(
                {
                    "key": f"{kind}:{value}",
                    "asset_ids": sorted(mapped_assets),
                    "resolution": "kept_as_independent_anchor",
                }
            )
        normalized = value.casefold() if kind in {"hostname", "user"} else value
        key = (kind, normalized)
        if key in key_to_position:
            continue
        key_to_position[key] = len(provisional)
        provisional.append(
            {
                "entity_type": kind,
                "role": "anchor",
                "value": value,
                "aliases": [],
                "provenance": [str(row.get("provenance") or "incident")],
            }
        )

    def sort_key(entity: Mapping[str, Any]) -> tuple[int, str]:
        kind = str(entity.get("entity_type"))
        order = {"asset": 0, "ip": 1, "hostname": 2, "user": 3}.get(kind, 9)
        value = str(entity.get("asset_id") or entity.get("value") or "")
        return order, value.casefold()

    entities = sorted(provisional, key=sort_key)
    index: dict[str, str] = {}
    for sequence, entity in enumerate(entities, start=1):
        entity_ref = f"E{sequence}"
        entity["entity_ref"] = entity_ref
        if entity["entity_type"] == "asset":
            index[f"asset:{entity['asset_id']}"] = entity_ref
            for alias in entity["aliases"]:
                kind = str(alias["type"])
                value = str(alias["value"])
                lookup = value.casefold() if kind == "hostname" else value
                owners = ip_to_assets[value] if kind == "ip" else host_to_assets[lookup]
                if len(owners & requested_assets) == 1:
                    index[f"{kind}:{lookup}"] = entity_ref
        else:
            value = str(entity["value"])
            lookup = value.casefold() if entity["entity_type"] in {"hostname", "user"} else value
            if not any(item["key"] == f"{entity['entity_type']}:{value}" for item in conflicts):
                index[f"{entity['entity_type']}:{lookup}"] = entity_ref
    return entities, index, {"conflicts": conflicts}


def _record_anchor_refs(record: Mapping[str, Any], index: Mapping[str, str]) -> set[str]:
    refs: set[str] = set()
    asset_id = _text(record.get("affected_asset_id"))
    if asset_id and (ref := index.get(f"asset:{asset_id}")):
        refs.add(ref)
    asset = _mapping(record.get("asset"))
    for kind, value in (
        ("asset", _first(asset.get("id"), asset.get("asset_id"))),
        ("ip", asset.get("ip")),
        ("hostname", asset.get("hostname")),
        ("ip", record.get("source_ip")),
        ("ip", record.get("destination_ip")),
    ):
        text = _text(value)
        if not text:
            continue
        lookup = text.casefold() if kind == "hostname" else text
        if ref := index.get(f"{kind}:{lookup}"):
            refs.add(ref)
    return refs


def expand_related_entities(
    entities: Iterable[Mapping[str, Any]],
    index: Mapping[str, str],
    records: Iterable[Mapping[str, Any]],
    time_range: list[str],
) -> tuple[list[dict[str, Any]], dict[str, str], dict[str, Any]]:
    """Expand alert-only entities once from explicit relations to original anchors.

    Newly added related entities are never used to discover further entities.
    """

    result = [copy.deepcopy(dict(entity)) for entity in entities]
    result_index = dict(index)
    anchor_refs = {
        str(entity["entity_ref"])
        for entity in result
        if entity.get("role") == "anchor" and entity.get("entity_ref")
    }
    candidates: dict[str, dict[str, Any]] = {}
    for record in records:
        direct_refs = _record_anchor_refs(record, index) & anchor_refs
        if not direct_refs:
            continue
        for field in ("source_ip", "destination_ip"):
            value = _text(record.get(field))
            if not value or f"ip:{value}" in result_index:
                continue
            candidates.setdefault(
                f"ip:{value}",
                {
                    "entity_type": "ip",
                    "role": "related",
                    "value": value,
                    "aliases": [],
                    "related_to": sorted(direct_refs),
                    "relation": "observed_network_endpoint_pair",
                    "valid_during": list(time_range),
                    "provenance": ["contributing_alert"],
                },
            )
        user_name = _text(_mapping(record.get("user")).get("name"))
        if user_name:
            for anchor_ref in sorted(direct_refs):
                key = f"user:{anchor_ref}:{user_name.casefold()}"
                candidates.setdefault(
                    key,
                    {
                        "entity_type": "user",
                        "role": "related",
                        "value": user_name,
                        "bound_asset_ref": anchor_ref,
                        "aliases": [],
                        "related_to": [anchor_ref],
                        "relation": "observed_asset_account",
                        "valid_during": list(time_range),
                        "provenance": ["contributing_alert"],
                    },
                )

    next_number = max(
        (
            int(str(entity.get("entity_ref", "E0"))[1:])
            for entity in result
            if str(entity.get("entity_ref", "")).startswith("E")
            and str(entity.get("entity_ref", ""))[1:].isdigit()
        ),
        default=0,
    )
    for key in sorted(candidates):
        next_number += 1
        entity = candidates[key]
        entity_ref = f"E{next_number}"
        entity["entity_ref"] = entity_ref
        result.append(entity)
        result_index[key] = entity_ref
        if entity["entity_type"] == "user" and f"user:{entity['value'].casefold()}" not in result_index:
            result_index[f"user:{entity['value'].casefold()}"] = entity_ref
    return result, result_index, {
        "related_entity_count": len(candidates),
        "recursive_expansion": False,
    }


def attach_entity_refs(
    records: Iterable[Mapping[str, Any]],
    index: Mapping[str, str],
    *,
    owner_refs: set[str] | None = None,
) -> list[dict[str, Any]]:
    """Attach all related entities and, when unambiguous, the local owner.

    ``owner_refs`` contains the incident-declared anchors eligible to own local
    endpoint behaviour.  A record without an explicit affected asset is bound
    to a local owner only when exactly one endpoint maps to such an anchor.
    """

    eligible_owners = {str(value) for value in (owner_refs or set())}
    result: list[dict[str, Any]] = []
    for record in records:
        row = copy.deepcopy(dict(record))
        refs: set[str] = set()
        asset_id = _text(row.get("affected_asset_id"))
        if asset_id and (ref := index.get(f"asset:{asset_id}")):
            row["entity_ref"] = ref
            refs.add(ref)
        asset = _mapping(row.get("asset"))
        if not row.get("entity_ref"):
            for kind, value in (
                ("asset", _first(asset.get("id"), asset.get("asset_id"))),
                ("ip", asset.get("ip")),
                ("hostname", asset.get("hostname")),
            ):
                text = _text(value)
                if not text:
                    continue
                lookup = text.casefold() if kind == "hostname" else text
                if ref := index.get(f"{kind}:{lookup}"):
                    row["entity_ref"] = ref
                    refs.add(ref)
                    break
        for field, output_field in (
            ("source_ip", "source_entity_ref"),
            ("destination_ip", "destination_entity_ref"),
        ):
            value = _text(row.get(field))
            if value and (ref := index.get(f"ip:{value}")):
                row[output_field] = ref
                refs.add(ref)
        if not row.get("entity_ref") and eligible_owners:
            endpoint_owners = refs.intersection(eligible_owners)
            if len(endpoint_owners) == 1:
                row["entity_ref"] = next(iter(endpoint_owners))
        user_name = _text(_mapping(row.get("user")).get("name"))
        if user_name:
            scoped_key = (
                f"user:{row.get('entity_ref')}:{user_name.casefold()}"
                if row.get("entity_ref")
                else None
            )
            ref = result_index_ref = (
                index.get(scoped_key) if scoped_key else None
            ) or index.get(f"user:{user_name.casefold()}")
            if result_index_ref:
                row["user_entity_ref"] = result_index_ref
                refs.add(result_index_ref)
        row["entity_refs"] = sorted(refs)
        if len(refs) >= 2:
            row["relation_strength"] = "definite"
        result.append(row)
    return result


def _json_key(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str)


def _identity_key(record: Mapping[str, Any]) -> tuple[str, str]:
    for label, field in (
        ("raw_event_uid", "raw_event_uid"),
        ("source_record_id", "source_record_id"),
        ("edr_event_id", "edr_event_id"),
        ("raw_ref", "raw_ref"),
        ("raw_event_key", "raw_event_key"),
    ):
        if value := _text(record.get(field)):
            return label, value
    process = _mapping(record.get("process"))
    parent = _mapping(process.get("parent"))
    fingerprint = {
        "source": record.get("source"),
        "entity_ref": record.get("entity_ref"),
        "affected_asset_id": record.get("affected_asset_id"),
        "event_type": record.get("alert_type") or record.get("event_type"),
        "action": record.get("action") or record.get("native_result"),
        "process_uid": process.get("uid"),
        "process_pid": process.get("pid"),
        "process_path": process.get("path"),
        "process_cmdline": process.get("cmdline"),
        "parent_uid": parent.get("uid"),
        "source_ip": record.get("source_ip"),
        "source_port": record.get("source_port"),
        "destination_ip": record.get("destination_ip"),
        "destination_port": record.get("destination_port"),
        "protocol": record.get("protocol"),
        "user": _mapping(record.get("user")).get("name"),
        "event_time": record.get("event_time"),
    }
    digest = hashlib.sha256(_json_key(fingerprint).encode("utf-8")).hexdigest()
    return "fingerprint", digest


def deduplicate_records(
    records: Iterable[Mapping[str, Any]],
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    grouped: dict[tuple[str, str], dict[str, Any]] = {}
    input_count = 0
    for raw in records:
        input_count += 1
        row = copy.deepcopy(dict(raw))
        identity = _identity_key(row)
        if identity not in grouped:
            row["record_key"] = f"{identity[0]}:{identity[1]}"
            row["alert_ids"] = sorted(
                {
                    str(value)
                    for value in [row.get("alert_id"), *_list(row.get("alert_ids"))]
                    if value not in (None, "")
                }
            )
            row["rule_ids"] = sorted(
                {
                    str(value)
                    for value in [row.get("rule_id"), *_list(row.get("rule_ids"))]
                    if value not in (None, "")
                }
            )
            grouped[identity] = row
            continue
        current = grouped[identity]
        current["alert_ids"] = sorted(
            set(current.get("alert_ids", []))
            | {
                str(value)
                for value in [row.get("alert_id"), *_list(row.get("alert_ids"))]
                if value not in (None, "")
            }
        )
        current["rule_ids"] = sorted(
            set(current.get("rule_ids", []))
            | {
                str(value)
                for value in [row.get("rule_id"), *_list(row.get("rule_ids"))]
                if value not in (None, "")
            }
        )
        for key, value in row.items():
            if current.get(key) in (None, "", [], {}) and value not in (None, "", [], {}):
                current[key] = value

    result = sorted(
        grouped.values(),
        key=lambda row: (
            parse_datetime_utc(row.get("event_time"))
            or datetime.min.replace(tzinfo=timezone.utc),
            str(row["record_key"]),
        ),
    )
    return result, {
        "input_count": input_count,
        "output_count": len(result),
        "duplicate_count": input_count - len(result),
    }


def _record_time(record: Mapping[str, Any]) -> datetime | None:
    return parse_datetime_utc(record.get("event_time"))


def _pid_link(parent: Mapping[str, Any], child: Mapping[str, Any], guard: timedelta) -> bool:
    if parent.get("entity_ref") != child.get("entity_ref"):
        return False
    parent_process = _mapping(parent.get("process"))
    child_process = _mapping(child.get("process"))
    if _text(parent_process.get("pid")) != _text(_mapping(child_process.get("parent")).get("pid")):
        return False
    parent_start = _record_time(parent)
    child_start = _record_time(child)
    if parent_start is None or child_start is None or child_start < parent_start:
        return False
    parent_end = parse_datetime_utc(parent_process.get("end_time"))
    return child_start <= parent_end if parent_end is not None else child_start - parent_start <= guard


def build_process_neighborhood(
    records: Iterable[Mapping[str, Any]],
    *,
    seed_record_keys: set[str],
    max_hops: int = 2,
    pid_reuse_guard_minutes: int = 30,
) -> set[str]:
    """Return records at most ``max_hops`` from alert process seeds."""

    rows = [dict(row) for row in records]
    by_key = {str(row.get("record_key")): row for row in rows if row.get("record_key")}
    adjacency: dict[str, set[str]] = defaultdict(set)
    guard = timedelta(minutes=pid_reuse_guard_minutes)
    for left_index, left in enumerate(rows):
        left_key = _text(left.get("record_key"))
        if not left_key:
            continue
        left_process = _mapping(left.get("process"))
        left_uid = _text(left_process.get("uid"))
        left_parent_uid = _text(_mapping(left_process.get("parent")).get("uid"))
        for right in rows[left_index + 1 :]:
            right_key = _text(right.get("record_key"))
            if not right_key or left.get("entity_ref") != right.get("entity_ref"):
                continue
            right_process = _mapping(right.get("process"))
            right_uid = _text(right_process.get("uid"))
            right_parent_uid = _text(_mapping(right_process.get("parent")).get("uid"))
            guid_link = bool(
                (left_uid and right_parent_uid == left_uid)
                or (right_uid and left_parent_uid == right_uid)
            )
            pid_link = _pid_link(left, right, guard) or _pid_link(right, left, guard)
            if guid_link or pid_link:
                adjacency[left_key].add(right_key)
                adjacency[right_key].add(left_key)

    visited = {key for key in seed_record_keys if key in by_key}
    queue = deque((key, 0) for key in sorted(visited))
    while queue:
        key, distance = queue.popleft()
        if distance >= max_hops:
            continue
        for neighbor in sorted(adjacency.get(key, set())):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, distance + 1))
    return visited


def _record_entity_refs(record: Mapping[str, Any]) -> set[str]:
    values = {
        str(value)
        for value in _list(record.get("entity_refs"))
        if value not in (None, "")
    }
    if record.get("entity_ref"):
        values.add(str(record["entity_ref"]))
    for field in ("source_entity_ref", "destination_entity_ref", "user_entity_ref"):
        if record.get(field):
            values.add(str(record[field]))
    return values


def select_records(
    records: Iterable[Mapping[str, Any]],
    *,
    anchor_refs: set[str],
    process_linked_keys: set[str],
    budget: int,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Retain by relation strength, then earlier business time, within one budget."""

    rows = [dict(row) for row in records]

    def priority(row: Mapping[str, Any]) -> int:
        refs = _record_entity_refs(row)
        if len(refs & anchor_refs) >= 2:
            return 1
        if row.get("record_key") in process_linked_keys:
            return 2
        if row.get("relation_strength") == "definite" and refs & anchor_refs:
            return 3
        if refs & anchor_refs:
            return 4
        return 5

    ranked = sorted(
        rows,
        key=lambda row: (
            priority(row),
            _record_time(row) or datetime.max.replace(tzinfo=timezone.utc),
            str(row.get("record_key") or ""),
        ),
    )
    kept = ranked[: max(0, budget)]
    kept.sort(
        key=lambda row: (
            _record_time(row) or datetime.max.replace(tzinfo=timezone.utc),
            str(row.get("record_key") or ""),
        )
    )
    cutoff_candidates = [_record_time(row) for row in kept]
    cutoff = max((value for value in cutoff_candidates if value is not None), default=None)
    return kept, {
        "input_count": len(rows),
        "retained_count": len(kept),
        "dropped_count": len(rows) - len(kept),
        "cutoff_time": _iso(cutoff) if cutoff else None,
        "priority_counts": {
            str(level): sum(1 for row in rows if priority(row) == level)
            for level in range(1, 6)
        },
    }


def aggregate_repeated_behaviors(
    records: Iterable[Mapping[str, Any]], *, sample_limit: int = 3
) -> list[dict[str, Any]]:
    groups: dict[str, list[Mapping[str, Any]]] = defaultdict(list)
    for row in records:
        process = _mapping(row.get("process"))
        user = _mapping(row.get("user"))
        signature = {
            "entity_ref": row.get("entity_ref"),
            "event_type": row.get("alert_type") or row.get("event_type"),
            "action": row.get("action") or row.get("native_result"),
            "process_path": process.get("path"),
            "process_cmdline": process.get("cmdline"),
            "user": user.get("name"),
            "destination_port": row.get("destination_port"),
            "protocol": row.get("protocol"),
        }
        groups[_json_key(signature)].append(row)

    result: list[dict[str, Any]] = []
    for signature_key, rows in groups.items():
        signature = json.loads(signature_key)
        times = sorted(
            value
            for value in (parse_datetime_utc(row.get("event_time")) for row in rows)
            if value is not None
        )
        targets = sorted(
            {
                str(row.get("destination_ip"))
                for row in rows
                if row.get("destination_ip") not in (None, "")
            }
        )
        result.append(
            {
                **{key: value for key, value in signature.items() if value not in (None, "")},
                "count": len(rows),
                "first_seen": _iso(times[0]) if times else None,
                "last_seen": _iso(times[-1]) if times else None,
                "distinct_targets": targets,
                "sample_record_ids": [
                    str(row.get("record_key")) for row in rows[:sample_limit]
                ],
                "alert_ids": sorted(
                    {
                        str(alert_id)
                        for row in rows
                        for alert_id in _list(row.get("alert_ids"))
                    }
                ),
                "rule_ids": sorted(
                    {
                        str(rule_id)
                        for row in rows
                        for rule_id in _list(row.get("rule_ids"))
                    }
                ),
            }
        )
    return sorted(
        result,
        key=lambda row: (str(row.get("first_seen") or ""), _json_key(row)),
    )


def build_forward_slices(
    start: str, end: str, *, max_slices: int = 12
) -> list[tuple[str, str]]:
    start_time = parse_datetime_utc(start)
    end_time = parse_datetime_utc(end)
    if start_time is None or end_time is None or end_time < start_time:
        raise ValueError("invalid effective time range")
    if max_slices < 1:
        raise ValueError("max_slices must be positive")
    if start_time == end_time:
        return [(_iso(start_time), _iso(end_time))]
    duration = end_time - start_time
    slice_count = min(max_slices, max(1, int(duration.total_seconds() // 3600) + 1))
    width = duration / slice_count
    result: list[tuple[str, str]] = []
    cursor = start_time
    for index in range(slice_count):
        slice_end = end_time if index == slice_count - 1 else start_time + width * (index + 1)
        result.append((_iso(cursor), _iso(slice_end)))
        cursor = slice_end
    return result

"""Minimal read-only client for the configured MCP resource gateway."""

from __future__ import annotations

import json
import time
import urllib.error
import urllib.request
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable, Iterable, Mapping

from fusion_contract import CallOutcome


READ_ONLY_POST_TOOLS = frozenset(
    {
        "ai_soc_detect__create_detect_alert_by_ids",
        "ai_soc_event__count_event",
        "ai_soc_event__search_event",
        "ai_soc_correlate__get_correlate_intel_check",
        "ai_soc_correlate__get_correlate_intel_check_list",
    }
)


@dataclass(frozen=True)
class McpCallResult:
    outcome: CallOutcome
    data: Any
    result_count: int | None
    latency_ms: int
    raw_response_file: str
    response: Mapping[str, Any]


class McpCatalog:
    def __init__(
        self,
        resources: Mapping[str, Mapping[str, Any]],
        tools: Mapping[str, Mapping[str, Any]],
    ) -> None:
        self.resources = dict(resources)
        self.tools = dict(tools)

    @classmethod
    def from_documents(
        cls,
        resource_document: Mapping[str, Any],
        tool_documents: Iterable[Mapping[str, Any]],
    ) -> "McpCatalog":
        resources = {
            str(item["slug"]): item
            for item in resource_document.get("items", [])
            if isinstance(item, Mapping) and item.get("slug") and item.get("id")
        }
        tools: dict[str, Mapping[str, Any]] = {}
        for document in tool_documents:
            if "items" in document:
                items = document.get("items", [])
            else:
                items = document.values()
            for item in items:
                if isinstance(item, Mapping) and item.get("name"):
                    tools[str(item["name"])] = item
        return cls(resources, tools)

    @classmethod
    def from_directory(cls, directory: Path) -> "McpCatalog":
        resources = json.loads(
            (directory / ".current-resources.local.json").read_text(encoding="utf-8")
        )
        tool_documents = [
            json.loads(path.read_text(encoding="utf-8"))
            for path in sorted(directory.glob(".current-ai_soc_*-tools.local.json"))
        ]
        return cls.from_documents(resources, tool_documents)


def extract_result_data(response: Mapping[str, Any]) -> Any:
    result = response.get("result")
    if isinstance(result, Mapping) and "data" in result:
        return result.get("data")
    return result


def _is_empty_data(data: Any) -> bool:
    if data is None or data == [] or data == {} or data == "":
        return True
    if isinstance(data, Mapping) and isinstance(data.get("items"), list):
        if data["items"]:
            return False
        total = data.get("total")
        return total in (None, 0, "0")
    if isinstance(data, Mapping) and "total" in data:
        total = data.get("total")
        if total in (0, "0"):
            hits = data.get("hits")
            return hits in (None, [])
    return False


def classify_response(response: Mapping[str, Any]) -> CallOutcome:
    status = str(response.get("status", "")).lower()
    status_code = response.get("status_code")
    result = response.get("result")
    inner_code = result.get("code") if isinstance(result, Mapping) else None
    if status not in {"success", "ok"}:
        return CallOutcome.FAILED
    if status_code not in (None, 200) or inner_code not in (None, 200):
        return CallOutcome.FAILED
    if isinstance(result, Mapping) and result.get("_truncated") is True:
        return CallOutcome.TRUNCATED
    return (
        CallOutcome.SUCCESS_EMPTY
        if _is_empty_data(extract_result_data(response))
        else CallOutcome.SUCCESS_WITH_DATA
    )


def result_count(data: Any) -> int | None:
    if data is None:
        return 0
    if isinstance(data, list):
        return len(data)
    if isinstance(data, Mapping):
        total = data.get("total")
        if isinstance(total, int):
            return total
        if isinstance(total, str) and total.isdigit():
            return int(total)
        items = data.get("items")
        if isinstance(items, list):
            return len(items)
        return 0 if not data else 1
    return 1


def _default_transport(endpoint: str, payload: Mapping[str, Any], timeout: int) -> Any:
    body = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode(
        "utf-8"
    )
    request = urllib.request.Request(
        endpoint,
        data=body,
        headers={"Content-Type": "application/json", "Accept": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            raw = response.read()
    except urllib.error.HTTPError as error:
        raw = error.read()
        try:
            parsed = json.loads(raw.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError):
            parsed = {}
        if not isinstance(parsed, dict):
            parsed = {}
        parsed.setdefault("status", "error")
        parsed.setdefault("status_code", error.code)
        return parsed
    except urllib.error.URLError as error:
        return {
            "status": "error",
            "status_code": None,
            "error_type": type(error.reason).__name__,
        }
    try:
        return json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return {
            "status": "error",
            "status_code": None,
            "error_type": "UNPARSEABLE_RESPONSE",
        }


class McpGateway:
    def __init__(
        self,
        *,
        base_url: str,
        catalog: McpCatalog,
        raw_directory: Path,
        transport: Callable[[str, Mapping[str, Any], int], Any] = _default_transport,
        timeout: int = 120,
    ) -> None:
        self.base_url = base_url.rstrip("/")
        self.catalog = catalog
        self.raw_directory = raw_directory
        self.transport = transport
        self.timeout = timeout

    def _validate(
        self, resource: str, tool_name: str, arguments: Mapping[str, Any]
    ) -> tuple[Mapping[str, Any], Mapping[str, Any]]:
        tool = self.catalog.tools.get(tool_name)
        if tool is None:
            raise KeyError(f"MCP tool is absent from catalog: {tool_name}")
        resource_record = self.catalog.resources.get(resource)
        if resource_record is None:
            raise KeyError(f"MCP resource is absent from catalog: {resource}")
        if tool.get("resource_id") != resource_record.get("id"):
            raise ValueError(f"tool does not belong to resource: {tool_name}")
        method = str(tool.get("http_method", "")).upper()
        if method != "GET" and tool_name not in READ_ONLY_POST_TOOLS:
            raise PermissionError(f"tool did not pass read-only gate: {tool_name}")
        schema = tool.get("schema_json")
        parameter_schema = schema.get("parameters", {}) if isinstance(schema, Mapping) else {}
        missing = [
            name
            for name in parameter_schema.get("required", [])
            if name not in arguments
        ]
        if missing:
            raise ValueError(f"missing required MCP arguments: {', '.join(missing)}")
        return resource_record, tool

    def invoke(
        self,
        *,
        call_id: str,
        resource: str,
        tool_name: str,
        arguments: Mapping[str, Any],
    ) -> McpCallResult:
        resource_record, _ = self._validate(resource, tool_name, arguments)
        endpoint = (
            f"{self.base_url}/api/v1/mcp-resources/{resource_record['id']}"
            f"/tools/{tool_name}/invoke"
        )
        started = time.monotonic()
        response = self.transport(
            endpoint, {"arguments": dict(arguments)}, self.timeout
        )
        latency_ms = round((time.monotonic() - started) * 1000)
        if not isinstance(response, Mapping):
            response = {
                "status": "error",
                "status_code": None,
                "error_type": "NON_OBJECT_RESPONSE",
            }
        self.raw_directory.mkdir(parents=True, exist_ok=True)
        raw_path = self.raw_directory / f"{call_id}.json"
        raw_path.write_text(
            json.dumps(response, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        outcome = classify_response(response)
        data = extract_result_data(response)
        return McpCallResult(
            outcome=outcome,
            data=data,
            result_count=(
                result_count(data)
                if outcome not in (CallOutcome.FAILED, CallOutcome.TRUNCATED)
                else None
            ),
            latency_ms=latency_ms,
            raw_response_file=str(raw_path),
            response=response,
        )

#!/usr/bin/env python3
"""Deterministically compact five-source evidence for the judgement model.

The audit artefacts remain unchanged.  This projection only removes repeated
provenance identifiers from the model-facing package and turns observed
network endpoint pairs into concise host-to-host path hints.
"""

from __future__ import annotations

import argparse
import copy
import json
import os
from collections import defaultdict
from pathlib import Path
from typing import Any, Iterable, Mapping


def _mapping(value: Any) -> Mapping[str, Any]:
    return value if isinstance(value, Mapping) else {}


def _list(value: Any) -> list[Any]:
    return value if isinstance(value, list) else []


def _nonempty(value: Any) -> bool:
    return value not in (None, "", [], {})


def _sparse(value: Any) -> Any:
    if isinstance(value, Mapping):
        compact = {str(key): _sparse(item) for key, item in value.items()}
        return {key: item for key, item in compact.items() if _nonempty(item)}
    if isinstance(value, list):
        compact = [_sparse(item) for item in value]
        return [item for item in compact if _nonempty(item)]
    return value


def _stable(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True, default=str)


def _unique(rows: Iterable[Mapping[str, Any]]) -> list[dict[str, Any]]:
    result: dict[str, dict[str, Any]] = {}
    for row in rows:
        current = _sparse(dict(row))
        if current:
            result[_stable(current)] = current
    return list(result.values())


def _endpoint_entity_index(
    entities: Iterable[Mapping[str, Any]],
) -> dict[str, dict[str, Any]]:
    candidates: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for entity in entities:
        entity_ref = entity.get("entity_ref")
        if entity_ref in (None, ""):
            continue
        ips: set[str] = set()
        hostname = None
        if entity.get("entity_type") == "ip" and entity.get("value") not in (None, ""):
            ips.add(str(entity["value"]))
        for alias in _list(entity.get("aliases")):
            current = _mapping(alias)
            value = current.get("value")
            if value in (None, ""):
                continue
            if current.get("type") == "ip":
                ips.add(str(value))
            elif current.get("type") == "hostname" and hostname is None:
                hostname = str(value)
        descriptor = _sparse(
            {
                "ref": str(entity_ref),
                "asset_id": entity.get("asset_id"),
                "host": hostname,
                "role": entity.get("role"),
                "entity_type": entity.get("entity_type"),
            }
        )
        for ip in ips:
            candidates[ip].append(descriptor)
    return {
        ip: sorted(
            rows,
            key=lambda row: (
                row.get("role") != "anchor",
                row.get("entity_type") != "asset",
                str(row.get("ref") or ""),
            ),
        )[0]
        for ip, rows in candidates.items()
    }


def _network_metadata(edr_detail: Mapping[str, Any]) -> dict[tuple[str, str], dict[str, Any]]:
    groups: dict[tuple[str, str], dict[str, Any]] = {}
    for entity in _list(edr_detail.get("entities")):
        for segment in _list(_mapping(entity).get("activity_segments")):
            for row in _list(_mapping(segment).get("network_details")):
                current = _mapping(row)
                source_ip = current.get("source_ip")
                destination_ip = current.get("destination_ip")
                if source_ip in (None, "") or destination_ip in (None, ""):
                    continue
                key = (str(source_ip), str(destination_ip))
                group = groups.setdefault(
                    key,
                    {"protocols": set(), "times": []},
                )
                if current.get("protocol") not in (None, ""):
                    group["protocols"].add(str(current["protocol"]))
                for field in ("observed_at", "first_seen", "last_seen"):
                    if current.get(field) not in (None, ""):
                        group["times"].append(str(current[field]))
                for value in _list(current.get("time_range")):
                    if value not in (None, ""):
                        group["times"].append(str(value))
    return groups


def _compact_hosts(rows: Iterable[Mapping[str, Any]]) -> list[dict[str, Any]]:
    return _unique(
        _sparse(
            {
                "entity_ref": row.get("entity_ref"),
                "asset_id": row.get("asset_id"),
                "hostname": row.get("hostname"),
                "ip": row.get("ip"),
                "direction": row.get("direction"),
            }
        )
        for row in rows
        if row.get("relation") != "observed_network_endpoint_pair"
    )


def _compact_users(rows: Iterable[Mapping[str, Any]]) -> list[dict[str, Any]]:
    return _unique(
        _sparse(
            {
                "entity_ref": row.get("entity_ref"),
                "name": row.get("name") or row.get("account") or row.get("username"),
                "privilege": row.get("privilege"),
                "role": row.get("role"),
            }
        )
        for row in rows
    )


def _compact_paths(
    graph: Mapping[str, Any],
    entities: Iterable[Mapping[str, Any]],
    edr_detail: Mapping[str, Any],
) -> list[dict[str, Any]]:
    def is_self_relation(row: Mapping[str, Any]) -> bool:
        source_ref = row.get("src_ref")
        destination_ref = row.get("dst_ref")
        if source_ref not in (None, "") and source_ref == destination_ref:
            return True
        source_asset = row.get("src_asset_id")
        destination_asset = row.get("dst_asset_id")
        if source_asset not in (None, "") and source_asset == destination_asset:
            return True
        source_ip = row.get("src_ip")
        destination_ip = row.get("dst_ip")
        return source_ip not in (None, "") and source_ip == destination_ip

    existing = [
        dict(row)
        for row in _list(graph.get("path_hints"))
        if isinstance(row, Mapping) and row.get("src_ip") and row.get("dst_ip")
    ]
    if existing:
        return _unique(row for row in existing if not is_self_relation(row))
    endpoint_pairs = [
        row
        for row in _list(graph.get("related_hosts"))
        if isinstance(row, Mapping)
        and row.get("relation") == "observed_network_endpoint_pair"
    ]
    entity_index = _endpoint_entity_index(entities)
    network_index = _network_metadata(edr_detail)
    result: list[dict[str, Any]] = []
    for pair in endpoint_pairs:
        source_ip = pair.get("source_ip")
        destination_ip = pair.get("destination_ip")
        if source_ip in (None, "") or destination_ip in (None, ""):
            continue
        source_ip = str(source_ip)
        destination_ip = str(destination_ip)
        source = entity_index.get(source_ip, {})
        destination = entity_index.get(destination_ip, {})
        network = network_index.get((source_ip, destination_ip), {})
        times = sorted(set(network.get("times") or []))
        path = _sparse(
            {
                    "src_ref": source.get("ref"),
                    "src_asset_id": source.get("asset_id"),
                    "src_host": source.get("host"),
                    "src_ip": source_ip,
                    "dst_ref": destination.get("ref"),
                    "dst_asset_id": destination.get("asset_id"),
                    "dst_host": destination.get("host"),
                    "dst_ip": destination_ip,
                    "protocols": sorted(network.get("protocols") or []),
                    "dst_ports": pair.get("destination_ports"),
                    "count": pair.get("observation_count"),
                    "time_range": [times[0], times[-1]] if times else None,
                    "basis": "event",
            }
        )
        if not is_self_relation(path):
            result.append(path)
    return _unique(result)


def _legacy_action(row: Mapping[str, Any]) -> Any:
    if row.get("action") not in (None, ""):
        return row.get("action")
    alert_ids = [str(value) for value in _list(row.get("alert_ids"))]
    if alert_ids and all(value.startswith("event:") for value in alert_ids):
        return row.get("event_type")
    return None


def _sorted_text(values: Iterable[Any]) -> list[str]:
    return sorted({str(value) for value in values if value not in (None, "")})


def _entity_display(row: Mapping[str, Any]) -> str | None:
    """Build a readable identity without exposing the internal E-number key."""

    def first(*fields: str) -> str | None:
        for field in fields:
            value = row.get(field)
            values = value if isinstance(value, list) else [value]
            normalized = _sorted_text(values)
            if normalized:
                return normalized[0]
        return None

    entity_type = str(row.get("entity_type") or "")
    hostname = first("hostname", "hostnames")
    ip = first("ip", "ips")
    name = first("name", "names")
    value = first("value", "values")
    asset_id = first("asset_id")

    if entity_type == "asset":
        head = hostname or ip or name or value
        qualifiers: list[str] = []
        if hostname and ip:
            qualifiers.append(ip)
        if asset_id:
            qualifiers.append(f"资产ID {asset_id}")
        if head and qualifiers:
            return f"{head}（{'，'.join(qualifiers)}）"
        if head:
            return head
        return f"资产ID {asset_id}" if asset_id else None
    if entity_type == "ip":
        return ip or value
    if entity_type in {"user", "account"}:
        return name or value
    if entity_type == "hostname":
        return hostname or value
    return hostname or ip or name or value or (f"资产ID {asset_id}" if asset_id else None)


def _compact_entity(row: Mapping[str, Any]) -> dict[str, Any]:
    aliases: dict[str, list[str]] = defaultdict(list)
    for alias in _list(row.get("aliases")):
        current = _mapping(alias)
        alias_type = current.get("type")
        value = current.get("value")
        if alias_type not in (None, "") and value not in (None, ""):
            aliases[str(alias_type)].append(str(value))
    entity_type = str(row.get("entity_type") or "")
    value = row.get("value")
    if value not in (None, ""):
        if entity_type == "ip":
            aliases["ip"].append(str(value))
        elif entity_type == "hostname":
            aliases["hostname"].append(str(value))
        elif entity_type in {"user", "account"}:
            aliases["name"].append(str(value))
        else:
            aliases["value"].append(str(value))
    for singular in ("ip", "hostname", "name", "value"):
        if singular == "value" and entity_type in {"ip", "hostname", "user", "account"}:
            continue
        direct = row.get(singular)
        if direct not in (None, ""):
            aliases[singular].append(str(direct))
        aliases[singular].extend(_list(row.get(f"{singular}s")))

    compact = {
        "entity_ref": row.get("entity_ref"),
        "entity_type": row.get("entity_type"),
        "role": row.get("role"),
        "asset_id": row.get("asset_id"),
        "bound_asset_ref": row.get("bound_asset_ref"),
        "related_to": row.get("related_to"),
    }
    for alias_type, values in aliases.items():
        unique = _sorted_text(values)
        if not unique:
            continue
        singular = {
            "ip": "ip",
            "hostname": "hostname",
            "name": "name",
            "value": "value",
        }.get(alias_type)
        if singular is None:
            continue
        compact[singular if len(unique) == 1 else f"{singular}s"] = (
            unique[0] if len(unique) == 1 else unique
        )
    compact["entity_display"] = _entity_display(compact)
    return _sparse(compact)


def _observed_time(row: Mapping[str, Any]) -> dict[str, Any]:
    if row.get("observed_at") not in (None, ""):
        return {"observed_at": row.get("observed_at")}
    elif _list(row.get("time_range")):
        return {"time_range": row.get("time_range")}
    elif row.get("first_seen") and row.get("first_seen") == row.get("last_seen"):
        return {"observed_at": row.get("first_seen")}
    elif row.get("first_seen") or row.get("last_seen"):
        return {"time_range": [row.get("first_seen"), row.get("last_seen")]}
    return {}


def _normalized_image(value: Any) -> str | None:
    if value in (None, ""):
        return None
    return str(value).strip().replace("\\", "/").lower() or None


def _image_aliases(value: Any) -> list[str]:
    normalized = _normalized_image(value)
    if not normalized:
        return []
    basename = normalized.rsplit("/", 1)[-1]
    return [f"image:{normalized}", f"basename:{basename}"]


def _uid_values(row: Mapping[str, Any]) -> list[str]:
    values = [*_list(row.get("process_uids")), row.get("process_uid")]
    return _sorted_text(values)


class _ProcessRegistry:
    def __init__(self) -> None:
        self.nodes: list[dict[str, Any]] = []
        self._by_ref: dict[str, dict[str, Any]] = {}
        self._aliases: dict[str, str | None] = {}

    def _lookup_aliases(self, aliases: Iterable[str]) -> str | None:
        refs = {self._aliases.get(alias) for alias in aliases}
        refs.discard(None)
        if len(refs) == 1:
            return next(iter(refs))
        return None

    def lookup(self, row: Mapping[str, Any]) -> str | None:
        uids = _uid_values(row)
        if uids:
            return self._lookup_aliases(f"uid:{value}" for value in uids)
        if row.get("pid") not in (None, ""):
            ref = self._lookup_aliases([f"pid:{row['pid']}"])
            if ref:
                return ref
        return self._lookup_aliases(_image_aliases(row.get("image") or row.get("process_image")))

    def _bind_alias(self, alias: str, ref: str) -> None:
        if alias not in self._aliases:
            self._aliases[alias] = ref
        elif self._aliases[alias] != ref:
            self._aliases[alias] = None

    def ensure(self, row: Mapping[str, Any], *, parent_only: bool = False) -> str | None:
        if not any(
            _nonempty(row.get(field))
            for field in ("image", "process_image", "cmdline", "process_uid", "process_uids", "pid")
        ):
            return None
        ref = self.lookup(row)
        if (
            ref is not None
            and not _uid_values(row)
            and row.get("pid") in (None, "")
            and row.get("cmdline") not in (None, "")
            and self._by_ref[ref].get("cmdline") not in (None, "")
            and str(row["cmdline"]) != str(self._by_ref[ref]["cmdline"])
        ):
            # An image name is only a weak lookup key.  Distinct command lines
            # without a UID/PID must remain separate so later image-only rows
            # become ambiguous instead of acquiring a fabricated process edge.
            ref = None
        if ref is None:
            ref = f"P{len(self.nodes) + 1:03d}"
            node = {"ref": ref}
            self.nodes.append(node)
            self._by_ref[ref] = node
        node = self._by_ref[ref]
        values = {
            "image": row.get("image") or row.get("process_image"),
            "cmdline": row.get("cmdline"),
            "user": row.get("user"),
            "native_result": row.get("native_result"),
            "action": _legacy_action(row),
            "count": row.get("count") if row.get("count") not in (None, 1) else None,
            **_observed_time(row),
        }
        if parent_only:
            values = {key: value for key, value in values.items() if key in {"image", "cmdline"}}
        for key, value in values.items():
            if _nonempty(value) and not _nonempty(node.get(key)):
                node[key] = value

        for uid in _uid_values(row):
            self._bind_alias(f"uid:{uid}", ref)
        if row.get("pid") not in (None, ""):
            self._bind_alias(f"pid:{row['pid']}", ref)
        for alias in _image_aliases(row.get("image") or row.get("process_image")):
            self._bind_alias(alias, ref)
        return ref


def _collect_segment_metadata(segment: Mapping[str, Any]) -> tuple[list[str], str | None]:
    sources: list[Any] = [*_list(segment.get("source_types"))]
    users: list[str] = []
    for field in (
        "process_activities",
        "processes",
        "file_operations",
        "network_details",
        "authentication_activities",
        "other_activities",
    ):
        for row in _list(segment.get(field)):
            current = _mapping(row)
            sources.extend(_list(current.get("sources")))
            if current.get("user") not in (None, ""):
                users.append(str(current["user"]))
    unique_users = _sorted_text(users)
    return _sorted_text(sources), unique_users[0] if len(unique_users) == 1 else None


def _compact_related_activity(
    row: Mapping[str, Any],
    *,
    kind: str,
    registry: _ProcessRegistry,
    owner_ips: set[str],
    default_user: str | None,
) -> dict[str, Any]:
    process_ref = row.get("process_ref") or registry.lookup(row)
    process_image = None if process_ref else row.get("process_image")
    common = {
        "process_ref": process_ref,
        "process_image": process_image,
        "count": row.get("count") if row.get("count") not in (None, 1) else None,
        **_observed_time(row),
    }
    if kind == "file_operations":
        values = {
            "path": row.get("path"),
            "operation": row.get("operation"),
            "hashes": row.get("hashes"),
            **common,
        }
    elif kind == "network_details":
        source_ip = row.get("source_ip")
        values = {
            "source_ip": source_ip if str(source_ip or "") not in owner_ips else None,
            "source_port": row.get("source_port"),
            "destination_ip": row.get("destination_ip"),
            "destination_port": row.get("destination_port"),
            "protocol": row.get("protocol"),
            "network_session_id": row.get("network_session_id"),
            "disposition": row.get("disposition"),
            **common,
        }
    elif kind == "authentication_activities":
        values = {
            "user": row.get("user") if row.get("user") != default_user else None,
            "session_id": row.get("session_id"),
            "result": row.get("result"),
            "source_ip": row.get("source_ip"),
            "destination_ip": row.get("destination_ip"),
            "event_type": row.get("event_type"),
            "count": common.get("count"),
            **_observed_time(row),
        }
    else:
        values = {
            "event_type": row.get("event_type"),
            "request_path": row.get("request_path"),
            "disposition": row.get("disposition"),
            "count": common.get("count"),
            **_observed_time(row),
        }
    return _sparse(values)


def _compact_segment(segment: Mapping[str, Any], owner_ips: set[str]) -> dict[str, Any]:
    sources, default_user = _collect_segment_metadata(segment)
    registry = _ProcessRegistry()

    existing_processes = [
        row for row in _list(segment.get("processes")) if isinstance(row, Mapping)
    ]
    if existing_processes and not _list(segment.get("process_activities")):
        registry.nodes = [_sparse(dict(row)) for row in existing_processes]
        registry._by_ref = {
            str(row["ref"]): row for row in registry.nodes if row.get("ref") not in (None, "")
        }
        for row in registry.nodes:
            for alias in _image_aliases(row.get("image")):
                registry._bind_alias(alias, str(row.get("ref")))
    else:
        for raw in _list(segment.get("process_activities")):
            row = _mapping(raw)
            parent = _mapping(row.get("parent"))
            parent_ref = registry.ensure(parent, parent_only=True)
            process_ref = registry.ensure(row)
            if process_ref and parent_ref and process_ref != parent_ref:
                registry._by_ref[process_ref]["parent_ref"] = parent_ref

    if default_user:
        for node in registry.nodes:
            if node.get("user") == default_user:
                node.pop("user", None)

    compact = {
        "segment_id": segment.get("segment_id"),
        "scope": segment.get("scope"),
        "time_range": segment.get("time_range"),
        "default_user": default_user,
        "source_types": sources,
        "processes": registry.nodes,
    }
    for kind in (
        "file_operations",
        "network_details",
        "authentication_activities",
        "other_activities",
    ):
        compact[kind] = [
            current
            for current in (
                _compact_related_activity(
                    _mapping(row),
                    kind=kind,
                    registry=registry,
                    owner_ips=owner_ips,
                    default_user=default_user,
                )
                for row in _list(segment.get(kind))
            )
            if current
        ]
    return _sparse(compact)


MODEL_PROVENANCE_FIELDS = {
    "rule_id",
    "rule_ids",
    "rule_id_count",
    "alert_ids",
    "alert_id_count",
    "sample_record_ids",
}


def _remove_model_provenance(value: Any) -> Any:
    """Remove audit-only identifiers while retaining sourced behavior facts."""

    if isinstance(value, Mapping):
        return {
            str(key): _remove_model_provenance(item)
            for key, item in value.items()
            if key not in MODEL_PROVENANCE_FIELDS
        }
    if isinstance(value, list):
        return [_remove_model_provenance(item) for item in value]
    return value


def _entity_ips(entity: Mapping[str, Any]) -> set[str]:
    values = [entity.get("ip"), *_list(entity.get("ips"))]
    return {str(value) for value in values if value not in (None, "")}


def compact_five_source_output(payload: Mapping[str, Any]) -> dict[str, Any]:
    """Return an idempotent model-facing projection of one five-source package."""

    output = copy.deepcopy(dict(payload))
    snapshot = dict(_mapping(output.get("event_snapshot")))
    context = _mapping(output.get("enriched_context"))
    graph = dict(_mapping(context.get("graph")))
    edr_detail = dict(_mapping(context.get("edr_detail")))
    audit_entities = [row for row in _list(snapshot.get("entities")) if isinstance(row, Mapping)]
    entities = [_compact_entity(row) for row in audit_entities]
    snapshot["entities"] = entities
    output["event_snapshot"] = snapshot

    graph["path_hints"] = _compact_paths(graph, audit_entities, edr_detail)
    graph["related_hosts"] = _compact_hosts(
        row for row in _list(graph.get("related_hosts")) if isinstance(row, Mapping)
    )
    graph["related_users"] = _compact_users(
        row for row in _list(graph.get("related_users")) if isinstance(row, Mapping)
    )
    graph = _remove_model_provenance(graph)

    entity_index = {
        str(entity.get("entity_ref")): entity
        for entity in entities
        if entity.get("entity_ref") not in (None, "")
    }
    compact_edr_entities: list[dict[str, Any]] = []
    for entity in _list(edr_detail.get("entities")):
        if not isinstance(entity, Mapping):
            continue
        entity_ref = str(entity.get("entity_ref") or "")
        owner_ips = _entity_ips(entity_index.get(entity_ref, {}))
        segments = [
            _compact_segment(segment, owner_ips)
            for segment in _list(entity.get("activity_segments"))
            if isinstance(segment, Mapping)
        ]
        segments = [segment for segment in segments if segment]
        if segments:
            compact_edr_entities.append(
                _sparse(
                    {
                        "entity_ref": entity_ref,
                        "entity_display": entity_index.get(entity_ref, {}).get(
                            "entity_display"
                        ),
                        "activity_segments": segments,
                    }
                )
            )
    edr_detail["entities"] = compact_edr_entities

    context = dict(context)
    context["graph"] = graph
    context["edr_detail"] = edr_detail
    output["enriched_context"] = context
    return output


def _dump_atomic(path: Path, value: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.tmp")
    temporary.write_text(
        json.dumps(value, ensure_ascii=False, indent=2, default=str) + "\n",
        encoding="utf-8",
    )
    os.replace(temporary, path)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--input", required=True)
    parser.add_argument("--output", required=True)
    args = parser.parse_args()
    source = Path(args.input).resolve()
    destination = Path(args.output).resolve()
    payload = json.loads(source.read_text(encoding="utf-8"))
    _dump_atomic(destination, compact_five_source_output(payload))
    print(destination)


if __name__ == "__main__":
    main()

"""SOC 认领和结果回写；persistence MCP 独立保存报告并返回下载地址。"""
from __future__ import annotations

import base64
import copy
import json
import urllib.parse
import urllib.request
from pathlib import Path

from mcp_gateway import McpCatalog, _default_transport, classify_response, extract_result_data
from fusion_contract import CallOutcome

LIMIT = 1048576
VALIDATION_STATUSES = {'passed', 'passed_with_warnings', 'failed', 'not_applicable_fast_classification'}


def build_writeback(run, report_html):
    raw = run['result']
    verdict = raw.get('verdict')
    if verdict not in ('误报', '真实告警', '可疑'):
        raise ValueError('verdict cannot be mapped to SOC')
    validation = run.get('validation', {}).get('status')
    if validation not in VALIDATION_STATUSES:
        raise ValueError('validationStatus cannot be mapped to SOC')
    if run['status'] != 'completed':
        raise ValueError('incomplete judgement requires SOC fail interface')
    if len(report_html.encode('utf-8')) > LIMIT:
        raise ValueError('reportHtml exceeds 1048576 UTF-8 bytes')
    fast = run['route'] == 'fast_classification'
    summary = f"事件 {run['incident_id']}，{'快速' if fast else '完整'}研判结论：{verdict}。"
    if fast:
        summary += f"命中 {len(raw.get('matches', []))} 条名单记录；依据名单规则生成，未进行完整行为研判。"
    else:
        reasoning = raw.get('reasoning_summary')
        detail = reasoning if isinstance(reasoning, str) else ''
        suffix = '模型输出校验未通过，需人工复核。' if validation == 'failed' else ''
        # 生成独立短摘要，超出时使用固定概述；原文全部保留在 resultJson 和报告。
        summary += (detail if len(summary + detail + suffix) <= 500 else '完整研判依据与建议见报告。') + suffix
    if len(summary) > 500:
        raise ValueError('summary exceeds 500 Unicode code points')
    confidence = None if fast else raw.get('confidence_score')
    if confidence is not None and (isinstance(confidence, bool) or not isinstance(confidence, (int, float)) or not 0 <= confidence <= 1):
        raise ValueError('confidence cannot be mapped to SOC')
    result_json = copy.deepcopy({k: v for k, v in run.items() if k != 'delivery'})
    result_json['schema_version'] = '1.0'
    if len(json.dumps(result_json, ensure_ascii=False).encode('utf-8')) > LIMIT:
        raise ValueError('resultJson exceeds 1048576 UTF-8 bytes')
    body = {'runId': run['run_id'], 'route': run['route'], 'llmInvoked': run['llm_invoked'],
            'verdict': verdict, 'validationStatus': validation,
            'summary': summary, 'reportHtml': report_html, 'resultJson': result_json,
            'schemaVersion': '1.0', 'agentName': 'threat-analysis'}
    if confidence is not None:
        body['confidence'] = confidence
    if run.get('model'):
        body['model'] = run['model']
    return body


class SocWriteError(RuntimeError):
    def __init__(self, code=None):
        super().__init__('SOC judgement MCP request failed')
        self.code = code


class SocJudgementClient:
    # 与只读取证客户端分开，只能读取待研判列表并执行三个已确认的写入工具。
    TOOLS = {
        'pending': 'ai_soc_correlate__get_correlate_incident_judge_pending',
        'claim': 'ai_soc_correlate__create_incident_judgement_claim',
        'result': 'ai_soc_correlate__update_incident_judgement_result',
        'fail': 'ai_soc_correlate__create_correlate_incident_judgement_fail',
    }

    def __init__(self, connection, output):
        self.url = connection['url'].rstrip('/')
        self.catalog = McpCatalog.from_directory(Path(connection['catalogDir']))
        self.output = Path(output)

    def invoke(self, operation, arguments):
        name = self.TOOLS[operation]
        resource = self.catalog.resources['ai_soc_correlate']['id']
        tool = self.catalog.tools[name]
        if tool['resource_id'] != resource:
            raise ValueError('SOC judgement tool resource mismatch')
        # 请求在网络调用前保存；同一 judgementId/runId 可用原请求重试，不重跑研判。
        self.output.mkdir(parents=True, exist_ok=True)
        (self.output / f'soc-{operation}-request.json').write_text(
            json.dumps(arguments, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
        response = _default_transport(
            f'{self.url}/api/v1/mcp-resources/{resource}/tools/{name}/invoke',
            {'arguments': arguments}, 30)
        (self.output / f'soc-{operation}-response.json').write_text(
            json.dumps(response, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
        if not isinstance(response, dict):
            raise SocWriteError()
        if classify_response(response) not in (CallOutcome.SUCCESS_WITH_DATA, CallOutcome.SUCCESS_EMPTY):
            inner = response.get('result')
            raise SocWriteError(inner.get('code', response.get('status_code')) if isinstance(inner, dict) else response.get('status_code'))
        return extract_result_data(response)

    def claim(self, incident_id):
        data = self.invoke('claim', {'incidentId': incident_id})
        if not isinstance(data, dict) or not isinstance(data.get('judgementId'), str) or not data['judgementId']:
            raise ValueError('SOC claim missing judgementId')
        return data

    def pending(self, page_size=100):
        if isinstance(page_size, bool) or not isinstance(page_size, int) or not 1 <= page_size <= 100:
            raise ValueError('pending page size must be between 1 and 100')
        return self.invoke('pending', {'pageNum': 1, 'pageSize': page_size,
                                       'previewPriority': False})

    def write(self, operation, judgement_id, body):
        error = None
        for attempt in range(1, 3):
            try:
                data = self.invoke(operation, {'judgementId': judgement_id, 'body': body})
                # judgementId/runId 保持不变，响应丢失时可由 SOC 幂等重放。
                return {'status': 'saved', 'judgement_id': judgement_id, 'attempts': attempt,
                        'replayed': isinstance(data, dict) and data.get('replayed') is True}
            except Exception as caught:
                error = caught
        state = {'status': 'failed', 'error_type': type(error).__name__, 'attempts': 2}
        if isinstance(error, SocWriteError):
            state['code'] = error.code
        return state


def build_failure_writeback(run):
    # 只传阶段与错误类别，避免异常文本带出连接凭据；详细证据留在本地运行目录。
    body = {'runId': run['run_id'], 'errorType': run.get('error_type', run['status']),
            'error': f"{run['status']}: {run.get('error_type', 'no deliverable result')}",
            'resultJson': copy.deepcopy({k: v for k, v in run.items() if k != 'delivery'}),
            'agentName': 'threat-analysis'}
    if run.get('model'):
        body['model'] = run['model']
    return body


def tool_data(response):
    if response.get('error') or not isinstance(response.get('result'), dict):
        raise ValueError('persistence MCP protocol error')
    result = response['result']
    if result.get('isError'):
        raise ValueError('persistence MCP tool error')
    try:
        body = json.loads(next(c['text'] for c in result.get('content', []) if c.get('type') == 'text'))
    except (ValueError, StopIteration, KeyError, TypeError):
        raise ValueError('persistence MCP invalid result') from None
    if not isinstance(body, dict) or str(body.get('code')) != '200' or not isinstance(body.get('data'), dict):
        raise ValueError('persistence MCP business error')
    return body['data']


class PersistenceClient:
    def __init__(self, url):
        self.url = url
        self.headers = {'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream'}
        self.initialized = False
        self.sequence = 0

    def rpc(self, method, params, notification=False):
        self.sequence += 1
        payload = {'jsonrpc': '2.0', 'method': method, 'params': params}
        if not notification:
            payload['id'] = self.sequence
        request = urllib.request.Request(self.url, data=json.dumps(payload, ensure_ascii=False).encode('utf-8'), headers=self.headers)
        with urllib.request.urlopen(request, timeout=30) as response:
            if response.headers.get('Mcp-Session-Id'):
                self.headers['Mcp-Session-Id'] = response.headers['Mcp-Session-Id']
            body = response.read().decode('utf-8')
            if notification:
                return {}
            if response.headers.get('Content-Type', '').startswith('text/event-stream'):
                for event in body.split('\n\n'):
                    data = '\n'.join(line[5:].lstrip() for line in event.splitlines() if line.startswith('data:'))
                    if data:
                        value = json.loads(data)
                        if value.get('id') == payload['id']:
                            return value
                raise ValueError('persistence MCP missing response')
            return json.loads(body)

    def save(self, arguments):
        if not self.initialized:
            response = self.rpc('initialize', {'protocolVersion': '2025-11-25', 'capabilities': {},
                                               'clientInfo': {'name': 'threat-analysis', 'version': '1.0'}})
            if response.get('error') or not response.get('result', {}).get('protocolVersion'):
                raise ValueError('persistence MCP initialization failed')
            self.headers['MCP-Protocol-Version'] = response['result']['protocolVersion']
            self.rpc('notifications/initialized', {}, notification=True)
            self.initialized = True
        return tool_data(self.rpc('tools/call', {'name': 'save_persistence_result', 'arguments': arguments}))


def persist(run, report_html, url):
    client = PersistenceClient(url)
    common = {'businessId': run['run_id'], 'sourceModule': 'threat-analysis', 'revision': 1}
    states = {'summary': {'status': 'not_configured'}}
    try:
        if len(report_html.encode('utf-8')) > LIMIT:
            raise ValueError('reportHtml exceeds 1048576 UTF-8 bytes')
        args = dict(common, resultType='report', contentType='text/html',
                    fileName=run['incident_id'] + '-' + run['run_id'] + '.html',
                    fileContentBase64=base64.b64encode(report_html.encode('utf-8')).decode('ascii'))
        data = client.save(args)
        if not isinstance(data.get('id'), str) or not data['id']:
            raise ValueError('persistence MCP missing storage id')
        state = {'status': 'saved', 'id': data['id']}
        url_value = data.get('downloadUrl')
        if isinstance(url_value, str):
            parsed = urllib.parse.urlsplit(url_value)
            if parsed.scheme in ('http', 'https') and parsed.netloc:
                state['download_url'] = url_value
        states['report'] = state
    except Exception as error:
        # 不回显网络异常中的地址或认证信息；保存失败不改变研判结论。
        states['report'] = {'status': 'failed', 'error_type': type(error).__name__}
        if isinstance(error, ValueError):
            states['report']['error'] = str(error)
    return states

